-- Refuse to run anywhere but the expected current shape: all 68 old tables,
-- nothing else in public (a stray view over an old table would block the
-- drops in step 19 — e.g. the golden harness's old_concept_* views), the roles
-- the trailer grants to, and the TS-1 app schema.
DO $$
DECLARE
  missing text;
  extra   text;
BEGIN
  SELECT string_agg(r, ', ' ORDER BY r) INTO missing
  FROM unnest(ARRAY['mwf_app', 'mwf_job', 'mwf_ops', 'mwf_auth']) AS r
  WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = r);
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'target_shape: database role(s) % do not exist', missing
      USING HINT = 'Apply infra/aws/roles.sql first (see migration 20261019173038_phase3_app_schema_helpers).';
  END IF;
  IF NOT pg_catalog.pg_has_role(current_user, 'mwf_job', 'SET') THEN
    RAISE EXCEPTION 'target_shape: role % cannot SET ROLE mwf_job (needed to hand the app.* helpers to mwf_job)', current_user;
  END IF;
  IF to_regnamespace('app') IS NULL THEN
    RAISE EXCEPTION 'target_shape: schema app is missing (migration 20261019173038_phase3_app_schema_helpers not applied)';
  END IF;
  IF to_regnamespace('app_migration') IS NOT NULL THEN
    RAISE EXCEPTION 'target_shape: schema app_migration already exists (a previous run''s verification schema; TS-8 drops it)';
  END IF;
  SELECT string_agg(t, ', ' ORDER BY t) INTO missing
  FROM unnest(ARRAY['User', 'Relationship', 'RelationshipMember', 'Session', 'InnerWorkSession', 'InnerWorkMessage', 'SessionTakeaway', 'TakeawayLink', 'StageProgress', 'UserVessel', 'UserEvent', 'EmotionalReading', 'IdentifiedNeed', 'Boundary', 'UserDocument', 'SharedVessel', 'ConsentedContent', 'CommonGround', 'Agreement', 'ConsentRecord', 'Message', 'PreSessionMessage', 'EmpathyDraft', 'EmpathyAttempt', 'EmpathyValidation', 'ReconcilerResult', 'ReconcilerShareOffer', 'RefinementAttemptCounter', 'StrategyProposal', 'StrategyProposalNeed', 'Stage4ProposalSelection', 'Stage4ProposalRevision', 'Stage4NeedCoverage', 'Stage4NeedDeclination', 'Stage4Closure', 'Stage4SubChat', 'Stage4SubChatMessage', 'TendingEntry', 'TendingCheckin', 'TendingCoordinationCycle', 'TendingResponse', 'TendingEntryOutcome', 'TendingNeedOutcome', 'TendingReminder', 'TendingAdjustment', 'TendingBetweenPeriodNote', 'TendingResponsePartialClosure', 'StrategyRanking', 'EmotionalExerciseCompletion', 'GlobalLibraryItem', 'Invitation', 'UserMemory', 'Need', 'NeedScore', 'NeedsAssessmentState', 'Person', 'PersonMention', 'Insight', 'RecurringTheme', 'GratitudeEntry', 'GratitudePreferences', 'MeditationSession', 'MeditationStats', 'MeditationFavorite', 'MeditationPreferences', 'SavedMeditation', 'BrainActivity', 'ValidationFeedbackDraft']::text[]) AS t
  WHERE to_regclass(format('public.%I', t)) IS NULL;
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'target_shape: not at the expected current shape; missing table(s): %', missing;
  END IF;
  SELECT string_agg(c.relname, ', ' ORDER BY c.relname) INTO extra
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p', 'v', 'm', 'f')
    AND c.relname <> ALL (ARRAY['User', 'Relationship', 'RelationshipMember', 'Session', 'InnerWorkSession', 'InnerWorkMessage', 'SessionTakeaway', 'TakeawayLink', 'StageProgress', 'UserVessel', 'UserEvent', 'EmotionalReading', 'IdentifiedNeed', 'Boundary', 'UserDocument', 'SharedVessel', 'ConsentedContent', 'CommonGround', 'Agreement', 'ConsentRecord', 'Message', 'PreSessionMessage', 'EmpathyDraft', 'EmpathyAttempt', 'EmpathyValidation', 'ReconcilerResult', 'ReconcilerShareOffer', 'RefinementAttemptCounter', 'StrategyProposal', 'StrategyProposalNeed', 'Stage4ProposalSelection', 'Stage4ProposalRevision', 'Stage4NeedCoverage', 'Stage4NeedDeclination', 'Stage4Closure', 'Stage4SubChat', 'Stage4SubChatMessage', 'TendingEntry', 'TendingCheckin', 'TendingCoordinationCycle', 'TendingResponse', 'TendingEntryOutcome', 'TendingNeedOutcome', 'TendingReminder', 'TendingAdjustment', 'TendingBetweenPeriodNote', 'TendingResponsePartialClosure', 'StrategyRanking', 'EmotionalExerciseCompletion', 'GlobalLibraryItem', 'Invitation', 'UserMemory', 'Need', 'NeedScore', 'NeedsAssessmentState', 'Person', 'PersonMention', 'Insight', 'RecurringTheme', 'GratitudeEntry', 'GratitudePreferences', 'MeditationSession', 'MeditationStats', 'MeditationFavorite', 'MeditationPreferences', 'SavedMeditation', 'BrainActivity', 'ValidationFeedbackDraft', '_prisma_migrations']::text[]);
  IF extra IS NOT NULL THEN
    RAISE EXCEPTION 'target_shape: unexpected relation(s) in schema public: %', extra
      USING HINT = 'Drop harness views (old_concept_*) and any ad-hoc tables before migrating.';
  END IF;
END
