-- ============================================================================
-- 2a. Migration workspace (schema app_migration) and step 0 row counts
-- ============================================================================

-- app_migration holds what the after-phase verify script (TS-8) reads —
-- shape_map, row_counts, report — and is dropped by TS-8 as its last step
-- (ruling R14). No grants to mwf_app. The work tables and helper functions are
-- dropped at the end of this migration.
CREATE SCHEMA app_migration;
REVOKE ALL ON SCHEMA app_migration FROM PUBLIC;
COMMENT ON SCHEMA app_migration IS
  'target_shape migration bookkeeping (shape_map, row_counts, report) for verify-target-migration.sql (TS-8), which drops this schema.';

-- Every id the migration minted (plan §3 id policy), keyed by what it replaces.
CREATE TABLE app_migration.shape_map (
  concept text NOT NULL,
  old_key text NOT NULL,
  new_id  uuid NOT NULL,
  PRIMARY KEY (concept, old_key)
);
-- Row counts: phase 'before' = the 68 old tables (step 0), 'after' = the 47 new ones (step 18).
CREATE TABLE app_migration.row_counts (
  phase      text   NOT NULL,
  table_name text   NOT NULL,
  n          bigint NOT NULL,
  PRIMARY KEY (phase, table_name)
);
-- Listed-not-fatal items: dropped rows, added rows, tie-breaks taken, mapping counts.
CREATE TABLE app_migration.report (
  seq    bigserial PRIMARY KEY,
  step   text   NOT NULL,
  item   text   NOT NULL,
  n      bigint NOT NULL,
  detail text
);

-- User-written text the target has no column for (ruling R-c): kept here,
-- never silently dropped, for the owner to decide at TS-14. No grants.
CREATE TABLE app_migration.dropped_content (
  concept    text NOT NULL,
  session_id uuid,
  user_id    uuid,
  text       text NOT NULL,
  written_at timestamptz
);

-- Work tables (dropped at the end of the migration).
CREATE TABLE app_migration.precheck (
  check_name text NOT NULL,
  offender   text NOT NULL,
  detail     text
);
CREATE TABLE app_migration.ab_slot (
  session_id     uuid    NOT NULL,
  slot           text    NOT NULL CHECK (slot IN ('A', 'B')),
  participant_id uuid    NOT NULL,
  tied           boolean NOT NULL,
  PRIMARY KEY (session_id, slot)
);
-- Old facts the trailer's view-based assertions compare against (the old tables are gone by then).
CREATE TABLE app_migration.old_closure (
  session_id              uuid PRIMARY KEY,
  shared_agreement_ids    uuid[] NOT NULL,
  individual_proposal_ids uuid[] NOT NULL,
  open_need_ids           uuid[] NOT NULL
);
CREATE TABLE app_migration.old_cycle (
  follow_up_id uuid PRIMARY KEY,
  cycle_id     uuid NOT NULL,
  status       text NOT NULL
);
-- Old (check-in, entry) pairs → new follow_up_checkin rows (step 14).
CREATE TABLE app_migration.checkin_map (
  checkin_id   uuid,            -- NULL for a synthetic check-in (orphan TendingResponse)
  entry_id     uuid NOT NULL,
  user_id      uuid NOT NULL,
  session_id   uuid NOT NULL,
  submitted_at timestamptz NOT NULL,
  is_first     boolean NOT NULL, -- the row that carries the check-in's entry-less children
  new_id       uuid NOT NULL UNIQUE,
  UNIQUE (entry_id, user_id)
);

CREATE FUNCTION app_migration.as_uuid(v text) RETURNS uuid
  LANGUAGE sql IMMUTABLE
  AS $$ SELECT CASE WHEN v ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v::uuid END $$;

-- JSON null (Prisma JsonNull) is SQL NULL in the target.
CREATE FUNCTION app_migration.jnull(j jsonb) RETURNS jsonb
  LANGUAGE sql IMMUTABLE
  AS $$ SELECT CASE WHEN jsonb_typeof(j) = 'null' THEN NULL ELSE j END $$;

-- An ISO timestamp inside a gate document; NULL when absent or not a timestamp.
CREATE FUNCTION app_migration.ts(j jsonb) RETURNS timestamptz
  LANGUAGE sql STABLE
  AS $$ SELECT CASE WHEN jsonb_typeof(j) = 'string' AND pg_input_is_valid(j #>> '{}', 'timestamptz')
                    THEN (j #>> '{}')::timestamptz END $$;

-- uuidv7 whose embedded time is ts (as the uuid migration minted ids).
CREATE FUNCTION app_migration.mint(ts timestamptz) RETURNS uuid
  LANGUAGE sql VOLATILE
  AS $$ SELECT uuidv7(coalesce(ts, clock_timestamp()) - clock_timestamp()) $$;

CREATE FUNCTION app_migration.assert(ok boolean, msg text) RETURNS void
  LANGUAGE plpgsql
  AS $$ BEGIN IF ok IS NOT TRUE THEN RAISE EXCEPTION 'target_shape: %', msg; END IF; END $$;

-- An enum mapping met a value it has no target for.
CREATE FUNCTION app_migration.unmapped(what text, v text) RETURNS text
  LANGUAGE plpgsql
  AS $$ BEGIN RAISE EXCEPTION 'target_shape: unmapped value % for %', v, what; END $$;

CREATE FUNCTION app_migration.note(p_step text, p_item text, p_n bigint, p_detail text DEFAULT NULL) RETURNS void
  LANGUAGE sql
  AS $$ INSERT INTO app_migration.report (step, item, n, detail) VALUES (p_step, p_item, p_n, p_detail) $$;

-- Step 0: row counts of all 68 old tables.
DO $$
DECLARE
  t text;
  n bigint;
BEGIN
  FOREACH t IN ARRAY ARRAY['User', 'Relationship', 'RelationshipMember', 'Session', 'InnerWorkSession', 'InnerWorkMessage', 'SessionTakeaway', 'TakeawayLink', 'StageProgress', 'UserVessel', 'UserEvent', 'EmotionalReading', 'IdentifiedNeed', 'Boundary', 'UserDocument', 'SharedVessel', 'ConsentedContent', 'CommonGround', 'Agreement', 'ConsentRecord', 'Message', 'PreSessionMessage', 'EmpathyDraft', 'EmpathyAttempt', 'EmpathyValidation', 'ReconcilerResult', 'ReconcilerShareOffer', 'RefinementAttemptCounter', 'StrategyProposal', 'StrategyProposalNeed', 'Stage4ProposalSelection', 'Stage4ProposalRevision', 'Stage4NeedCoverage', 'Stage4NeedDeclination', 'Stage4Closure', 'Stage4SubChat', 'Stage4SubChatMessage', 'TendingEntry', 'TendingCheckin', 'TendingCoordinationCycle', 'TendingResponse', 'TendingEntryOutcome', 'TendingNeedOutcome', 'TendingReminder', 'TendingAdjustment', 'TendingBetweenPeriodNote', 'TendingResponsePartialClosure', 'StrategyRanking', 'EmotionalExerciseCompletion', 'GlobalLibraryItem', 'Invitation', 'UserMemory', 'Need', 'NeedScore', 'NeedsAssessmentState', 'Person', 'PersonMention', 'Insight', 'RecurringTheme', 'GratitudeEntry', 'GratitudePreferences', 'MeditationSession', 'MeditationStats', 'MeditationFavorite', 'MeditationPreferences', 'SavedMeditation', 'BrainActivity', 'ValidationFeedbackDraft']::text[] LOOP
    EXECUTE format('SELECT count(*) FROM public.%I', t) INTO n;
    INSERT INTO app_migration.row_counts VALUES ('before', t, n);
  END LOOP;
END
$$;

CREATE TABLE app_migration.su (
  session_id uuid NOT NULL,
  user_id    uuid NOT NULL,
  source     text NOT NULL
);
-- Every (session, user) pair any old row names (plan step 4: the participant
-- set; the plan's union, extended to every old userId + sessionId pair so its
-- assertion "every pair resolves to exactly one participant" can hold). Text
-- ids that are not uuid-shaped drop out here and are reported by the step-17
-- precheck. Users with no "User" row are the vanished members (step 4a).
INSERT INTO app_migration.su (session_id, user_id, source)
SELECT DISTINCT session_id, user_id, source FROM (
  SELECT "sessionId" AS session_id, "userId" AS user_id, 'StageProgress' AS source FROM "StageProgress"
  UNION ALL SELECT "sessionId", "userId", 'UserVessel' FROM "UserVessel"
  UNION ALL SELECT "sessionId", "userId", 'EmpathyDraft' FROM "EmpathyDraft"
  UNION ALL SELECT "sessionId", "userId", 'Stage4ProposalSelection' FROM "Stage4ProposalSelection"
  UNION ALL SELECT "sessionId", "userId", 'TendingCheckin' FROM "TendingCheckin"
  UNION ALL SELECT "sessionId", app_migration.as_uuid("forUserId"), 'Message.forUserId' FROM "Message"
  UNION ALL SELECT "sessionId", "senderId", 'Message.senderId' FROM "Message"
  UNION ALL SELECT s.id, m."userId", 'RelationshipMember'
    FROM "Session" s JOIN "RelationshipMember" m ON m."relationshipId" = s."relationshipId"
  UNION ALL SELECT "sessionId", "sourceUserId", 'EmpathyAttempt' FROM "EmpathyAttempt"
  UNION ALL SELECT "sessionId", "userId", 'EmpathyValidation' FROM "EmpathyValidation"
  UNION ALL SELECT "sessionId", app_migration.as_uuid("guesserId"), 'ReconcilerResult.guesserId' FROM "ReconcilerResult"
  UNION ALL SELECT "sessionId", app_migration.as_uuid("subjectId"), 'ReconcilerResult.subjectId' FROM "ReconcilerResult"
  UNION ALL SELECT r."sessionId", app_migration.as_uuid(o."userId"), 'ReconcilerShareOffer.userId'
    FROM "ReconcilerShareOffer" o JOIN "ReconcilerResult" r ON r.id = o."resultId"
  UNION ALL SELECT "sessionId", "userId", 'ConsentRecord.userId' FROM "ConsentRecord"
  UNION ALL SELECT "sessionId", "requestedByUserId", 'ConsentRecord.requestedByUserId' FROM "ConsentRecord"
  UNION ALL SELECT "sessionId", "createdByUserId", 'StrategyProposal.createdByUserId' FROM "StrategyProposal"
  UNION ALL SELECT "sessionId", "removedByUserId", 'StrategyProposal.removedByUserId' FROM "StrategyProposal"
  UNION ALL SELECT "sessionId", "userId", 'StrategyRanking' FROM "StrategyRanking"
  UNION ALL SELECT p."sessionId", app_migration.as_uuid(r."actorUserId"), 'Stage4ProposalRevision.actorUserId'
    FROM "Stage4ProposalRevision" r JOIN "StrategyProposal" p ON p.id = r."proposalId"
  UNION ALL SELECT "sessionId", app_migration.as_uuid("userId"), 'Stage4NeedDeclination.userId' FROM "Stage4NeedDeclination"
  UNION ALL SELECT "sessionId", app_migration.as_uuid("closedByUserId"), 'Stage4Closure.closedByUserId' FROM "Stage4Closure"
  UNION ALL SELECT "sessionId", "userId", 'Stage4SubChat' FROM "Stage4SubChat"
  UNION ALL SELECT "sessionId", app_migration.as_uuid("ownerUserId"), 'TendingEntry.ownerUserId' FROM "TendingEntry"
  UNION ALL SELECT e."sessionId", r."userId", 'TendingResponse'
    FROM "TendingResponse" r JOIN "TendingEntry" e ON e.id = r."tendingEntryId"
  UNION ALL SELECT e."sessionId", o."userId", 'TendingEntryOutcome'
    FROM "TendingEntryOutcome" o JOIN "TendingEntry" e ON e.id = o."tendingEntryId"
  UNION ALL SELECT "sessionId", app_migration.as_uuid("sourceUserId"), 'TendingNeedOutcome.sourceUserId' FROM "TendingNeedOutcome"
  UNION ALL SELECT "sessionId", "userId", 'TendingReminder' FROM "TendingReminder"
  UNION ALL SELECT "sessionId", "userId", 'TendingAdjustment' FROM "TendingAdjustment"
  UNION ALL SELECT "sessionId", "userId", 'TendingBetweenPeriodNote' FROM "TendingBetweenPeriodNote"
  UNION ALL SELECT "sessionId", "createdByUserId", 'TendingCoordinationCycle.createdByUserId' FROM "TendingCoordinationCycle"
  UNION ALL SELECT "sessionId", "userId", 'EmotionalExerciseCompletion' FROM "EmotionalExerciseCompletion"
  UNION ALL SELECT "sessionId", "userId", 'ValidationFeedbackDraft' FROM "ValidationFeedbackDraft"
  UNION ALL SELECT "sessionId", "invitedById", 'Invitation.invitedById' FROM "Invitation"
  UNION ALL SELECT v."sessionId", v."userId", 'EmotionalReading'
    FROM "EmotionalReading" e JOIN "UserVessel" v ON v.id = e."vesselId"
) x
WHERE session_id IS NOT NULL AND user_id IS NOT NULL;
CREATE INDEX ON app_migration.su (session_id, user_id);

-- The distinct pairs, and the vanished users among them (no "User" row).
CREATE VIEW app_migration.pair AS
  SELECT DISTINCT session_id, user_id FROM app_migration.su;
CREATE VIEW app_migration.vanished AS
  SELECT DISTINCT su.user_id FROM app_migration.su
  WHERE NOT EXISTS (SELECT 1 FROM "User" u WHERE u.id = su.user_id);

CREATE TABLE app_migration.empathy_attempt_src AS
SELECT a.id, a."draftId", a."sessionId",
       coalesce(a."sourceUserId",
         CASE WHEN (SELECT count(*) FROM "EmpathyAttempt" o WHERE o."sessionId" = a."sessionId" AND o."sourceUserId" IS NULL) = 1
              THEN (SELECT CASE WHEN count(*) = 1 THEN min(v.user_id::text)::uuid END
                    FROM app_migration.vanished v JOIN app_migration.pair p ON p.user_id = v.user_id AND p.session_id = a."sessionId"
                    WHERE NOT EXISTS (SELECT 1 FROM "EmpathyAttempt" o WHERE o."sessionId" = a."sessionId" AND o."sourceUserId" = v.user_id))
         END) AS "sourceUserId",
       (a."sourceUserId" IS NULL) AS author_recovered,
       a.content, a."sharedAt", a."consentRecordId", a.status, a."statusVersion", a."revealedAt", a."revisionCount",
       a."deliveryStatus", a."deliveredAt", a."seenAt"
FROM "EmpathyAttempt" a;
CREATE TABLE app_migration.empathy_validation_src AS
SELECT v.id, v."attemptId", v."sessionId",
       coalesce(v."userId",
         (SELECT CASE WHEN count(DISTINCT p.user_id) = 1 THEN min(p.user_id::text)::uuid END
          FROM app_migration.pair p JOIN app_migration.empathy_attempt_src a ON a.id = v."attemptId"
          WHERE p.session_id = v."sessionId" AND p.user_id IS DISTINCT FROM a."sourceUserId")) AS "userId",
       (v."userId" IS NULL) AS reviewer_recovered,
       v.validated, v.feedback, v."feedbackShared", v."validatedAt"
FROM "EmpathyValidation" v;

-- ============================================================================
-- 2b. Prechecks (plan step 0b)
-- ============================================================================

-- P01 live_sessions_per_relationship (A-Q3 partial unique)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'live_sessions_per_relationship', "relationshipId"::text, string_agg(id::text, ', ' ORDER BY id)
FROM "Session"
WHERE status NOT IN ('RESOLVED', 'ABANDONED', 'ARCHIVED')
GROUP BY "relationshipId"
HAVING count(*) > 1;

-- P02 ai_message_with_sender (target message role/sender CHECK, P3 §6)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'ai_message_with_sender', id::text, role::text
FROM "Message"
WHERE role IN ('AI', 'SYSTEM') AND "senderId" IS NOT NULL;

-- P03 agreement_without_proposal (agreement.proposal_id NOT NULL, P1-10)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'agreement_without_proposal', id::text, status::text
FROM "Agreement"
WHERE "proposalId" IS NULL;

-- P04 dropped_proposed_agreement_in_use (PROPOSED dropped unless both agreed, P1-10)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'dropped_proposed_agreement_in_use', a.id::text, 'tending entries: ' || string_agg(e.id::text, ', ' ORDER BY e.id)
FROM "Agreement" a
JOIN "TendingEntry" e ON e."agreementId" = a.id
WHERE a.status = 'PROPOSED' AND NOT (a."agreedByA" AND a."agreedByB")
GROUP BY a.id;

-- P05 user_name_mismatch (user.name becomes GENERATED, P2)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'user_name_mismatch', id::text,
       format('name=%L generated=%L', name, nullif(trim(coalesce("firstName", '') || ' ' || coalesce("lastName", '')), ''))
FROM "User"
WHERE name IS DISTINCT FROM nullif(trim(coalesce("firstName", '') || ' ' || coalesce("lastName", '')), '');

-- P06a gates_not_object
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'gates_not_object', id::text, jsonb_typeof("gatesSatisfied")
FROM "StageProgress"
WHERE "gatesSatisfied" IS NOT NULL AND jsonb_typeof("gatesSatisfied") NOT IN ('object', 'null');

-- P06b unknown_gate_key (step 7 key table; unknown key = unmodelled state)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'unknown_gate_key', sp.id::text, k
FROM "StageProgress" sp
CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(sp."gatesSatisfied") = 'object' THEN sp."gatesSatisfied" ELSE '{}'::jsonb END) AS k
WHERE k <> ALL (ARRAY['agreementConfirmed', 'agreementCreated', 'compactSigned', 'compactSignedAt', 'confirmedAt', 'coveredNeedIds', 'currentNeedId', 'empathyExchanged', 'empathyExchangedAt', 'empathyValidated', 'feedback', 'feelHeardCheckOffered', 'feelHeardConfirmed', 'feelHeardConfirmedAt', 'finalEmotionalReading', 'invitationSent', 'needsCaptured', 'needsCapturedAt', 'needsConfirmed', 'needsIdentified', 'needsIdentifiedAt', 'needsRevealReviewedAt', 'needsShared', 'needsValidated', 'needsValidatedAt', 'own', 'partner', 'partnerConsented', 'partnerValidated', 'phase', 'rankingSubmitted', 'rankingSubmittedAt', 'readyAt', 'readyToRank', 'selectionSubmitted', 'selectionSubmittedAt', 'sharedAt', 'signedAt', 'skipReason', 'skippedNeedIds', 'skippedRefinement', 'stage4Walkthrough', 'strategiesRanked', 'validatedAt', 'willingToAccept']::text[]);

-- P06c walkthrough_shape (stage4Walkthrough → need_disposition)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'walkthrough_shape', sp.id::text, coalesce(k, jsonb_typeof(w))
FROM "StageProgress" sp
CROSS JOIN LATERAL (SELECT sp."gatesSatisfied" -> 'stage4Walkthrough' AS w) x
LEFT JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(w) = 'object' THEN w ELSE '{}'::jsonb END) AS k ON true
WHERE jsonb_typeof(sp."gatesSatisfied") = 'object' AND w IS NOT NULL AND jsonb_typeof(w) <> 'null'
  AND (jsonb_typeof(w) <> 'object'
       OR k <> ALL (ARRAY['phase', 'currentNeedId', 'coveredNeedIds', 'skippedNeedIds', 'updatedAt', 'updatedFrom', 'lastAction', 'lastReason']::text[])
       OR jsonb_typeof(coalesce(w -> 'coveredNeedIds', '[]')) <> 'array'
       OR jsonb_typeof(coalesce(w -> 'skippedNeedIds', '[]')) <> 'array');

-- P06d gate_timestamp_unparseable
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'gate_timestamp_unparseable', sp.id::text, k || '=' || (sp."gatesSatisfied" ->> k)
FROM "StageProgress" sp
CROSS JOIN unnest(ARRAY['signedAt', 'compactSignedAt', 'feelHeardConfirmedAt', 'confirmedAt', 'validatedAt', 'empathyExchangedAt', 'needsIdentifiedAt', 'needsValidatedAt', 'needsRevealReviewedAt', 'sharedAt', 'selectionSubmittedAt', 'needsCapturedAt', 'rankingSubmittedAt', 'readyAt']::text[]) AS k
WHERE jsonb_typeof(sp."gatesSatisfied") = 'object'
  AND jsonb_typeof(sp."gatesSatisfied" -> k) NOT IN ('null')
  AND app_migration.ts(sp."gatesSatisfied" -> k) IS NULL;

-- P07a consent_target_type (arc: 4 old types map to the target arc)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'consent_target_type', id::text, "targetType"::text
FROM "ConsentRecord"
WHERE "targetType" NOT IN ('IDENTIFIED_NEED', 'EMPATHY_ATTEMPT', 'EMPATHY_DRAFT', 'STRATEGY_PROPOSAL');

-- P07b consent_target_unresolved (targetId must resolve, P0-3)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'consent_target_unresolved', c.id::text, c."targetType"::text || ':' || coalesce(c."targetId", 'NULL')
FROM "ConsentRecord" c
WHERE c."targetType" IN ('IDENTIFIED_NEED', 'EMPATHY_ATTEMPT', 'EMPATHY_DRAFT', 'STRATEGY_PROPOSAL')
  AND NOT CASE c."targetType"
    WHEN 'IDENTIFIED_NEED' THEN EXISTS (SELECT 1 FROM "IdentifiedNeed" n WHERE n.id = app_migration.as_uuid(c."targetId"))
    WHEN 'EMPATHY_ATTEMPT' THEN EXISTS (SELECT 1 FROM app_migration.empathy_attempt_src a WHERE a.id = app_migration.as_uuid(c."targetId"))
    WHEN 'EMPATHY_DRAFT' THEN
         EXISTS (SELECT 1 FROM app_migration.empathy_attempt_src a WHERE a.id = app_migration.as_uuid(c."targetId") OR a."draftId" = app_migration.as_uuid(c."targetId"))
      OR EXISTS (SELECT 1 FROM "EmpathyDraft" d JOIN app_migration.empathy_attempt_src a ON a."sessionId" = d."sessionId" AND a."sourceUserId" = d."userId"
                 WHERE d.id = app_migration.as_uuid(c."targetId"))
    WHEN 'STRATEGY_PROPOSAL' THEN EXISTS (SELECT 1 FROM "StrategyProposal" p WHERE p.id = app_migration.as_uuid(c."targetId"))
  END;

-- P08 ab_slot_tie_with_split_agreement (P1-8: a joinedAt tie decides A/B only when agreedByA <> agreedByB)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'ab_slot_tie_with_split_agreement', s.id::text, 'agreements: ' || string_agg(a.id::text, ', ' ORDER BY a.id)
FROM "Session" s
JOIN "SharedVessel" sv ON sv."sessionId" = s.id
JOIN "Agreement" a ON a."sharedVesselId" = sv.id AND a."agreedByA" <> a."agreedByB"
WHERE (SELECT count(*) FROM (
         SELECT m."joinedAt" FROM "RelationshipMember" m WHERE m."relationshipId" = s."relationshipId"
         ORDER BY m."joinedAt", m.ctid LIMIT 2) two
       HAVING count(DISTINCT "joinedAt") = 1 AND count(*) = 2) IS NOT NULL
GROUP BY s.id;

-- P10 dropped_table_not_empty (census §2: unpopulated; dropping content is never silent)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'dropped_table_not_empty', table_name, n::text || ' row(s)'
FROM app_migration.row_counts
WHERE phase = 'before' AND n > 0 AND table_name = ANY (ARRAY['UserEvent', 'Boundary', 'UserDocument', 'PreSessionMessage', 'GlobalLibraryItem', 'CommonGround']::text[]);

-- P11 relationship_role (text → relationship_role enum)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'relationship_role', "relationshipId"::text || ':' || "userId"::text, role
FROM "RelationshipMember"
WHERE role NOT IN ('member', 'owner');

-- P12 session_resolved_without_resolved_at (CHECK status <> RESOLVED OR resolved_at)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'session_resolved_without_resolved_at', id::text, NULL
FROM "Session"
WHERE status = 'RESOLVED' AND "resolvedAt" IS NULL;

-- P13 session_without_two_participants (the step-4a assertion, checked before any copy; T-cardinality-1)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'session_without_two_participants', s.id::text,
       s.status::text || ', participants: ' || coalesce((SELECT string_agg(DISTINCT p.user_id::text, ', ') FROM app_migration.pair p WHERE p.session_id = s.id), 'none')
FROM "Session" s
WHERE s.status IN ('ACTIVE', 'WAITING', 'PAUSED', 'RESOLVED')
  AND (SELECT count(DISTINCT p.user_id) FROM app_migration.pair p WHERE p.session_id = s.id) < 2
  AND NOT (s.status <> 'RESOLVED'
           AND EXISTS (SELECT 1 FROM app_migration.pair p JOIN app_migration.vanished v USING (user_id) WHERE p.session_id = s.id));

-- P14a invitation_accepted_without_accepted_at (CHECK, P3 §6)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'invitation_accepted_without_accepted_at', id::text, NULL
FROM "Invitation"
WHERE status = 'ACCEPTED' AND "acceptedAt" IS NULL;

-- P14b invitation_accepted_without_unique_acceptor (accepted_by_user_id = the one non-inviter participant, vanished ones included)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'invitation_accepted_without_unique_acceptor', i.id::text,
       (SELECT count(DISTINCT p.user_id) FROM app_migration.pair p WHERE p.session_id = i."sessionId" AND p.user_id <> i."invitedById")::text
       || ' non-inviter participant(s)'
FROM "Invitation" i
WHERE i.status = 'ACCEPTED'
  AND (SELECT count(DISTINCT p.user_id) FROM app_migration.pair p WHERE p.session_id = i."sessionId" AND p.user_id <> i."invitedById") <> 1;

-- P15a attempt_without_author (empathy_attempt.author NOT NULL; not recoverable from vanished-member evidence)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'attempt_without_author', id::text, NULL
FROM app_migration.empathy_attempt_src
WHERE "sourceUserId" IS NULL;

-- P15b attempt_without_unique_subject (step 11: subject = the other participant; RAISE if N≠2)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'attempt_without_unique_subject', a.id::text,
       (SELECT count(DISTINCT p.user_id) FROM app_migration.pair p WHERE p.session_id = a."sessionId" AND p.user_id <> a."sourceUserId")::text
       || ' other participant(s)'
FROM app_migration.empathy_attempt_src a
WHERE a."sourceUserId" IS NOT NULL
  AND (SELECT count(DISTINCT p.user_id) FROM app_migration.pair p WHERE p.session_id = a."sessionId" AND p.user_id <> a."sourceUserId") <> 1;

-- P15c empathy_draft_without_unique_subject (draft.about_participant_id = the other participant)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'empathy_draft_without_unique_subject', d.id::text,
       (SELECT count(DISTINCT p.user_id) FROM app_migration.pair p WHERE p.session_id = d."sessionId" AND p.user_id <> d."userId")::text
       || ' other participant(s)'
FROM "EmpathyDraft" d
WHERE (SELECT count(DISTINCT p.user_id) FROM app_migration.pair p WHERE p.session_id = d."sessionId" AND p.user_id <> d."userId") <> 1;

-- P15d attempt_revealed_without_revealed_at (CHECK REVEALED/VALIDATED → revealed_at)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'attempt_revealed_without_revealed_at', id::text, status::text
FROM app_migration.empathy_attempt_src
WHERE status IN ('REVEALED', 'VALIDATED') AND "revealedAt" IS NULL;

-- P16a validation_without_reviewer (empathy_review.reviewer NOT NULL; not recoverable as the attempt subject)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'validation_without_reviewer', id::text, NULL
FROM app_migration.empathy_validation_src
WHERE "userId" IS NULL;

-- P16b validation_reviewer_is_author (reviewer = the subject of the attempt)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'validation_reviewer_is_author', v.id::text, NULL
FROM app_migration.empathy_validation_src v JOIN app_migration.empathy_attempt_src a ON a.id = v."attemptId"
WHERE v."userId" = a."sourceUserId";

-- P16c validation_draft_without_partner_attempt (draft(VALIDATION_FEEDBACK).attempt = the attempt of the partner)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'validation_draft_without_partner_attempt', d.id::text,
       (SELECT count(*) FROM app_migration.empathy_attempt_src a WHERE a."sessionId" = d."sessionId" AND a."sourceUserId" <> d."userId")::text || ' partner attempt(s)'
FROM "ValidationFeedbackDraft" d
WHERE (SELECT count(*) FROM app_migration.empathy_attempt_src a WHERE a."sessionId" = d."sessionId" AND a."sourceUserId" <> d."userId") <> 1;

-- P17a reconciler_result_without_attempt (result → attempt by (session, guesser))
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'reconciler_result_without_attempt', r.id::text, r."guesserId"
FROM "ReconcilerResult" r
WHERE NOT EXISTS (SELECT 1 FROM app_migration.empathy_attempt_src a
                  WHERE a."sessionId" = r."sessionId" AND a."sourceUserId" = app_migration.as_uuid(r."guesserId"));

-- P17b reconciler_result_two_current (sql_result_one_current)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'reconciler_result_two_current', "sessionId"::text || ':' || "guesserId" || '->' || "subjectId",
       string_agg(id::text, ', ' ORDER BY id)
FROM "ReconcilerResult"
WHERE "supersededAt" IS NULL
GROUP BY "sessionId", "guesserId", "subjectId"
HAVING count(*) > 1;

-- P17c reconciler_result_duplicate_iteration (UNIQUE (attempt_id, iteration))
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'reconciler_result_duplicate_iteration', "sessionId"::text || ':' || "guesserId" || ' #' || iteration,
       string_agg(id::text, ', ' ORDER BY id)
FROM "ReconcilerResult"
GROUP BY "sessionId", "guesserId", iteration
HAVING count(*) > 1;

-- P17d reconciler_result_enum (gap_severity / recommender_action)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'reconciler_result_enum', id::text, format('gapSeverity=%L recommendedAction=%L', "gapSeverity", "recommendedAction")
FROM "ReconcilerResult"
WHERE upper("gapSeverity") NOT IN ('NONE', 'MINOR', 'MODERATE', 'SIGNIFICANT')
   OR "recommendedAction" NOT IN ('PROCEED', 'OFFER_OPTIONAL', 'OFFER_SHARING');

-- P17e reconciler_result_self (CHECK author <> subject)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'reconciler_result_self', id::text, NULL
FROM "ReconcilerResult"
WHERE "guesserId" = "subjectId";

-- P17f reconciler_result_score_range (CHECK alignment_score 0..100)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'reconciler_result_score_range', id::text, "alignmentScore"::text
FROM "ReconcilerResult"
WHERE "alignmentScore" NOT BETWEEN 0 AND 100;

-- P18a share_offer_status_dates (CHECK ACCEPTED ⇔ shared_at, DECLINED ⇔ declined_at)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'share_offer_status_dates', id::text, format('status=%s sharedAt=%s declinedAt=%s', status, "sharedAt", "declinedAt")
FROM "ReconcilerShareOffer"
WHERE (status = 'ACCEPTED') <> ("sharedAt" IS NOT NULL)
   OR (status = 'DECLINED') <> ("declinedAt" IS NOT NULL);

-- P18b share_offer_user_not_subject (context_share_offer.subject = result.subject)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'share_offer_user_not_subject', o.id::text, o."userId" || ' <> ' || r."subjectId"
FROM "ReconcilerShareOffer" o JOIN "ReconcilerResult" r ON r.id = o."resultId"
WHERE o."userId" <> r."subjectId";

-- P18c share_offer_duplicate_iteration (UNIQUE (attempt_id, iteration))
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'share_offer_duplicate_iteration', r."sessionId"::text || ':' || r."guesserId" || ' #' || o.iteration,
       string_agg(o.id::text, ', ' ORDER BY o.id)
FROM "ReconcilerShareOffer" o JOIN "ReconcilerResult" r ON r.id = o."resultId"
GROUP BY r."sessionId", r."guesserId", o.iteration
HAVING count(*) > 1;

-- P19a consent_decision_undated (CHECK (decision IS NULL) = (decided_at IS NULL), P3 §6)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'consent_decision_undated', id::text, format('decision=%s decidedAt=%s', decision, "decidedAt")
FROM "ConsentRecord"
WHERE (decision IS NULL) <> ("decidedAt" IS NULL);

-- P19b consent_revoked_not_revoked (CHECK revoked_at IS NULL OR decision = REVOKED)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'consent_revoked_not_revoked', id::text, format('decision=%s', decision)
FROM "ConsentRecord"
WHERE "revokedAt" IS NOT NULL AND decision IS DISTINCT FROM 'REVOKED';

-- P20a consented_content_target (need_share.need_id via consentRecordId → ConsentRecord.targetId)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'consented_content_target', cc.id::text, cr."targetType"::text || ':' || coalesce(cr."targetId", 'NULL')
FROM "ConsentedContent" cc JOIN "ConsentRecord" cr ON cr.id = cc."consentRecordId"
WHERE cr."targetType" <> 'IDENTIFIED_NEED'
   OR NOT EXISTS (SELECT 1 FROM "IdentifiedNeed" n WHERE n.id = app_migration.as_uuid(cr."targetId"))
   OR (cc."originalNeedId" IS NOT NULL AND cc."originalNeedId" IS DISTINCT FROM app_migration.as_uuid(cr."targetId"));

-- P20b consented_content_duplicate_need (need_share PK need_id)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'consented_content_duplicate_need', cr."targetId", string_agg(cc.id::text, ', ' ORDER BY cc.id)
FROM "ConsentedContent" cc JOIN "ConsentRecord" cr ON cr.id = cc."consentRecordId"
GROUP BY cr."targetId"
HAVING count(*) > 1;

-- P20c consented_content_revocation (inactive needs revokedAt; CHECK revoked_at >= shared_at)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'consented_content_revocation', id::text, format('consentActive=%s revokedAt=%s consentedAt=%s', "consentActive", "revokedAt", "consentedAt")
FROM "ConsentedContent"
WHERE (NOT "consentActive" AND "revokedAt" IS NULL) OR "revokedAt" < "consentedAt";

-- P20d consented_content_session (session of the need owner = SharedVessel session)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'consented_content_session', cc.id::text, NULL
FROM "ConsentedContent" cc
JOIN "ConsentRecord" cr ON cr.id = cc."consentRecordId"
JOIN "SharedVessel" sv ON sv.id = cc."sharedVesselId"
JOIN "IdentifiedNeed" n ON n.id = app_migration.as_uuid(cr."targetId")
JOIN "UserVessel" uv ON uv.id = n."vesselId"
WHERE uv."sessionId" <> sv."sessionId";

-- P21 proposal_removed_dates (CHECK (status = REMOVED) = (removed_at IS NOT NULL))
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'proposal_removed_dates', id::text, format('status=%s removedAt=%s', status, "removedAt")
FROM "StrategyProposal"
WHERE (status = 'REMOVED') <> ("removedAt" IS NOT NULL);

-- P22a agreement_duplicate_proposal (UNIQUE agreement.proposal_id)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'agreement_duplicate_proposal', "proposalId"::text, string_agg(id::text, ', ' ORDER BY id)
FROM "Agreement"
WHERE "proposalId" IS NOT NULL AND (status <> 'PROPOSED' OR ("agreedByA" AND "agreedByB"))
GROUP BY "proposalId"
HAVING count(*) > 1;

-- P22b agreement_parties_incomplete (T-agreement-parties: every participant is a party)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'agreement_parties_incomplete', id::text, format('status=%s agreedByA=%s agreedByB=%s', status, "agreedByA", "agreedByB")
FROM "Agreement"
WHERE status <> 'PROPOSED' AND NOT ("agreedByA" AND "agreedByB");

-- P22c agreement_party_not_willing (T-agreement-parties: every party WILLING)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'agreement_party_not_willing', a.id::text, 'NOT_WILLING selection ' || s.id::text
FROM "Agreement" a
JOIN "Stage4ProposalSelection" s ON s."proposalId" = a."proposalId" AND s.decision = 'NOT_WILLING'
WHERE a.status <> 'PROPOSED' OR (a."agreedByA" AND a."agreedByB");

-- P23a revision_action_unknown (action → revision_action, upper snake)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'revision_action_unknown', id::text, action
FROM "Stage4ProposalRevision"
WHERE upper(regexp_replace(regexp_replace(action, '([a-z0-9])([A-Z])', '\1_\2', 'g'), '[^A-Za-z0-9]+', '_', 'g'))
      NOT IN ('CREATED', 'REVISED', 'REMOVED', 'RESTORED', 'CONVERTED', 'CAPTURE_SKIPPED', 'COVERED', 'SUBCHAT_REFINED');

-- P23b revision_session_mismatch (sessionId asserted = that of the proposal, then dropped)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'revision_session_mismatch', r.id::text, r."sessionId" || ' <> ' || p."sessionId"::text
FROM "Stage4ProposalRevision" r JOIN "StrategyProposal" p ON p.id = r."proposalId"
WHERE r."sessionId" <> p."sessionId"::text;

-- P23c revision_json_not_object (CHECK jsonb_typeof(before/after) = object)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'revision_json_not_object', id::text, format('before=%s after=%s', jsonb_typeof(before), jsonb_typeof(after))
FROM "Stage4ProposalRevision"
WHERE coalesce(jsonb_typeof(before), 'null') NOT IN ('object', 'null')
   OR coalesce(jsonb_typeof(after), 'null') NOT IN ('object', 'null');

-- P24a follow_up_scope_owner (CHECK (scope = INDIVIDUAL) = (owner IS NOT NULL))
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'follow_up_scope_owner', id::text, format('scope=%s ownerUserId=%s', scope, "ownerUserId")
FROM "TendingEntry"
WHERE (scope = 'INDIVIDUAL') <> ("ownerUserId" IS NOT NULL);

-- P24b reminder_status_unknown (text → reminder_status)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'reminder_status_unknown', id::text, status
FROM "TendingReminder"
WHERE status NOT IN ('SCHEDULED', 'DELIVERED', 'CANCELLED');

-- P24c checkin_without_entry (a check-in must land on a follow_up)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'checkin_without_entry', c.id::text, NULL
FROM "TendingCheckin" c
WHERE NOT EXISTS (SELECT 1 FROM "TendingCoordinationCycle" y WHERE y.id = c."coordinationCycleId" AND cardinality(y."entryIds") > 0)
  AND NOT EXISTS (SELECT 1 FROM "TendingResponse" r WHERE r."checkinId" = c.id)
  AND NOT EXISTS (SELECT 1 FROM "TendingEntryOutcome" o WHERE o."checkinId" = c.id)
  AND NOT EXISTS (SELECT 1 FROM "TendingAdjustment" a WHERE a."checkinId" = c.id);

-- P24d checkin_entry_duplicate (UNIQUE follow_up_checkin (follow_up_id, participant_id))
INSERT INTO app_migration.precheck (check_name, offender, detail)
WITH covers AS (
  SELECT c.id AS checkin_id, c."userId" AS user_id, e AS entry_id
  FROM "TendingCheckin" c
  JOIN "TendingCoordinationCycle" y ON y.id = c."coordinationCycleId"
  CROSS JOIN unnest(y."entryIds") AS e
  UNION SELECT r."checkinId", r."userId", r."tendingEntryId" FROM "TendingResponse" r WHERE r."checkinId" IS NOT NULL
  UNION SELECT o."checkinId", o."userId", o."tendingEntryId" FROM "TendingEntryOutcome" o
  UNION SELECT a."checkinId", a."userId", a."tendingEntryId" FROM "TendingAdjustment" a
)
SELECT 'checkin_entry_duplicate', entry_id::text || ':' || user_id::text, string_agg(DISTINCT checkin_id::text, ', ')
FROM covers
GROUP BY entry_id, user_id
HAVING count(DISTINCT checkin_id) > 1;

-- P24e cycle_entry_unknown (TendingCoordinationCycle.entryIds must be entries)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'cycle_entry_unknown', y.id::text, e::text
FROM "TendingCoordinationCycle" y CROSS JOIN unnest(y."entryIds") AS e
WHERE NOT EXISTS (SELECT 1 FROM "TendingEntry" t WHERE t.id = e);

-- P25 text_id_not_uuid (step 17: every resolved value cast to uuid)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'text_id_not_uuid', id::text, 'Message.forUserId=' || "forUserId"
FROM "Message" WHERE "forUserId" IS NOT NULL AND app_migration.as_uuid("forUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'ReconcilerResult.guesserId=' || "guesserId"
FROM "ReconcilerResult" WHERE "guesserId" IS NOT NULL AND app_migration.as_uuid("guesserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'ReconcilerResult.subjectId=' || "subjectId"
FROM "ReconcilerResult" WHERE "subjectId" IS NOT NULL AND app_migration.as_uuid("subjectId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'ReconcilerShareOffer.userId=' || "userId"
FROM "ReconcilerShareOffer" WHERE "userId" IS NOT NULL AND app_migration.as_uuid("userId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'Stage4NeedDeclination.userId=' || "userId"
FROM "Stage4NeedDeclination" WHERE "userId" IS NOT NULL AND app_migration.as_uuid("userId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'Stage4NeedDeclination.needId=' || "needId"
FROM "Stage4NeedDeclination" WHERE "needId" IS NOT NULL AND app_migration.as_uuid("needId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'Stage4ProposalRevision.actorUserId=' || "actorUserId"
FROM "Stage4ProposalRevision" WHERE "actorUserId" IS NOT NULL AND app_migration.as_uuid("actorUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'Stage4Closure.closedByUserId=' || "closedByUserId"
FROM "Stage4Closure" WHERE "closedByUserId" IS NOT NULL AND app_migration.as_uuid("closedByUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'TendingEntry.ownerUserId=' || "ownerUserId"
FROM "TendingEntry" WHERE "ownerUserId" IS NOT NULL AND app_migration.as_uuid("ownerUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'TendingNeedOutcome.sourceUserId=' || "sourceUserId"
FROM "TendingNeedOutcome" WHERE "sourceUserId" IS NOT NULL AND app_migration.as_uuid("sourceUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'ConsentRecord.targetId=' || "targetId"
FROM "ConsentRecord" WHERE "targetId" IS NOT NULL AND app_migration.as_uuid("targetId") IS NULL;

-- P26 declination_need_unresolved (step 17: Stage4NeedDeclination.needId found)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'declination_need_unresolved', d.id::text, d."needId"
FROM "Stage4NeedDeclination" d
WHERE app_migration.as_uuid(d."needId") IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "IdentifiedNeed" n WHERE n.id = app_migration.as_uuid(d."needId"));

-- P27 intensity_out_of_range (intensity domain 1..10)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'intensity_out_of_range', id::text, 'EmotionalReading.intensity=' || intensity
FROM "EmotionalReading" WHERE intensity NOT BETWEEN 1 AND 10
UNION ALL
SELECT 'intensity_out_of_range', id::text, format('EmotionalExerciseCompletion before=%s after=%s', "intensityBefore", "intensityAfter")
FROM "EmotionalExerciseCompletion"
WHERE "intensityBefore" NOT BETWEEN 1 AND 10 OR "intensityAfter" NOT BETWEEN 1 AND 10;

-- P28a summary_not_json_object (conversationSummary text → jsonb, RAISE on invalid JSON)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'summary_not_json_object', 'UserVessel:' || id::text, left("conversationSummary", 60)
FROM "UserVessel"
WHERE "conversationSummary" IS NOT NULL
  AND (NOT pg_input_is_valid("conversationSummary", 'jsonb') OR jsonb_typeof("conversationSummary"::jsonb) <> 'object'
       OR NOT ("conversationSummary"::jsonb ?& ARRAY['text', 'messageCount', 'generatedAt']))
UNION ALL
SELECT 'summary_not_json_object', 'InnerWorkSession:' || id::text, left("conversationSummary", 60)
FROM "InnerWorkSession"
WHERE "conversationSummary" IS NOT NULL
  AND (NOT pg_input_is_valid("conversationSummary", 'jsonb') OR jsonb_typeof("conversationSummary"::jsonb) <> 'object');

-- P28b facts_shape (ai_memory *_FACTS doc requires a facts array)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'facts_shape', 'UserVessel:' || id::text, jsonb_typeof("notableFacts")
FROM "UserVessel"
WHERE app_migration.jnull("notableFacts") IS NOT NULL
  AND jsonb_typeof("notableFacts") <> 'array'
  AND NOT (jsonb_typeof("notableFacts") = 'object' AND jsonb_typeof("notableFacts" -> 'facts') = 'array')
UNION ALL
SELECT 'facts_shape', 'User:' || id::text, jsonb_typeof("globalFacts")
FROM "User"
WHERE app_migration.jnull("globalFacts") IS NOT NULL
  AND jsonb_typeof("globalFacts") <> 'array'
  AND NOT (jsonb_typeof("globalFacts") = 'object' AND jsonb_typeof("globalFacts" -> 'facts') = 'array');

-- P28c jsonb_not_container (CHECK jsonb_typeof on every jsonb column)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'jsonb_not_container', 'BrainActivity:' || id::text,
       format('input=%s output=%s metadata=%s structuredOutput=%s', jsonb_typeof(input), jsonb_typeof(output), jsonb_typeof(metadata), jsonb_typeof("structuredOutput"))
FROM "BrainActivity"
WHERE coalesce(jsonb_typeof(input), 'null') NOT IN ('object', 'array', 'null')
   OR coalesce(jsonb_typeof(output), 'null') NOT IN ('object', 'array', 'null')
   OR coalesce(jsonb_typeof(metadata), 'null') NOT IN ('object', 'array', 'null')
   OR coalesce(jsonb_typeof("structuredOutput"), 'null') NOT IN ('object', 'array', 'null')
UNION ALL
SELECT 'jsonb_not_container', 'User:' || id::text,
       format('memory=%s notifications=%s privacy=%s', jsonb_typeof("memoryPreferences"), jsonb_typeof("notificationPreferences"), jsonb_typeof("privacyPreferences"))
FROM "User"
WHERE coalesce(jsonb_typeof("memoryPreferences"), 'null') NOT IN ('object', 'null')
   OR coalesce(jsonb_typeof("notificationPreferences"), 'null') NOT IN ('object', 'null')
   OR coalesce(jsonb_typeof("privacyPreferences"), 'null') NOT IN ('object', 'null');

-- P29 inner_work_message_role (reflection_message.role is USER/AI/SYSTEM)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'inner_work_message_role', id::text, role::text
FROM "InnerWorkMessage"
WHERE role NOT IN ('USER', 'AI', 'SYSTEM');

-- P30 need_confidence_range (CHECK ai_confidence 0..1)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'need_confidence_range', id::text, "aiConfidence"::text
FROM "IdentifiedNeed"
WHERE "aiConfidence" NOT BETWEEN 0 AND 1;

-- P31 takeaway_link_self (CHECK source_id <> target_id)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'takeaway_link_self', id::text, NULL
FROM "TakeawayLink"
WHERE "sourceId" = "targetId";

-- P32 brain_cost_overflow (cost numeric(10,6))
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'brain_cost_overflow', id::text, cost::text
FROM "BrainActivity"
WHERE abs(cost) >= 10000;

-- P33 message_without_owner (no forUserId and no senderId, in a session without a vanished member)
INSERT INTO app_migration.precheck (check_name, offender, detail)
SELECT 'message_without_owner', m.id::text, m.role::text || ' @ ' || m.timestamp::text
FROM "Message" m
WHERE m."forUserId" IS NULL AND m."senderId" IS NULL
  AND NOT EXISTS (SELECT 1 FROM app_migration.pair p JOIN app_migration.vanished v USING (user_id) WHERE p.session_id = m."sessionId");


-- The single verdict: every failing precheck at once, with ids.
DO $$
DECLARE
  r   record;
  msg text := '';
  total bigint;
BEGIN
  SELECT count(*) INTO total FROM app_migration.precheck;
  IF total = 0 THEN
    RETURN;
  END IF;
  FOR r IN
    SELECT check_name, count(*) AS n,
           string_agg(offender || coalesce(' (' || detail || ')', ''), '; ' ORDER BY offender) FILTER (WHERE rn <= 10) AS sample
    FROM (SELECT p.*, row_number() OVER (PARTITION BY check_name ORDER BY offender) AS rn FROM app_migration.precheck p) x
    GROUP BY check_name
    ORDER BY check_name
  LOOP
    msg := msg || E'\n  ' || r.check_name || ' x' || r.n || ': ' || r.sample;
  END LOOP;
  RAISE EXCEPTION 'target_shape: % precheck offender(s); the database is unchanged:%', total, msg
    USING HINT = 'Fix the data with backend/scripts/target-shape/fix-data.template.sql (one block per check name) and re-run.';
END
$$;

-- ============================================================================
-- 3a. Steps 1–3: user, relationship, session
-- ============================================================================

-- ---- Step 1: user (identity), user_device, user_preferences, ai_memory(GLOBAL_FACTS)
-- user.name is still the plain column Prisma created; the trailer replaces it
-- with the GENERATED one (sql-only.sql §1), which the P05 precheck proved equal.
INSERT INTO "user" (id, clerk_id, email, first_name, last_name, deleted_at, created_at, updated_at)
SELECT id, "clerkId", email, "firstName", "lastName", NULL, "createdAt", "updatedAt"
FROM "User";

-- One device row per user that has a push token or biometric enrolment (a user
-- with neither has no device to record). platform is unknown → NULL.
WITH ins AS (
  INSERT INTO user_device (id, user_id, push_token, platform, biometric_enabled, biometric_enrolled_at, last_seen_at, created_at, updated_at)
  SELECT app_migration.mint(u."createdAt"), u.id, u."pushToken", NULL, u."biometricEnabled", u."biometricEnrolledAt", NULL, u."createdAt", u."updatedAt"
  FROM "User" u
  WHERE u."pushToken" IS NOT NULL OR u."biometricEnabled" OR u."biometricEnrolledAt" IS NOT NULL
  ORDER BY u."createdAt", u.id
  RETURNING id, user_id
)
INSERT INTO app_migration.shape_map SELECT 'user_device', user_id::text, id FROM ins;

-- Defaults (shared/src/dto/auth.ts DEFAULT_*_PREFERENCES) under the stored keys.
INSERT INTO user_preferences (user_id, doc, created_at, updated_at)
SELECT u.id,
       jsonb_build_object(
         'memory',        '{"sessionContinuity":true,"crossSessionRecall":false,"patternInsights":false,"rememberAgreements":true}'::jsonb || coalesce(app_migration.jnull(u."memoryPreferences"), '{}'::jsonb),
         'notifications', '{"pushEnabled":true,"emailEnabled":false,"newInvitations":true,"partnerActions":true,"followUpReminders":true}'::jsonb || coalesce(app_migration.jnull(u."notificationPreferences"), '{}'::jsonb),
         'privacy',       '{"showActivityStatus":true,"allowSessionInvites":true,"analyticsOptOut":false}'::jsonb || coalesce(app_migration.jnull(u."privacyPreferences"), '{}'::jsonb)),
       u."createdAt", u."updatedAt"
FROM "User" u;

-- globalFacts: the object shape {facts, consolidatedAt, sessionCount} wins
-- (spec §1.1 ai_memory); a bare array is wrapped as {facts}.
WITH ins AS (
  INSERT INTO ai_memory (id, participant_id, user_id, kind, doc, created_at, updated_at)
  SELECT app_migration.mint(u."updatedAt"), NULL, u.id, 'GLOBAL_FACTS',
         CASE WHEN jsonb_typeof(u."globalFacts") = 'array' THEN jsonb_build_object('facts', u."globalFacts") ELSE u."globalFacts" END,
         u."updatedAt", u."updatedAt"
  FROM "User" u
  WHERE app_migration.jnull(u."globalFacts") IS NOT NULL
  ORDER BY u."updatedAt", u.id
  RETURNING id, user_id
)
INSERT INTO app_migration.shape_map SELECT 'ai_memory:GLOBAL_FACTS', user_id::text, id FROM ins;

SELECT app_migration.assert(a = b, format('step 1: %s user rows for %s "User" rows', a, b))
FROM (SELECT (SELECT count(*) FROM "user") AS a, (SELECT count(*) FROM "User") AS b) x;
SELECT app_migration.assert(a = b, format('step 1: %s user_preferences rows for %s users', a, b))
FROM (SELECT (SELECT count(*) FROM user_preferences) AS a, (SELECT count(*) FROM "user") AS b) x;
SELECT app_migration.assert(a = b, format('step 1: %s GLOBAL_FACTS rows for %s users with globalFacts', a, b))
FROM (SELECT (SELECT count(*) FROM ai_memory WHERE kind = 'GLOBAL_FACTS') AS a,
             (SELECT count(*) FROM "User" WHERE app_migration.jnull("globalFacts") IS NOT NULL) AS b) x;
SELECT app_migration.note('1', 'User.lastMoodIntensity dropped (becomes v_participant.last_mood)', count(*))
FROM "User" WHERE "lastMoodIntensity" IS NOT NULL;

-- ---- Step 2: relationship, relationship_member (role text → enum; P11 checked the values)
INSERT INTO relationship (id, created_at, updated_at)
SELECT id, "createdAt", "updatedAt" FROM "Relationship";

INSERT INTO relationship_member (relationship_id, user_id, role, nickname, joined_at, created_at, updated_at)
SELECT "relationshipId", "userId", role::relationship_role, nickname, "joinedAt", "joinedAt", "joinedAt"
FROM "RelationshipMember";

SELECT app_migration.assert(a = b AND c = d, format('step 2: relationship %s/%s, relationship_member %s/%s', a, b, c, d))
FROM (SELECT (SELECT count(*) FROM relationship) AS a, (SELECT count(*) FROM "Relationship") AS b,
             (SELECT count(*) FROM relationship_member) AS c, (SELECT count(*) FROM "RelationshipMember") AS d) x;

-- ---- Step 3: session (WAITING → ACTIVE; PAUSED → ACTIVE + the paused milestone in step 7; type dropped)
INSERT INTO session (id, relationship_id, status, topic_frame, topic_frame_confirmed_at, previous_session_id, resolved_at, created_at, updated_at)
SELECT id, "relationshipId",
       (CASE status::text WHEN 'WAITING' THEN 'ACTIVE' WHEN 'PAUSED' THEN 'ACTIVE' ELSE status::text END)::session_status,
       "topicFrame", "topicFrameConfirmedAt", NULL, "resolvedAt", "createdAt", "updatedAt"
FROM "Session";
UPDATE session s SET previous_session_id = o."previousSessionId"
FROM "Session" o
WHERE o.id = s.id AND o."previousSessionId" IS NOT NULL;

SELECT app_migration.note('3', 'Session.status ' || status::text || ' → ACTIVE', count(*))
FROM "Session" WHERE status IN ('WAITING', 'PAUSED') GROUP BY status;
SELECT app_migration.note('3', 'Session.type ' || type::text || ' (column dropped)', count(*))
FROM "Session" WHERE type <> 'CONFLICT_RESOLUTION' GROUP BY type;
SELECT app_migration.assert(a = b, format('step 3: %s session rows for %s "Session" rows', a, b))
FROM (SELECT (SELECT count(*) FROM session) AS a, (SELECT count(*) FROM "Session") AS b) x;

-- ============================================================================
-- 3b. Steps 4, 4a, 5: participant, vanished members, A/B slots
-- ============================================================================

-- ---- Step 4a: vanished members (users hard-deleted under today's user.delete,
-- account-deletion.ts:160): each id named by a session's evidence with no
-- "User" row becomes a tombstone user with THE SAME id (so every text id that
-- named it still resolves) and a participant with left_at set.
WITH ins AS (
  INSERT INTO "user" (id, clerk_id, email, first_name, last_name, deleted_at, created_at, updated_at)
  SELECT v.user_id, NULL, 'deleted+' || v.user_id::text, NULL, NULL, now(), now(), now()
  FROM app_migration.vanished v
  ORDER BY v.user_id
  RETURNING id
)
INSERT INTO app_migration.shape_map SELECT 'tombstone_user', id::text, id FROM ins;
SELECT app_migration.note('4a', 'vanished member → tombstone user', count(*), string_agg(user_id::text, ', ' ORDER BY user_id))
FROM app_migration.vanished;

-- ---- Step 4: participant — one per distinct (session, user) any old row names.
-- joined_at = RelationshipMember.joinedAt, else the session's createdAt;
-- display_name = User.name (NULL for a tombstone).
WITH src AS (
  SELECT p.session_id, p.user_id, (v.user_id IS NOT NULL) AS vanished, u.name,
         coalesce((SELECT m."joinedAt" FROM "RelationshipMember" m
                   WHERE m."relationshipId" = s."relationshipId" AND m."userId" = p.user_id), s."createdAt") AS joined_at
  FROM app_migration.pair p
  JOIN "Session" s ON s.id = p.session_id
  LEFT JOIN app_migration.vanished v ON v.user_id = p.user_id
  LEFT JOIN "User" u ON u.id = p.user_id
), ins AS (
  INSERT INTO participant (id, session_id, user_id, kind, display_name, joined_at, left_at, created_at, updated_at)
  SELECT app_migration.mint(joined_at), session_id, user_id, 'human', CASE WHEN NOT vanished THEN name END,
         joined_at, CASE WHEN vanished THEN now() END, joined_at, CASE WHEN vanished THEN now() ELSE joined_at END
  FROM src
  ORDER BY src.joined_at, src.session_id, src.user_id
  RETURNING id, session_id, user_id
)
INSERT INTO app_migration.shape_map SELECT 'participant', session_id::text || ':' || user_id::text, id FROM ins;

-- A live session with a vanished member cannot continue: ABANDONED (4a).
WITH upd AS (
  UPDATE session s SET status = 'ABANDONED', updated_at = now()
  WHERE s.status NOT IN ('RESOLVED', 'ABANDONED', 'ARCHIVED')
    AND EXISTS (SELECT 1 FROM participant p WHERE p.session_id = s.id AND p.left_at IS NOT NULL)
  RETURNING s.id
)
SELECT app_migration.note('4a', 'live session with a vanished member → ABANDONED', count(*), string_agg(id::text, ', ' ORDER BY id)) FROM upd;

SELECT app_migration.assert(a = b, format('step 4: %s participants for %s distinct (session, user) pairs', a, b))
FROM (SELECT (SELECT count(*) FROM participant) AS a, (SELECT count(*) FROM app_migration.pair) AS b) x;
SELECT app_migration.assert(n = 0, format('step 4: %s (session, user) pair(s) resolve to no participant', n))
FROM (SELECT count(*) AS n FROM app_migration.pair p
      WHERE NOT EXISTS (SELECT 1 FROM participant x WHERE x.session_id = p.session_id AND x.user_id = p.user_id)) x;
SELECT app_migration.assert(n = 0, format('step 4a: %s ACTIVE/RESOLVED session(s) with fewer than 2 participants: %s', n, ids))
FROM (SELECT count(*) AS n, string_agg(s.id::text, ', ' ORDER BY s.id) AS ids
      FROM session s
      WHERE s.status IN ('ACTIVE', 'RESOLVED') AND (SELECT count(*) FROM participant p WHERE p.session_id = s.id) < 2) x;
SELECT app_migration.assert(n = 0, format('step 4a: %s ACTIVE session(s) without a live human participant (T-cardinality-1)', n))
FROM (SELECT count(*) AS n FROM session s
      WHERE s.status = 'ACTIVE'
        AND NOT EXISTS (SELECT 1 FROM participant p WHERE p.session_id = s.id AND p.kind = 'human' AND p.left_at IS NULL)) x;

-- ---- Step 5: A/B slots — getUserSlot order materialised once: first
-- RelationshipMember by joinedAt is A; tie-break joinedAt, ctid (physical
-- order, what Prisma returned on a tie). P08 refused the one case where a tie
-- matters (an agreement with agreedByA <> agreedByB).
INSERT INTO app_migration.ab_slot (session_id, slot, participant_id, tied)
SELECT session_id, CASE rn WHEN 1 THEN 'A' ELSE 'B' END, participant_id, tied
FROM (
  SELECT s.id AS session_id, p.id AS participant_id,
         row_number() OVER (PARTITION BY s.id ORDER BY m."joinedAt", m.ctid) AS rn,
         count(*) OVER (PARTITION BY s.id, m."joinedAt") > 1 AS tied
  FROM "Session" s
  JOIN "RelationshipMember" m ON m."relationshipId" = s."relationshipId"
  JOIN participant p ON p.session_id = s.id AND p.user_id = m."userId"
) x
WHERE rn <= 2;
-- A vanished member's RelationshipMember row cascaded with their deletion, so
-- the survivor alone was ranked above (review D2). Where the session has one
-- surviving member and one vanished participant, recover both slots: the
-- survivor is A when a surviving Invitation of the session was sent by them
-- (the inviter joins first), else B (the inviter's own invitation cascaded
-- with the inviter); the vanished participant takes the other slot. (Every
-- agreement that survives step 13 was agreed by both, so the slot decides who
-- is listed, never who agreed — P22b.)
CREATE TABLE app_migration.slot_fix AS
SELECT s.id AS session_id,
       (SELECT a.participant_id FROM app_migration.ab_slot a WHERE a.session_id = s.id) AS survivor,
       (SELECT p.id FROM participant p JOIN app_migration.vanished v USING (user_id) WHERE p.session_id = s.id) AS gone,
       CASE WHEN EXISTS (SELECT 1 FROM "Invitation" i JOIN app_migration.ab_slot a ON a.session_id = s.id
                         JOIN participant p ON p.id = a.participant_id
                         WHERE i."sessionId" = s.id AND i."invitedById" = p.user_id)
            THEN 'A' ELSE 'B' END AS survivor_slot
FROM "Session" s
WHERE (SELECT count(*) FROM app_migration.ab_slot a WHERE a.session_id = s.id) = 1
  AND (SELECT count(*) FROM participant p JOIN app_migration.vanished v USING (user_id) WHERE p.session_id = s.id) = 1;
DELETE FROM app_migration.ab_slot WHERE session_id IN (SELECT session_id FROM app_migration.slot_fix);
INSERT INTO app_migration.ab_slot (session_id, slot, participant_id, tied)
SELECT session_id, survivor_slot, survivor, false FROM app_migration.slot_fix
UNION ALL
SELECT session_id, CASE survivor_slot WHEN 'A' THEN 'B' ELSE 'A' END, gone, false FROM app_migration.slot_fix;
SELECT app_migration.note('5', 'A/B slots recovered for a session with a vanished member (survivor slot from the surviving invitation)', count(*))
FROM app_migration.slot_fix;
SELECT app_migration.note('5', 'A/B slot decided by the ctid tie-break (no split agreement)', count(DISTINCT session_id))
FROM app_migration.ab_slot WHERE tied;
SELECT app_migration.assert(n = 0, format('step 5: %s two-member session(s) without exactly one A and one B', n))
FROM (SELECT count(*) AS n FROM "Session" s
      WHERE (SELECT count(*) FROM "RelationshipMember" m WHERE m."relationshipId" = s."relationshipId") = 2
        AND (SELECT count(*) FROM app_migration.ab_slot a WHERE a.session_id = s.id) <> 2) x;

-- ============================================================================
-- 3c. Step 6: conversation, ai_memory
-- ============================================================================

-- ---- Step 6: conversation — one MAIN per participant (id minted at the
-- UserVessel's createdAt, else the participant's joined_at); ai_memory SUMMARY
-- and NOTABLE_FACTS from the vessel. Sub-chats follow the proposals below;
-- conversation_read_state follows the messages (its FK into message).
WITH src AS (
  SELECT p.id AS participant_id, coalesce(v."createdAt", p.joined_at) AS created_at, coalesce(v."updatedAt", p.joined_at) AS updated_at
  FROM participant p
  LEFT JOIN "UserVessel" v ON v."sessionId" = p.session_id AND v."userId" = p.user_id
), ins AS (
  INSERT INTO conversation (id, participant_id, kind, anchor_kind, anchor_proposal_id, status, resolved_at, created_at, updated_at)
  SELECT app_migration.mint(created_at), participant_id, 'MAIN', NULL, NULL, 'ACTIVE', NULL, created_at, updated_at
  FROM src
  ORDER BY src.created_at, src.participant_id
  RETURNING id, participant_id
)
INSERT INTO app_migration.shape_map SELECT 'conversation:MAIN', participant_id::text, id FROM ins;

WITH ins AS (
  INSERT INTO ai_memory (id, participant_id, user_id, kind, doc, created_at, updated_at)
  SELECT app_migration.mint(v."updatedAt"), p.id, NULL, 'SUMMARY', v."conversationSummary"::jsonb, v."updatedAt", v."updatedAt"
  FROM "UserVessel" v JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId"
  WHERE v."conversationSummary" IS NOT NULL
  ORDER BY v."updatedAt", v.id
  RETURNING id, participant_id
)
INSERT INTO app_migration.shape_map SELECT 'ai_memory:SUMMARY', participant_id::text, id FROM ins;

WITH ins AS (
  INSERT INTO ai_memory (id, participant_id, user_id, kind, doc, created_at, updated_at)
  SELECT app_migration.mint(v."updatedAt"), p.id, NULL, 'NOTABLE_FACTS',
         CASE WHEN jsonb_typeof(v."notableFacts") = 'array' THEN jsonb_build_object('facts', v."notableFacts") ELSE v."notableFacts" END,
         v."updatedAt", v."updatedAt"
  FROM "UserVessel" v JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId"
  WHERE app_migration.jnull(v."notableFacts") IS NOT NULL
  ORDER BY v."updatedAt", v.id
  RETURNING id, participant_id
)
INSERT INTO app_migration.shape_map SELECT 'ai_memory:NOTABLE_FACTS', participant_id::text, id FROM ins;

SELECT app_migration.assert(a = b, format('step 6: %s MAIN conversations for %s participants', a, b))
FROM (SELECT (SELECT count(*) FROM conversation WHERE kind = 'MAIN') AS a, (SELECT count(*) FROM participant) AS b) x;
SELECT app_migration.assert(n = 0, format('step 6: %s participant(s) without exactly one MAIN conversation', n))
FROM (SELECT count(*) AS n FROM participant p
      WHERE (SELECT count(*) FROM conversation c WHERE c.participant_id = p.id AND c.kind = 'MAIN') <> 1) x;
SELECT app_migration.assert(a = b, format('step 6: %s of %s UserVessel rows mapped to a participant', a, b))
FROM (SELECT (SELECT count(*) FROM "UserVessel" v JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId") AS a,
             (SELECT count(*) FROM "UserVessel") AS b) x;
SELECT app_migration.assert(a = b, format('step 6: %s SUMMARY rows for %s vessel summaries', a, b))
FROM (SELECT (SELECT count(*) FROM ai_memory WHERE kind = 'SUMMARY') AS a,
             (SELECT count(*) FROM "UserVessel" WHERE "conversationSummary" IS NOT NULL) AS b) x;
SELECT app_migration.assert(a = b, format('step 6: %s NOTABLE_FACTS rows for %s vessels with notableFacts', a, b))
FROM (SELECT (SELECT count(*) FROM ai_memory WHERE kind = 'NOTABLE_FACTS') AS a,
             (SELECT count(*) FROM "UserVessel" WHERE app_migration.jnull("notableFacts") IS NOT NULL) AS b) x;

-- ============================================================================
-- 3d. Milestone seed and step 7: participant_milestone
-- ============================================================================

-- ---- Milestone seed (needed before step 7: participant_milestone → milestone
-- is RESTRICT). The plan lists the seed in the trailer; the FK decides.
INSERT INTO milestone (key, ordinal, stage_label, scope, self_assertable) VALUES
  ('paused', 0, 'Paused', 'participant', false),
  ('invitation_sent', 10, 'Getting Started', 'participant', false),
  ('compact_signed', 20, 'Getting Started', 'session', true),
  ('feel_heard', 110, 'Your Story', 'participant', true),
  ('empathy_submitted', 210, 'Walking in Their Shoes', 'participant', false),
  ('empathy_ready', 220, 'Walking in Their Shoes', 'participant', false),
  ('empathy_validated', 230, 'Walking in Their Shoes', 'session', false),
  ('needs_confirmed', 310, 'What Matters Most', 'participant', true),
  ('needs_validated', 320, 'What Matters Most', 'session', false),
  ('needs_shared', 330, 'What Matters Most', 'session', false),
  ('repair_walkthrough_started', 410, 'What Comes Next', 'participant', false),
  ('choices_shared', 420, 'What Comes Next', 'session', true),
  ('closed', 430, 'What Comes Next', 'session', false);

-- ---- Step 7: participant_milestone from gatesSatisfied (key table in
-- gen/maps.ts), the terminal milestone of every COMPLETED stage, PAUSED, plus
-- two facts the fixtures encode outside gatesSatisfied (current-shape.ts
-- GATE_ENCODING "elsewhere"): empathy_submitted at EmpathyAttempt.sharedAt and
-- invitation_sent at Invitation.messageConfirmedAt. A milestone reached by
-- several sources keeps its earliest time.
CREATE TABLE app_migration.milestone_src AS
WITH sp AS (
  SELECT p.id AS participant_id, x.*,
         CASE WHEN jsonb_typeof(x."gatesSatisfied") = 'object' THEN x."gatesSatisfied" ELSE '{}'::jsonb END AS gates
  FROM "StageProgress" x JOIN participant p ON p.session_id = x."sessionId" AND p.user_id = x."userId"
)
SELECT * FROM (
  SELECT participant_id, 'compact_signed', coalesce(app_migration.ts(sp.gates -> 'signedAt'), app_migration.ts(sp.gates -> 'compactSignedAt'), sp."completedAt", sp."startedAt"), 'gate:compactSigned'
  FROM sp WHERE sp.gates -> 'compactSigned' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'invitation_sent', coalesce(sp."startedAt"), 'gate:invitationSent'
  FROM sp WHERE sp.gates -> 'invitationSent' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'feel_heard', coalesce(app_migration.ts(sp.gates -> 'feelHeardConfirmedAt'), app_migration.ts(sp.gates -> 'confirmedAt'), sp."completedAt", sp."startedAt"), 'gate:feelHeardConfirmed'
  FROM sp WHERE sp.gates -> 'feelHeardConfirmed' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'empathy_validated', coalesce(sp."completedAt", app_migration.ts(sp.gates -> 'validatedAt'), sp."startedAt"), 'gate:empathyValidated'
  FROM sp WHERE sp.gates -> 'empathyValidated' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'empathy_validated', coalesce(sp."completedAt", app_migration.ts(sp.gates -> 'empathyExchangedAt'), sp."startedAt"), 'gate:empathyExchanged'
  FROM sp WHERE sp.gates -> 'empathyExchanged' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'needs_confirmed', coalesce(app_migration.ts(sp.gates -> 'confirmedAt'), app_migration.ts(sp.gates -> 'needsIdentifiedAt'), sp."startedAt"), 'gate:needsConfirmed'
  FROM sp WHERE sp.gates -> 'needsConfirmed' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'needs_confirmed', coalesce(app_migration.ts(sp.gates -> 'needsIdentifiedAt'), sp."startedAt"), 'gate:needsIdentified'
  FROM sp WHERE sp.gates -> 'needsIdentified' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'needs_shared', coalesce(app_migration.ts(sp.gates -> 'sharedAt'), sp."completedAt", sp."startedAt"), 'gate:needsShared'
  FROM sp WHERE sp.gates -> 'needsShared' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'needs_validated', coalesce(app_migration.ts(sp.gates -> 'needsValidatedAt'), app_migration.ts(sp.gates -> 'needsRevealReviewedAt'), sp."startedAt"), 'gate:needsValidated'
  FROM sp WHERE sp.gates -> 'needsValidated' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'choices_shared', coalesce(app_migration.ts(sp.gates -> 'selectionSubmittedAt'), sp."startedAt"), 'gate:selectionSubmitted'
  FROM sp WHERE sp.gates -> 'selectionSubmitted' = 'true'::jsonb
  UNION ALL
  SELECT participant_id, 'repair_walkthrough_started',
         coalesce(app_migration.ts(sp.gates -> 'stage4Walkthrough' -> 'updatedAt'), sp."startedAt"), 'gate:stage4Walkthrough'
  FROM sp
  WHERE jsonb_typeof(sp.gates -> 'stage4Walkthrough') = 'object'
     OR (jsonb_typeof(sp.gates -> 'phase') = 'string' AND sp.gates ->> 'phase' <> 'INVENTORY')
  UNION ALL
  SELECT participant_id, (ARRAY['compact_signed', 'feel_heard', 'empathy_validated', 'needs_shared', 'choices_shared'])[sp.stage + 1], coalesce(sp."completedAt", sp."startedAt"), 'terminal:stage' || sp.stage
  FROM sp WHERE sp.status = 'COMPLETED' AND sp.stage BETWEEN 0 AND 4
  UNION ALL
  SELECT p.id, 'paused', s."updatedAt", 'Session.PAUSED'
  FROM "Session" s JOIN participant p ON p.session_id = s.id
  WHERE s.status = 'PAUSED' AND p.left_at IS NULL
  UNION ALL
  SELECT p.id, 'empathy_submitted', a."sharedAt", 'EmpathyAttempt.sharedAt'
  FROM app_migration.empathy_attempt_src a JOIN participant p ON p.session_id = a."sessionId" AND p.user_id = a."sourceUserId"
  UNION ALL
  SELECT p.id, 'invitation_sent', i."messageConfirmedAt", 'Invitation.messageConfirmedAt'
  FROM "Invitation" i JOIN participant p ON p.session_id = i."sessionId" AND p.user_id = i."invitedById"
  WHERE i."messageConfirmedAt" IS NOT NULL
) r (participant_id, milestone_key, reached_at, source);

INSERT INTO participant_milestone (participant_id, milestone_key, reached_at, created_at)
SELECT participant_id, milestone_key, min(reached_at), min(reached_at)
FROM app_migration.milestone_src
GROUP BY participant_id, milestone_key
ORDER BY 3, 1, 2;

SELECT app_migration.note('7', 'milestone source ' || source || ' → ' || milestone_key, count(*))
FROM app_migration.milestone_src GROUP BY source, milestone_key ORDER BY source, milestone_key;
INSERT INTO app_migration.dropped_content (concept, session_id, user_id, text, written_at)
SELECT 'StageProgress.gatesSatisfied.' || k, sp."sessionId", sp."userId", sp."gatesSatisfied" ->> k, coalesce(sp."completedAt", sp."startedAt")
FROM "StageProgress" sp CROSS JOIN unnest(ARRAY['skipReason', 'feedback']::text[]) AS k
WHERE jsonb_typeof(sp."gatesSatisfied") = 'object' AND app_migration.jnull(sp."gatesSatisfied" -> k) IS NOT NULL
ORDER BY sp.id, k;
SELECT app_migration.note('7', 'gatesSatisfied.' || k || ' (free text, no target column) → app_migration.dropped_content', count(*))
FROM "StageProgress" sp CROSS JOIN unnest(ARRAY['skipReason', 'feedback']::text[]) AS k
WHERE jsonb_typeof(sp."gatesSatisfied") = 'object' AND app_migration.jnull(sp."gatesSatisfied" -> k) IS NOT NULL
GROUP BY k;
SELECT app_migration.assert(n = 0, format('step 7: %s COMPLETED StageProgress row(s) without their terminal milestone', n))
FROM (SELECT count(*) AS n
      FROM "StageProgress" x JOIN participant p ON p.session_id = x."sessionId" AND p.user_id = x."userId"
      WHERE x.status = 'COMPLETED'
        AND NOT EXISTS (SELECT 1 FROM participant_milestone pm
                        WHERE pm.participant_id = p.id AND pm.milestone_key = (ARRAY['compact_signed', 'feel_heard', 'empathy_validated', 'needs_shared', 'choices_shared'])[x.stage + 1])) x;

-- ============================================================================
-- 3e. need, need_share (12), need_disposition (8), proposal (13), sub-chats (6)
-- ============================================================================

-- ---- need ← IdentifiedNeed (ids kept; owner = the vessel's participant).
-- confirmed has no timestamp: confirmed_at = createdAt when confirmed.
INSERT INTO need (id, participant_id, label, category, evidence, ai_confidence, confirmed_at, locked_at, superseded_by_need_id, deleted_at, created_at, updated_at)
SELECT n.id, p.id, n.need, n.category::text::need_category, coalesce(n.evidence, '{}'), n."aiConfidence"::real,
       CASE WHEN n.confirmed THEN n."createdAt" END, n."lockedAt", NULL, n."deletedAt", n."createdAt",
       greatest(n."createdAt", n."lockedAt", n."deletedAt")
FROM "IdentifiedNeed" n
JOIN "UserVessel" v ON v.id = n."vesselId"
JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId";
UPDATE need SET superseded_by_need_id = o."supersededByNeedId"
FROM "IdentifiedNeed" o WHERE o.id = need.id AND o."supersededByNeedId" IS NOT NULL;
SELECT app_migration.assert(a = b, format('needs: %s need rows for %s "IdentifiedNeed" rows', a, b))
FROM (SELECT (SELECT count(*) FROM need) AS a, (SELECT count(*) FROM "IdentifiedNeed") AS b) x;

-- ---- Step 12 (part): need_share ← ConsentedContent. need via consentRecordId
-- → ConsentRecord.targetId (originalNeedId was never written, census §3);
-- participant_id/session_id from the resolved need's owner (pass 2 N-1).
WITH ins AS (
  INSERT INTO need_share (need_id, participant_id, session_id, category, shared_text, shared_at, revoked_at, created_at, updated_at)
  SELECT n.id, n.participant_id, p.session_id, n.category, cc."transformedContent", cc."consentedAt", cc."revokedAt",
         cc."consentedAt", coalesce(cc."revokedAt", cc."consentedAt")
  FROM "ConsentedContent" cc
  JOIN "ConsentRecord" cr ON cr.id = cc."consentRecordId"
  JOIN need n ON n.id = app_migration.as_uuid(cr."targetId")
  JOIN participant p ON p.id = n.participant_id
  RETURNING need_id
)
SELECT app_migration.note('12', 'need_share from ConsentedContent', count(*)) FROM ins;
INSERT INTO app_migration.shape_map
SELECT 'need_share:ConsentedContent', cc.id::text, app_migration.as_uuid(cr."targetId")
FROM "ConsentedContent" cc JOIN "ConsentRecord" cr ON cr.id = cc."consentRecordId";
SELECT app_migration.assert(a = b, format('step 12: %s need_share rows for %s "ConsentedContent" rows', a, b))
FROM (SELECT (SELECT count(*) FROM need_share) AS a, (SELECT count(*) FROM "ConsentedContent") AS b) x;
SELECT app_migration.assert(n = 0, format('step 12: %s need_share row(s) whose participant_id/session_id is not the need owner''s (T-need-share-owner)', n))
FROM (SELECT count(*) AS n FROM need_share ns
      JOIN need n ON n.id = ns.need_id JOIN participant p ON p.id = n.participant_id
      WHERE ns.participant_id <> n.participant_id OR ns.session_id <> p.session_id) x;

-- ---- Step 8: need_disposition ← stage4Walkthrough {currentNeedId,
-- coveredNeedIds, skippedNeedIds} (stage4.ts:500, stream-turn-actions.ts:243;
-- the plan's top-level keys are read too) ∪ Stage4NeedDeclination (→ DECLINED),
-- for needs with a need_share row. Others are reported and dropped.
-- Precedence on one (participant, need): DECLINED > COVERED > SKIPPED > OPEN.
CREATE TABLE app_migration.disposition_ref AS
WITH walk AS (
  SELECT p.id AS participant_id, x."startedAt",
         CASE WHEN jsonb_typeof(x."gatesSatisfied" -> 'stage4Walkthrough') = 'object'
              THEN x."gatesSatisfied" -> 'stage4Walkthrough' ELSE x."gatesSatisfied" END AS w
  FROM "StageProgress" x JOIN participant p ON p.session_id = x."sessionId" AND p.user_id = x."userId"
  WHERE x.stage = 4 AND jsonb_typeof(x."gatesSatisfied") = 'object'
)
SELECT participant_id, need_text, status, is_current, at, source FROM (
  SELECT participant_id, e AS need_text, 'COVERED' AS status, false AS is_current,
         coalesce(app_migration.ts(w -> 'updatedAt'), "startedAt") AS at, 'coveredNeedIds' AS source
  FROM walk CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(w -> 'coveredNeedIds') = 'array' THEN w -> 'coveredNeedIds' ELSE '[]' END) e
  UNION ALL
  SELECT participant_id, e, 'SKIPPED', false, coalesce(app_migration.ts(w -> 'updatedAt'), "startedAt"), 'skippedNeedIds'
  FROM walk CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(w -> 'skippedNeedIds') = 'array' THEN w -> 'skippedNeedIds' ELSE '[]' END) e
  UNION ALL
  SELECT participant_id, w ->> 'currentNeedId', 'OPEN', true, coalesce(app_migration.ts(w -> 'updatedAt'), "startedAt"), 'currentNeedId'
  FROM walk WHERE jsonb_typeof(w -> 'currentNeedId') = 'string'
  UNION ALL
  SELECT p.id, d."needId", 'DECLINED', false, d."declinedAt", 'Stage4NeedDeclination'
  FROM "Stage4NeedDeclination" d JOIN participant p ON p.session_id = d."sessionId" AND p.user_id = app_migration.as_uuid(d."userId")
) r;

INSERT INTO need_disposition (participant_id, need_id, status, is_current, note, created_at, updated_at)
SELECT r.participant_id, ns.need_id,
       ((ARRAY['OPEN', 'SKIPPED', 'COVERED', 'DECLINED'])[max(array_position(ARRAY['OPEN', 'SKIPPED', 'COVERED', 'DECLINED'], r.status))])::need_disposition_status,
       bool_or(r.is_current), NULL, min(r.at), max(r.at)
FROM app_migration.disposition_ref r
JOIN need_share ns ON ns.need_id = app_migration.as_uuid(r.need_text)
GROUP BY r.participant_id, ns.need_id
ORDER BY 1, 2;

SELECT app_migration.note('8', 'disposition on a need without need_share (' || source || '): dropped', count(*),
                          string_agg(need_text, ', ' ORDER BY need_text))
FROM app_migration.disposition_ref r
WHERE NOT EXISTS (SELECT 1 FROM need_share ns WHERE ns.need_id = app_migration.as_uuid(r.need_text))
GROUP BY source;
SELECT app_migration.assert(n = 0, format('step 8: %s disposition reference(s) to a shared need did not land', n))
FROM (SELECT count(*) AS n FROM app_migration.disposition_ref r
      JOIN need_share ns ON ns.need_id = app_migration.as_uuid(r.need_text)
      WHERE NOT EXISTS (SELECT 1 FROM need_disposition d WHERE d.participant_id = r.participant_id AND d.need_id = ns.need_id)) x;
SELECT app_migration.note('8', 'Stage4NeedCoverage not copied (computed: v_need_coverage)', count(*)) FROM "Stage4NeedCoverage";
INSERT INTO app_migration.dropped_content (concept, session_id, user_id, text, written_at)
SELECT 'Stage4NeedCoverage.note', c."sessionId", app_migration.as_uuid(c."sourceUserId"), c.note, c."updatedAt"
FROM "Stage4NeedCoverage" c WHERE c.note IS NOT NULL ORDER BY c.id;

-- ---- Step 13 (part): proposal ← StrategyProposal (ids kept). needsAddressed
-- → proposal_need / unresolved_need_labels below; parentProposalId,
-- coverageSummary, consentRecordId, capturedFromMessageId dropped.
INSERT INTO proposal (id, session_id, created_by_participant_id, source, kind, status, description, duration, measure_of_success,
                      unresolved_need_labels, removed_at, removed_by_participant_id, removal_reason, shared_at, created_at, updated_at)
SELECT sp.id, sp."sessionId", pc.id, sp.source::text::proposal_source, sp.kind::text::proposal_kind, sp.status::text::proposal_status,
       sp.description, sp.duration, sp."measureOfSuccess", '{}', sp."removedAt", pr.id, sp."removalReason", NULL, sp."createdAt", sp."updatedAt"
FROM "StrategyProposal" sp
LEFT JOIN participant pc ON pc.session_id = sp."sessionId" AND pc.user_id = sp."createdByUserId"
LEFT JOIN participant pr ON pr.session_id = sp."sessionId" AND pr.user_id = sp."removedByUserId";
SELECT app_migration.assert(a = b, format('step 13: %s proposal rows for %s "StrategyProposal" rows', a, b))
FROM (SELECT (SELECT count(*) FROM proposal) AS a, (SELECT count(*) FROM "StrategyProposal") AS b) x;
SELECT app_migration.note('13', 'StrategyProposal.' || c || ' dropped', n)
FROM (SELECT 'parentProposalId' AS c, count(*) FILTER (WHERE "parentProposalId" IS NOT NULL) AS n FROM "StrategyProposal"
      UNION ALL SELECT 'coverageSummary', count(*) FILTER (WHERE app_migration.jnull("coverageSummary") IS NOT NULL) FROM "StrategyProposal"
      UNION ALL SELECT 'capturedFromMessageId', count(*) FILTER (WHERE "capturedFromMessageId" IS NOT NULL) FROM "StrategyProposal") x
WHERE n > 0;

-- Sub-chats (step 6, second half): SUBCHAT conversations ← Stage4SubChat (ids kept).
INSERT INTO conversation (id, participant_id, kind, anchor_kind, anchor_proposal_id, status, resolved_at, created_at, updated_at)
SELECT sc.id, p.id, 'SUBCHAT', sc."anchorKind"::text::subchat_anchor, pr.id, sc.status::text::conversation_status,
       sc."resolvedAt", sc."createdAt", coalesce(sc."resolvedAt", sc."createdAt")
FROM "Stage4SubChat" sc
JOIN participant p ON p.session_id = sc."sessionId" AND p.user_id = sc."userId"
LEFT JOIN proposal pr ON pr.id = app_migration.as_uuid(sc."anchorId");
SELECT app_migration.note('17', 'Stage4SubChat.anchorId that is not a proposal id (anchor_proposal_id NULL)', count(*))
FROM "Stage4SubChat" sc
WHERE sc."anchorId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "StrategyProposal" p WHERE p.id = app_migration.as_uuid(sc."anchorId"));
SELECT app_migration.assert(a = b, format('step 6: %s SUBCHAT conversations for %s "Stage4SubChat" rows', a, b))
FROM (SELECT (SELECT count(*) FROM conversation WHERE kind = 'SUBCHAT') AS a, (SELECT count(*) FROM "Stage4SubChat") AS b) x;

-- ============================================================================
-- 3f. Step 11: empathy attempts, reconciler, reviews
-- ============================================================================

-- ---- Step 11: empathy_attempt ← EmpathyAttempt (ids kept). author ←
-- sourceUserId; subject ← the one other participant (P15b refused N≠2);
-- round ← revisionCount + 1; ANALYZING → HELD, NEEDS_WORK → AWAITING_SHARING.
INSERT INTO empathy_attempt (id, author_participant_id, subject_participant_id, round, supersedes_attempt_id, content, status, status_version,
                             submitted_at, revealed_at, delivery_status, delivered_at, seen_at, created_at, updated_at)
SELECT a.id, pa.id, ps.id, a."revisionCount" + 1, NULL, a.content,
       (CASE a.status::text WHEN 'ANALYZING' THEN 'HELD' WHEN 'NEEDS_WORK' THEN 'AWAITING_SHARING' ELSE a.status::text END)::empathy_status,
       a."statusVersion", a."sharedAt", a."revealedAt", a."deliveryStatus"::text::delivery_status, a."deliveredAt", a."seenAt",
       a."sharedAt", greatest(a."sharedAt", a."revealedAt", a."deliveredAt", a."seenAt")
FROM app_migration.empathy_attempt_src a
JOIN participant pa ON pa.session_id = a."sessionId" AND pa.user_id = a."sourceUserId"
JOIN participant ps ON ps.session_id = a."sessionId" AND ps.user_id <> a."sourceUserId";
SELECT app_migration.note('11', 'EmpathyAttempt.status ' || status::text || ' → ' ||
                          CASE status::text WHEN 'ANALYZING' THEN 'HELD' ELSE 'AWAITING_SHARING' END, count(*))
FROM app_migration.empathy_attempt_src WHERE status IN ('ANALYZING', 'NEEDS_WORK') GROUP BY status;
SELECT app_migration.assert(a = b, format('step 11: %s empathy_attempt rows for %s "EmpathyAttempt" rows (subject must be unique)', a, b))
FROM (SELECT (SELECT count(*) FROM empathy_attempt) AS a, (SELECT count(*) FROM app_migration.empathy_attempt_src) AS b) x;

-- reconciler_result ← ReconcilerResult (ids kept) → the attempt of (session, guesser).
INSERT INTO reconciler_result (id, attempt_id, subject_participant_id, iteration, alignment_score, alignment_summary, gap_summary, gap_severity,
                               correctly_identified, missed_feelings, misattributions, most_important_gap, recommended_action, rationale,
                               sharing_would_help, suggested_share_focus, suggested_share_content, suggested_share_reason,
                               circuit_breaker_tripped, superseded_at, created_at, updated_at)
SELECT r.id, a.id, ps.id, r.iteration, r."alignmentScore", r."alignmentSummary", r."gapSummary", upper(r."gapSeverity")::gap_severity,
       coalesce(r."correctlyIdentified", '{}'), coalesce(r."missedFeelings", '{}'), coalesce(r.misattributions, '{}'), r."mostImportantGap",
       r."recommendedAction"::recommender_action, r.rationale, r."sharingWouldHelp", r."suggestedShareFocus",
       r."suggestedShareContent", r."suggestedShareReason", r."wasCircuitBreakerTrip", r."supersededAt",
       r."createdAt", coalesce(r."supersededAt", r."createdAt")
FROM "ReconcilerResult" r
JOIN app_migration.empathy_attempt_src a ON a."sessionId" = r."sessionId" AND a."sourceUserId" = app_migration.as_uuid(r."guesserId")
JOIN participant ps ON ps.session_id = r."sessionId" AND ps.user_id = app_migration.as_uuid(r."subjectId");
SELECT app_migration.assert(a = b, format('step 11: %s reconciler_result rows for %s "ReconcilerResult" rows', a, b))
FROM (SELECT (SELECT count(*) FROM reconciler_result) AS a, (SELECT count(*) FROM "ReconcilerResult") AS b) x;
SELECT app_migration.assert(n = 0, format('step 11: %s reconciler_result row(s) whose subject is not the attempt''s subject (T-result-live-attempt)', n))
FROM (SELECT count(*) AS n FROM reconciler_result r JOIN empathy_attempt a ON a.id = r.attempt_id
      WHERE r.subject_participant_id <> a.subject_participant_id) x;
SELECT app_migration.assert(n = 0, format('step 11: %s attempt(s) with more than one current reconciler_result', n))
FROM (SELECT count(*) AS n FROM (SELECT attempt_id FROM reconciler_result WHERE superseded_at IS NULL GROUP BY attempt_id HAVING count(*) > 1) d) x;
-- The plan asks "counter value = count(reconciler_result) per direction"; the
-- app deletes results on resubmit (circuit-breaker.ts:63-70) and increments
-- the counter only on resubmit, so the two are not equal by design. Reported.
SELECT app_migration.note('11', 'RefinementAttemptCounter direction: attempts vs results (not asserted; see header)', count(*),
                          string_agg(format('%s %s: counter=%s results=%s round=%s', c."sessionId", c.direction, c.attempts,
                            (SELECT count(*) FROM "ReconcilerResult" r WHERE r."sessionId" = c."sessionId" AND r."guesserId" || '->' || r."subjectId" = c.direction),
                            (SELECT a."revisionCount" + 1 FROM app_migration.empathy_attempt_src a WHERE a."sessionId" = c."sessionId" AND a."sourceUserId"::text = split_part(c.direction, '->', 1))),
                            '; '))
FROM "RefinementAttemptCounter" c;

-- reconciler_guidance ← ReconcilerResult.{areaHint, guidanceType, promptSeed} (P3 D8a split), where any is set.
INSERT INTO reconciler_guidance (result_id, author_participant_id, subject_participant_id, area_hint, guidance_type, prompt_seed, created_at)
SELECT r.id, a.author_participant_id, a.subject_participant_id, o."areaHint", o."guidanceType", o."promptSeed", r.created_at
FROM "ReconcilerResult" o
JOIN reconciler_result r ON r.id = o.id
JOIN empathy_attempt a ON a.id = r.attempt_id
WHERE num_nonnulls(o."areaHint", o."guidanceType", o."promptSeed") > 0;

-- context_share_offer ← ReconcilerShareOffer (ids kept); NOT_OFFERED/SKIPPED → EXPIRED;
-- refinedContent → draft(SHARE_CONTEXT) below; skippedAt, refinementChatUsed dropped.
INSERT INTO context_share_offer (id, attempt_id, result_id, subject_participant_id, iteration, status, offer_message, suggested_content,
                                 suggested_reason, shared_content, shared_at, declined_at, offered_at, delivery_status, delivered_at, seen_at,
                                 delivery_notified_at, seen_notified_at, created_at, updated_at)
SELECT o.id, r.attempt_id, r.id, r.subject_participant_id, o.iteration,
       (CASE o.status::text WHEN 'NOT_OFFERED' THEN 'EXPIRED' WHEN 'SKIPPED' THEN 'EXPIRED' ELSE o.status::text END)::share_offer_status,
       o."offerMessage", o."suggestedContent", o."suggestedReason", o."sharedContent", o."sharedAt", o."declinedAt", NULL,
       o."deliveryStatus"::text::delivery_status, o."deliveredAt", o."seenAt", o."lastDeliveryNotifiedAt", o."lastSeenNotifiedAt",
       o."createdAt", o."updatedAt"
FROM "ReconcilerShareOffer" o JOIN reconciler_result r ON r.id = o."resultId";
SELECT app_migration.note('11', 'ReconcilerShareOffer.status ' || status::text || ' → EXPIRED', count(*))
FROM "ReconcilerShareOffer" WHERE status IN ('NOT_OFFERED', 'SKIPPED') GROUP BY status;
SELECT app_migration.assert(a = b, format('step 11: %s context_share_offer rows for %s "ReconcilerShareOffer" rows', a, b))
FROM (SELECT (SELECT count(*) FROM context_share_offer) AS a, (SELECT count(*) FROM "ReconcilerShareOffer") AS b) x;

-- empathy_review ← EmpathyValidation (ids kept). feedback kept only where it
-- was shared (feedback_sent_at = validatedAt); unsent text → draft below.
INSERT INTO empathy_review (id, attempt_id, reviewer_participant_id, validated, feedback, feedback_sent_at, created_at, updated_at)
SELECT v.id, v."attemptId", p.id, v.validated,
       CASE WHEN v."feedbackShared" THEN v.feedback END,
       CASE WHEN v."feedbackShared" AND v.feedback IS NOT NULL THEN coalesce(v."validatedAt", a.submitted_at) END,
       coalesce(v."validatedAt", a.submitted_at), coalesce(v."validatedAt", a.submitted_at)
FROM app_migration.empathy_validation_src v
JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId"
JOIN empathy_attempt a ON a.id = v."attemptId";
SELECT app_migration.assert(a = b, format('step 11: %s empathy_review rows for %s "EmpathyValidation" rows', a, b))
FROM (SELECT (SELECT count(*) FROM empathy_review) AS a, (SELECT count(*) FROM app_migration.empathy_validation_src) AS b) x;
SELECT app_migration.assert(n = 0, format('step 11: %s empathy_review row(s) whose reviewer is not the attempt''s subject', n))
FROM (SELECT count(*) AS n FROM empathy_review r JOIN empathy_attempt a ON a.id = r.attempt_id
      WHERE r.reviewer_participant_id <> a.subject_participant_id) x;

-- ============================================================================
-- 3g. Step 9: messages, delivered copies, read state
-- ============================================================================

-- ---- Step 9: message ← Message (ids kept). conversation = the MAIN
-- conversation of participant (session, coalesce(forUserId, senderId)).
-- role USER/AI/SYSTEM stays (kind CHAT); the six event roles become kind,
-- with role USER when the row has a sender and AI when not (the role/sender
-- CHECKs: USER ⇒ sender, AI/SYSTEM ⇒ no sender). A USER row whose sender was
-- nulled (SetNull on a deleted user) is the conversation owner's own turn.
-- source_attempt_id: EMPATHY_STATEMENT → the attempt authored by its sender
-- (plan: by (session, author)); VALIDATION_FEEDBACK and SHARED_CONTEXT (spec
-- §1.1 names it too) → the attempt the sender is the subject of.
-- Rows with neither forUserId nor senderId are dropped only in a session with
-- a vanished member — the leaver's private rows (plan 4a, D9); P33 refused
-- them anywhere else. Their text goes to app_migration.dropped_content (R-c).
INSERT INTO app_migration.dropped_content (concept, session_id, user_id, text, written_at)
SELECT 'Message.content (no owner; session with a vanished member, D9)', m."sessionId", NULL, m.content, m.timestamp
FROM "Message" m WHERE m."forUserId" IS NULL AND m."senderId" IS NULL ORDER BY m.timestamp, m.id;
SELECT app_migration.note('9', 'Message without forUserId and senderId (role ' || role::text || '), vanished-member session: not copied (D9, plan 4a) → dropped_content', count(*),
                          string_agg(id::text, ', ' ORDER BY id))
FROM "Message" WHERE "forUserId" IS NULL AND "senderId" IS NULL GROUP BY role;

INSERT INTO message (id, conversation_id, sender_participant_id, role, kind, content, content_hash, refining_need_id, source_attempt_id, created_at)
SELECT m.id, c.id,
       CASE WHEN m.role IN ('AI', 'SYSTEM') THEN NULL
            WHEN m.role = 'USER' THEN coalesce(ps.id, po.id)
            ELSE ps.id END,
       (CASE WHEN m.role IN ('USER', 'AI', 'SYSTEM') THEN m.role::text
             WHEN ps.id IS NOT NULL THEN 'USER' ELSE 'AI' END)::message_role,
       (CASE WHEN m.role IN ('USER', 'AI', 'SYSTEM') THEN 'CHAT' ELSE m.role::text END)::message_kind,
       m.content, m."contentHash", m."refiningNeedId",
       CASE m.role::text
         WHEN 'EMPATHY_STATEMENT' THEN
           (SELECT a.id FROM app_migration.empathy_attempt_src a WHERE a."sessionId" = m."sessionId" AND a."sourceUserId" = coalesce(m."senderId", o.owner))
         WHEN 'VALIDATION_FEEDBACK' THEN
           (SELECT a.id FROM app_migration.empathy_attempt_src a WHERE a."sessionId" = m."sessionId"
              AND CASE WHEN m."senderId" IS NOT NULL THEN a."sourceUserId" <> m."senderId" ELSE a."sourceUserId" = o.owner END)
         WHEN 'SHARED_CONTEXT' THEN
           (SELECT a.id FROM app_migration.empathy_attempt_src a WHERE a."sessionId" = m."sessionId"
              AND CASE WHEN m."senderId" IS NOT NULL THEN a."sourceUserId" <> m."senderId" ELSE a."sourceUserId" = o.owner END)
       END,
       m.timestamp
FROM "Message" m
CROSS JOIN LATERAL (SELECT coalesce(app_migration.as_uuid(m."forUserId"), m."senderId") AS owner) o
JOIN participant po ON po.session_id = m."sessionId" AND po.user_id = o.owner
JOIN conversation c ON c.participant_id = po.id AND c.kind = 'MAIN'
LEFT JOIN participant ps ON ps.session_id = m."sessionId" AND ps.user_id = m."senderId"
ORDER BY m.timestamp, m.id;

SELECT app_migration.note('9', 'Message role ' || m.role::text || ' → role ' || x.role::text || ', kind ' || x.kind::text, count(*))
FROM "Message" m JOIN message x ON x.id = m.id
GROUP BY m.role, x.role, x.kind;
SELECT app_migration.note('9', 'USER message with a nulled sender → sender = the conversation owner', count(*))
FROM "Message" WHERE role = 'USER' AND "senderId" IS NULL AND "forUserId" IS NOT NULL;
SELECT app_migration.note('9', kind::text || ' message without a resolvable source attempt', count(*))
FROM message WHERE kind IN ('EMPATHY_STATEMENT', 'VALIDATION_FEEDBACK', 'SHARED_CONTEXT') AND source_attempt_id IS NULL GROUP BY kind;

-- Stage4SubChatMessage → its SUBCHAT conversation (ids kept); no sender column:
-- USER rows are the sub-chat owner's.
INSERT INTO message (id, conversation_id, sender_participant_id, role, kind, content, content_hash, refining_need_id, source_attempt_id, created_at)
SELECT sm.id, c.id, CASE WHEN sm.role = 'USER' THEN c.participant_id END,
       (CASE WHEN sm.role IN ('USER', 'AI', 'SYSTEM') THEN sm.role::text ELSE 'AI' END)::message_role,
       (CASE WHEN sm.role IN ('USER', 'AI', 'SYSTEM') THEN 'CHAT' ELSE sm.role::text END)::message_kind,
       sm.content, NULL, NULL, NULL, sm."createdAt"
FROM "Stage4SubChatMessage" sm JOIN conversation c ON c.id = sm."subChatId"
ORDER BY sm."createdAt", sm.id;

-- Delivered copies (P0-2): for every REVEALED/VALIDATED attempt, the
-- EMPATHY_STATEMENT the reveal job writes into the SUBJECT's conversation,
-- at revealed_at — today's data has none. content_hash NULL (the plaintext
-- hash is not derivable in SQL from encrypted content).
WITH ins AS (
  INSERT INTO message (id, conversation_id, sender_participant_id, role, kind, content, content_hash, refining_need_id, source_attempt_id, created_at)
  SELECT app_migration.mint(a.revealed_at), c.id, a.author_participant_id, 'USER', 'EMPATHY_STATEMENT', a.content, NULL, NULL, a.id, a.revealed_at
  FROM empathy_attempt a
  JOIN conversation c ON c.participant_id = a.subject_participant_id AND c.kind = 'MAIN'
  WHERE a.status IN ('REVEALED', 'VALIDATED')
    AND NOT EXISTS (SELECT 1 FROM message m WHERE m.conversation_id = c.id AND m.source_attempt_id = a.id AND m.kind = 'EMPATHY_STATEMENT')
  ORDER BY a.revealed_at, a.id
  RETURNING id, source_attempt_id
)
INSERT INTO app_migration.shape_map SELECT 'message:delivered_empathy_statement', source_attempt_id::text, id FROM ins;
SELECT app_migration.note('9', 'delivered EMPATHY_STATEMENT copies inserted (added rows)', count(*))
FROM app_migration.shape_map WHERE concept = 'message:delivered_empathy_statement';

SELECT app_migration.assert(a = b + c + d - e,
         format('step 9: message %s <> Message %s + Stage4SubChatMessage %s + delivered copies %s - ownerless %s', a, b, c, d, e))
FROM (SELECT (SELECT count(*) FROM message) AS a, (SELECT count(*) FROM "Message") AS b, (SELECT count(*) FROM "Stage4SubChatMessage") AS c,
             (SELECT count(*) FROM app_migration.shape_map WHERE concept = 'message:delivered_empathy_statement') AS d,
             (SELECT count(*) FROM "Message" WHERE "forUserId" IS NULL AND "senderId" IS NULL) AS e) x;

-- Step 11 assertion: every reveal is still resolvable — for every
-- REVEALED/VALIDATED attempt, under the subject's identity
-- (app.current_user_id() via SET LOCAL-equivalent set_config(…, true)), the
-- target SELECT policy on empathy_attempt (spec §1.2: mine(author) OR
-- (mine(subject) AND revealed_at IS NOT NULL)) admits the row, and the
-- subject's own conversation holds its delivered copy.
DO $$
DECLARE
  r   record;
  bad text := '';
  n   int := 0;
BEGIN
  FOR r IN
    SELECT a.id, s.user_id AS subject_user
    FROM empathy_attempt a JOIN participant s ON s.id = a.subject_participant_id
    WHERE a.status IN ('REVEALED', 'VALIDATED')
  LOOP
    PERFORM set_config('app.current_user_id', r.subject_user::text, true);
    IF NOT EXISTS (
         SELECT 1 FROM empathy_attempt a
         WHERE a.id = r.id
           AND (EXISTS (SELECT 1 FROM participant p WHERE p.id = a.author_participant_id AND p.user_id = app.current_user_id())
                OR (EXISTS (SELECT 1 FROM participant p WHERE p.id = a.subject_participant_id AND p.user_id = app.current_user_id())
                    AND a.revealed_at IS NOT NULL)))
       OR NOT EXISTS (
         SELECT 1 FROM message m
         JOIN conversation c ON c.id = m.conversation_id
         JOIN participant p ON p.id = c.participant_id
         WHERE m.source_attempt_id = r.id AND m.kind = 'EMPATHY_STATEMENT' AND p.user_id = app.current_user_id())
    THEN
      n := n + 1;
      bad := bad || ' ' || r.id;
    END IF;
  END LOOP;
  PERFORM set_config('app.current_user_id', '', true);
  PERFORM app_migration.assert(n = 0, format('step 11: %s revealed attempt(s) not resolvable by their subject:%s', n, bad));
END
$$;

-- conversation_read_state ← UserVessel read fields. lastSeenChatItemId keeps
-- only a value that is a migrated message id (FK message SET NULL); others are reported.
INSERT INTO conversation_read_state (participant_id, last_viewed_at, last_seen_message_id, last_viewed_share_tab_at, last_active_at, archived_at, created_at, updated_at)
SELECT p.id, v."lastViewedAt", m.id, v."lastViewedShareTabAt", v."lastActiveAt", v."archivedAt", v."createdAt", v."updatedAt"
FROM "UserVessel" v
JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId"
LEFT JOIN message m ON m.id = app_migration.as_uuid(v."lastSeenChatItemId");
SELECT app_migration.note('6', 'UserVessel.lastSeenChatItemId not a migrated message id → NULL', count(*))
FROM "UserVessel" v
WHERE v."lastSeenChatItemId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM message m WHERE m.id = app_migration.as_uuid(v."lastSeenChatItemId"));
SELECT app_migration.assert(a = b, format('step 6: %s conversation_read_state rows for %s "UserVessel" rows', a, b))
FROM (SELECT (SELECT count(*) FROM conversation_read_state) AS a, (SELECT count(*) FROM "UserVessel") AS b) x;

-- ============================================================================
-- 3h. Steps 10, 12: drafts, consent
-- ============================================================================

-- ---- Step 10: draft. EmpathyDraft → EMPATHY about the other participant;
-- ValidationFeedbackDraft → VALIDATION_FEEDBACK on the partner's attempt;
-- unsent EmpathyValidation.feedback → VALIDATION_FEEDBACK on the reviewed
-- attempt (unless a ValidationFeedbackDraft already holds that point — it is
-- the newer working text; the skipped text is reported); ReconcilerShareOffer
-- .refinedContent → SHARE_CONTEXT on the offer. Ids minted (plan id policy).
WITH ins AS (
  INSERT INTO draft (id, participant_id, kind, about_participant_id, attempt_id, share_offer_id, content, ready_to_share, version, created_at, updated_at)
  SELECT app_migration.mint(d."createdAt"), p.id, 'EMPATHY', o.id, NULL, NULL, d.content, d."readyToShare", d.version, d."createdAt", d."updatedAt"
  FROM "EmpathyDraft" d
  JOIN participant p ON p.session_id = d."sessionId" AND p.user_id = d."userId"
  JOIN participant o ON o.session_id = d."sessionId" AND o.user_id <> d."userId"
  ORDER BY d."createdAt", d.id
  RETURNING id, participant_id, about_participant_id
)
INSERT INTO app_migration.shape_map
SELECT 'draft:EmpathyDraft', d.id::text, ins.id
FROM ins JOIN participant p ON p.id = ins.participant_id
JOIN "EmpathyDraft" d ON d."sessionId" = p.session_id AND d."userId" = p.user_id;

WITH ins AS (
  INSERT INTO draft (id, participant_id, kind, about_participant_id, attempt_id, share_offer_id, content, ready_to_share, version, created_at, updated_at)
  SELECT app_migration.mint(d."createdAt"), p.id, 'VALIDATION_FEEDBACK', NULL, a.id, NULL, d.content, d."readyToShare", 1, d."createdAt", d."updatedAt"
  FROM "ValidationFeedbackDraft" d
  JOIN participant p ON p.session_id = d."sessionId" AND p.user_id = d."userId"
  JOIN app_migration.empathy_attempt_src a ON a."sessionId" = d."sessionId" AND a."sourceUserId" <> d."userId"
  ORDER BY d."createdAt", d.id
  RETURNING id, participant_id
)
INSERT INTO app_migration.shape_map
SELECT 'draft:ValidationFeedbackDraft', d.id::text, ins.id
FROM ins JOIN participant p ON p.id = ins.participant_id
JOIN "ValidationFeedbackDraft" d ON d."sessionId" = p.session_id AND d."userId" = p.user_id;

WITH src AS (
  SELECT v.id AS validation_id, p.id AS participant_id, v."attemptId", v.feedback, coalesce(v."validatedAt", a.submitted_at) AS at
  FROM app_migration.empathy_validation_src v
  JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId"
  JOIN empathy_attempt a ON a.id = v."attemptId"
  WHERE NOT v."feedbackShared" AND v.feedback IS NOT NULL
), ins AS (
  INSERT INTO draft (id, participant_id, kind, about_participant_id, attempt_id, share_offer_id, content, ready_to_share, version, created_at, updated_at)
  SELECT app_migration.mint(at), participant_id, 'VALIDATION_FEEDBACK', NULL, "attemptId", NULL, feedback, false, 1, at, at
  FROM src
  WHERE NOT EXISTS (SELECT 1 FROM draft d WHERE d.participant_id = src.participant_id AND d.kind = 'VALIDATION_FEEDBACK' AND d.attempt_id = src."attemptId")
  ORDER BY at, validation_id
  RETURNING id, participant_id, attempt_id
)
INSERT INTO app_migration.shape_map
SELECT 'draft:EmpathyValidation.feedback', v.id::text, ins.id
FROM ins JOIN participant p ON p.id = ins.participant_id
JOIN app_migration.empathy_validation_src v ON v."attemptId" = ins.attempt_id AND v."userId" = p.user_id;
INSERT INTO app_migration.dropped_content (concept, session_id, user_id, text, written_at)
SELECT 'EmpathyValidation.feedback (unsent; superseded by a ValidationFeedbackDraft)', v."sessionId", v."userId", v.feedback, v."validatedAt"
FROM app_migration.empathy_validation_src v
JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId"
WHERE NOT v."feedbackShared" AND v.feedback IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM app_migration.shape_map s WHERE s.concept = 'draft:EmpathyValidation.feedback' AND s.old_key = v.id::text);
SELECT app_migration.note('10', 'unsent EmpathyValidation.feedback superseded by a ValidationFeedbackDraft → dropped_content', count(*))
FROM app_migration.empathy_validation_src v
JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId"
WHERE NOT v."feedbackShared" AND v.feedback IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM app_migration.shape_map s WHERE s.concept = 'draft:EmpathyValidation.feedback' AND s.old_key = v.id::text);

WITH ins AS (
  INSERT INTO draft (id, participant_id, kind, about_participant_id, attempt_id, share_offer_id, content, ready_to_share, version, created_at, updated_at)
  SELECT app_migration.mint(o.updated_at), o.subject_participant_id, 'SHARE_CONTEXT', NULL, NULL, o.id, r."refinedContent", false, 1, o.updated_at, o.updated_at
  FROM "ReconcilerShareOffer" r JOIN context_share_offer o ON o.id = r.id
  WHERE r."refinedContent" IS NOT NULL
  ORDER BY o.updated_at, o.id
  RETURNING id, share_offer_id
)
INSERT INTO app_migration.shape_map SELECT 'draft:ReconcilerShareOffer.refinedContent', share_offer_id::text, id FROM ins;

SELECT app_migration.assert(a = b, format('step 10: %s drafts for %s sources', a, b))
FROM (SELECT (SELECT count(*) FROM draft) AS a,
             (SELECT count(*) FROM app_migration.shape_map WHERE concept LIKE 'draft:%') AS b) x;
SELECT app_migration.assert(a = b, format('step 10: %s EMPATHY drafts for %s "EmpathyDraft" rows', a, b))
FROM (SELECT (SELECT count(*) FROM draft WHERE kind = 'EMPATHY') AS a, (SELECT count(*) FROM "EmpathyDraft") AS b) x;
SELECT app_migration.assert(n = 0, format('step 10: %s sharing point(s) with more than one draft', n))
FROM (SELECT count(*) AS n FROM (
        SELECT 1 FROM draft GROUP BY participant_id, kind, coalesce(about_participant_id, attempt_id, share_offer_id) HAVING count(*) > 1) d) x;

-- ---- Step 12: consent ← ConsentRecord (ids kept). Arc column by targetType:
-- IDENTIFIED_NEED → need_id; EMPATHY_ATTEMPT → empathy_attempt_id;
-- EMPATHY_DRAFT → empathy_attempt_id of the draft's attempt (the writer
-- stores the EmpathyDraft id, stage2.ts:682); STRATEGY_PROPOSAL → proposal_id.
-- sessionId (nullable) falls back to the target's session. target_kind is
-- written here because Prisma's DDL made it a plain NOT NULL column; the
-- trailer re-creates it GENERATED from the same arc. metadata dropped.
WITH t AS (
  SELECT c.*,
         CASE c."targetType" WHEN 'IDENTIFIED_NEED' THEN app_migration.as_uuid(c."targetId") END AS t_need,
         CASE c."targetType"
           WHEN 'EMPATHY_ATTEMPT' THEN app_migration.as_uuid(c."targetId")
           WHEN 'EMPATHY_DRAFT' THEN coalesce(
             (SELECT a.id FROM app_migration.empathy_attempt_src a WHERE a.id = app_migration.as_uuid(c."targetId")),
             (SELECT a.id FROM app_migration.empathy_attempt_src a WHERE a."draftId" = app_migration.as_uuid(c."targetId") ORDER BY a.id LIMIT 1),
             (SELECT a.id FROM "EmpathyDraft" d JOIN app_migration.empathy_attempt_src a ON a."sessionId" = d."sessionId" AND a."sourceUserId" = d."userId"
              WHERE d.id = app_migration.as_uuid(c."targetId")))
         END AS t_attempt,
         CASE c."targetType" WHEN 'STRATEGY_PROPOSAL' THEN app_migration.as_uuid(c."targetId") END AS t_proposal
  FROM "ConsentRecord" c
), s AS (
  SELECT t.*, coalesce(t."sessionId",
           (SELECT p.session_id FROM need n JOIN participant p ON p.id = n.participant_id WHERE n.id = t.t_need),
           (SELECT p.session_id FROM empathy_attempt a JOIN participant p ON p.id = a.author_participant_id WHERE a.id = t.t_attempt),
           (SELECT pr.session_id FROM proposal pr WHERE pr.id = t.t_proposal)) AS t_session
  FROM t
)
INSERT INTO consent (id, participant_id, requested_by_participant_id, need_id, empathy_attempt_id, proposal_id, share_offer_id, review_id,
                     target_kind, decision, decided_at, revoked_at, created_at, updated_at)
SELECT s.id, pd.id, pr.id, s.t_need, s.t_attempt, s.t_proposal, NULL, NULL,
       (CASE WHEN s.t_need IS NOT NULL THEN 'NEED' WHEN s.t_attempt IS NOT NULL THEN 'EMPATHY_ATTEMPT' ELSE 'PROPOSAL' END)::consent_target,
       s.decision::text::consent_decision, s."decidedAt", s."revokedAt", s."createdAt", coalesce(s."revokedAt", s."decidedAt", s."createdAt")
FROM s
JOIN participant pd ON pd.session_id = s.t_session AND pd.user_id = s."userId"
LEFT JOIN participant pr ON pr.session_id = s.t_session AND pr.user_id = s."requestedByUserId";

SELECT app_migration.note('12', 'ConsentRecord.targetType ' || "targetType"::text, count(*)) FROM "ConsentRecord" GROUP BY "targetType";
SELECT app_migration.note('12', 'ConsentRecord.metadata dropped', count(*)) FROM "ConsentRecord" WHERE app_migration.jnull(metadata) IS NOT NULL;
SELECT app_migration.assert(a = b, format('step 12: %s consent rows for %s "ConsentRecord" rows (decider must be a participant)', a, b))
FROM (SELECT (SELECT count(*) FROM consent) AS a, (SELECT count(*) FROM "ConsentRecord") AS b) x;
SELECT app_migration.assert(n = 0, format('step 12: %s consent row(s) without exactly one arc target', n))
FROM (SELECT count(*) AS n FROM consent WHERE num_nonnulls(need_id, empathy_attempt_id, proposal_id, share_offer_id, review_id) <> 1) x;
SELECT app_migration.assert(n = 0, format('step 12: %s consent row(s) with a requester that is not a participant of the session', n))
FROM (SELECT count(*) AS n FROM consent c JOIN "ConsentRecord" o ON o.id = c.id
      WHERE o."requestedByUserId" IS NOT NULL AND c.requested_by_participant_id IS NULL) x;
-- T-consent-owner on every migrated row: the decider owns the arc target.
SELECT app_migration.assert(n = 0, format('step 12: %s consent row(s) name a target the decider does not own (T-consent-owner): %s', n, ids))
FROM (SELECT count(*) AS n, string_agg(c.id::text, ', ' ORDER BY c.id) AS ids
      FROM consent c
      LEFT JOIN need n ON n.id = c.need_id
      LEFT JOIN empathy_attempt a ON a.id = c.empathy_attempt_id
      LEFT JOIN proposal p ON p.id = c.proposal_id
      WHERE c.participant_id IS DISTINCT FROM coalesce(n.participant_id, a.author_participant_id, p.created_by_participant_id)) x;

-- ============================================================================
-- 3i. Step 13: proposal children, agreements, closure
-- ============================================================================

-- ---- Step 13: proposal_need ← StrategyProposalNeed ∪ needsAddressed[] labels
-- matched case-insensitively to a need of the session, both filtered to needs
-- with a need_share row (P0-1). A label that matches several shared needs
-- links each. Unmatched or unshared → proposal.unresolved_need_labels (first
-- occurrence order, case-insensitively distinct).
CREATE TABLE app_migration.proposal_need_src AS
SELECT spn."proposalId" AS proposal_id, spn."needId" AS need_id, n.need AS label, 0 AS ord, spn."createdAt" AS at, 'StrategyProposalNeed' AS source
FROM "StrategyProposalNeed" spn JOIN "IdentifiedNeed" n ON n.id = spn."needId"
UNION ALL
SELECT sp.id, m.need_id, l.label, l.ord::int, sp."createdAt", 'needsAddressed'
FROM "StrategyProposal" sp
CROSS JOIN LATERAL unnest(coalesce(sp."needsAddressed", '{}')) WITH ORDINALITY AS l (label, ord)
LEFT JOIN LATERAL (
  SELECT n.id AS need_id FROM need n JOIN participant p ON p.id = n.participant_id
  WHERE p.session_id = sp."sessionId" AND lower(trim(n.label)) = lower(trim(l.label))
) m ON true;

INSERT INTO proposal_need (proposal_id, need_id, created_at)
SELECT s.proposal_id, ns.need_id, min(s.at)
FROM app_migration.proposal_need_src s JOIN need_share ns ON ns.need_id = s.need_id
GROUP BY s.proposal_id, ns.need_id
ORDER BY 1, 2;

UPDATE proposal p SET unresolved_need_labels = u.labels
FROM (
  SELECT proposal_id, array_agg(label ORDER BY ord, label) AS labels
  FROM (
    SELECT DISTINCT ON (s.proposal_id, lower(trim(s.label))) s.proposal_id, s.label, s.ord
    FROM app_migration.proposal_need_src s
    WHERE s.label IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM app_migration.proposal_need_src s2 JOIN need_share ns ON ns.need_id = s2.need_id
                      WHERE s2.proposal_id = s.proposal_id AND lower(trim(s2.label)) = lower(trim(s.label)))
    ORDER BY s.proposal_id, lower(trim(s.label)), s.ord
  ) d
  GROUP BY proposal_id
) u
WHERE u.proposal_id = p.id;

SELECT app_migration.note('13', 'needsAddressed label coverage: ' || outcome, count(*))
FROM (SELECT CASE WHEN EXISTS (SELECT 1 FROM need_share ns WHERE ns.need_id = s.need_id) THEN 'linked to a shared need'
                  WHEN s.need_id IS NOT NULL THEN 'matched an unshared need → unresolved_need_labels'
                  ELSE 'no match → unresolved_need_labels' END AS outcome
      FROM app_migration.proposal_need_src s WHERE s.source = 'needsAddressed') x
GROUP BY outcome;
SELECT app_migration.note('13', 'StrategyProposalNeed on an unshared need → unresolved_need_labels', count(*))
FROM app_migration.proposal_need_src s
WHERE s.source = 'StrategyProposalNeed' AND NOT EXISTS (SELECT 1 FROM need_share ns WHERE ns.need_id = s.need_id);
SELECT app_migration.assert(n = 0, format('step 13: %s proposal_need row(s) on a need without need_share', n))
FROM (SELECT count(*) AS n FROM proposal_need pn WHERE NOT EXISTS (SELECT 1 FROM need_share ns WHERE ns.need_id = pn.need_id)) x;

-- proposal_choice ← Stage4ProposalSelection.
INSERT INTO proposal_choice (proposal_id, participant_id, decision, note, created_at, updated_at)
SELECT s."proposalId", p.id, s.decision::text::choice_decision, s.note, s."selectedAt", s."updatedAt"
FROM "Stage4ProposalSelection" s JOIN participant p ON p.session_id = s."sessionId" AND p.user_id = s."userId";
SELECT app_migration.assert(a = b, format('step 13: %s proposal_choice rows for %s "Stage4ProposalSelection" rows', a, b))
FROM (SELECT (SELECT count(*) FROM proposal_choice) AS a, (SELECT count(*) FROM "Stage4ProposalSelection") AS b) x;

-- proposal_revision ← Stage4ProposalRevision (ids kept): action upper-snaked;
-- sessionId asserted (P23b) then dropped; messageId dropped.
INSERT INTO proposal_revision (id, proposal_id, actor_participant_id, action, before, after, reason, created_at)
SELECT r.id, r."proposalId", pa.id,
       upper(regexp_replace(regexp_replace(r.action, '([a-z0-9])([A-Z])', '\1_\2', 'g'), '[^A-Za-z0-9]+', '_', 'g'))::revision_action,
       app_migration.jnull(r.before), app_migration.jnull(r.after), r.reason, r."createdAt"
FROM "Stage4ProposalRevision" r
JOIN "StrategyProposal" sp ON sp.id = r."proposalId"
LEFT JOIN participant pa ON pa.session_id = sp."sessionId" AND pa.user_id = app_migration.as_uuid(r."actorUserId");
SELECT app_migration.note('13', 'Stage4ProposalRevision.messageId dropped', count(*)) FROM "Stage4ProposalRevision" WHERE "messageId" IS NOT NULL;
SELECT app_migration.assert(a = b, format('step 13: %s proposal_revision rows for %s "Stage4ProposalRevision" rows', a, b))
FROM (SELECT (SELECT count(*) FROM proposal_revision) AS a, (SELECT count(*) FROM "Stage4ProposalRevision") AS b) x;

-- agreement ← Agreement (ids kept; session via SharedVessel). PROPOSED with
-- both agreed → AGREED; PROPOSED otherwise → dropped (the proposal remains;
-- listed). created_at = agreedAt, else the proposal's createdAt (Agreement has no createdAt).
SELECT app_migration.note('13', 'PROPOSED agreement not accepted by both: dropped', count(*), string_agg(id::text, ', ' ORDER BY id))
FROM "Agreement" WHERE status = 'PROPOSED' AND NOT ("agreedByA" AND "agreedByB");
INSERT INTO app_migration.dropped_content (concept, session_id, user_id, text, written_at)
SELECT 'Agreement.description (PROPOSED, not accepted by both; dropped)', sv."sessionId", NULL, a.description, a."agreedAt"
FROM "Agreement" a JOIN "SharedVessel" sv ON sv.id = a."sharedVesselId"
WHERE a.status = 'PROPOSED' AND NOT (a."agreedByA" AND a."agreedByB");
SELECT app_migration.note('13', 'PROPOSED agreement accepted by both → AGREED', count(*))
FROM "Agreement" WHERE status = 'PROPOSED' AND "agreedByA" AND "agreedByB";
INSERT INTO agreement (id, session_id, proposal_id, type, status, description, duration, measure_of_success, follow_up_at, completed_at, created_at, updated_at)
SELECT a.id, sv."sessionId", a."proposalId", a.type::text::agreement_type,
       (CASE a.status::text WHEN 'PROPOSED' THEN 'AGREED' ELSE a.status::text END)::agreement_status,
       a.description, a.duration, a."measureOfSuccess", a."followUpDate", a."completedAt",
       coalesce(a."agreedAt", sp."createdAt"), greatest(coalesce(a."agreedAt", sp."createdAt"), a."completedAt")
FROM "Agreement" a
JOIN "SharedVessel" sv ON sv.id = a."sharedVesselId"
JOIN "StrategyProposal" sp ON sp.id = a."proposalId"
WHERE a.status <> 'PROPOSED' OR (a."agreedByA" AND a."agreedByB");

SELECT app_migration.assert(a = b - c, format('step 13: %s agreement rows for %s "Agreement" rows - %s dropped PROPOSED', a, b, c))
FROM (SELECT (SELECT count(*) FROM agreement) AS a, (SELECT count(*) FROM "Agreement") AS b,
             (SELECT count(*) FROM "Agreement" WHERE status = 'PROPOSED' AND NOT ("agreedByA" AND "agreedByB")) AS c) x;

-- agreement_party ← agreedByA/agreedByB through the A/B slots.
INSERT INTO agreement_party (agreement_id, participant_id, agreed_at, created_at)
SELECT ag.id, s.participant_id, ag.created_at, ag.created_at
FROM agreement ag
JOIN "Agreement" a ON a.id = ag.id
JOIN app_migration.ab_slot s ON s.session_id = ag.session_id
WHERE (s.slot = 'A' AND a."agreedByA") OR (s.slot = 'B' AND a."agreedByB");
SELECT app_migration.assert(a = b, format('step 13: %s agreement_party rows for %s agreedByA/agreedByB flags', a, b))
FROM (SELECT (SELECT count(*) FROM agreement_party) AS a,
             (SELECT coalesce(sum(a."agreedByA"::int + a."agreedByB"::int), 0) FROM "Agreement" a JOIN agreement ag ON ag.id = a.id) AS b) x;

-- Agreement.agreedByA/B is also choice evidence (spec §1.4 proposal_choice
-- Absorbs): a party without a choice on the proposal gets WILLING at
-- agreed_at, so T-agreement-parties (ii) holds for the legacy ranking flow,
-- which wrote no selections. Reported as added rows.
WITH ins AS (
  INSERT INTO proposal_choice (proposal_id, participant_id, decision, note, created_at, updated_at)
  SELECT ag.proposal_id, ap.participant_id, 'WILLING', NULL, ap.agreed_at, ap.agreed_at
  FROM agreement_party ap JOIN agreement ag ON ag.id = ap.agreement_id
  WHERE NOT EXISTS (SELECT 1 FROM proposal_choice c WHERE c.proposal_id = ag.proposal_id AND c.participant_id = ap.participant_id)
  RETURNING proposal_id, participant_id
)
INSERT INTO app_migration.shape_map SELECT 'proposal_choice:from_agreement', proposal_id::text || ':' || participant_id::text, participant_id FROM ins;
SELECT app_migration.note('13', 'proposal_choice WILLING synthesised from Agreement.agreedByA/B (added rows)', count(*))
FROM app_migration.shape_map WHERE concept = 'proposal_choice:from_agreement';

-- T-agreement-parties, evaluated on every migrated agreement (its deferred
-- trigger only sees rows written after the trailer creates it): the parties
-- are the human participants present when it was created — a tombstoned
-- leaver (left_at = the migration) included (spec §4 "what survives").
SELECT app_migration.assert(n = 0, format('step 13: %s agreement(s) whose parties are not exactly the human participants present at creation, all WILLING: %s', n, ids))
FROM (SELECT count(*) AS n, string_agg(ag.id::text, ', ' ORDER BY ag.id) AS ids
      FROM agreement ag
      WHERE EXISTS (SELECT participant_id FROM agreement_party WHERE agreement_id = ag.id
                    EXCEPT SELECT id FROM participant WHERE session_id = ag.session_id AND kind = 'human'
                                                        AND (left_at IS NULL OR left_at > ag.created_at))
         OR EXISTS (SELECT id FROM participant WHERE session_id = ag.session_id AND kind = 'human'
                                                AND (left_at IS NULL OR left_at > ag.created_at)
                    EXCEPT SELECT participant_id FROM agreement_party WHERE agreement_id = ag.id)
         OR EXISTS (SELECT 1 FROM agreement_party ap
                    WHERE ap.agreement_id = ag.id
                      AND NOT EXISTS (SELECT 1 FROM proposal_choice c WHERE c.proposal_id = ag.proposal_id
                                        AND c.participant_id = ap.participant_id AND c.decision = 'WILLING'))) x;

-- session_closure ← Stage4Closure minus the three arrays (→ v_session_closure_items,
-- compared in the trailer against app_migration.old_closure).
INSERT INTO session_closure (session_id, kind, reason, summary, closed_by_participant_id, check_in_at, closed_at, created_at)
SELECT c."sessionId", c.kind::text::closure_kind, c.reason::text::closure_reason, c.summary, p.id, c."checkInAt", c."closedAt", c."createdAt"
FROM "Stage4Closure" c
LEFT JOIN participant p ON p.session_id = c."sessionId" AND p.user_id = app_migration.as_uuid(c."closedByUserId");
INSERT INTO app_migration.old_closure (session_id, shared_agreement_ids, individual_proposal_ids, open_need_ids)
SELECT "sessionId", coalesce("sharedAgreementIds", '{}'), coalesce("individualProposalIds", '{}'), coalesce("openNeedIds", '{}')
FROM "Stage4Closure";
SELECT app_migration.assert(a = b, format('step 13: %s session_closure rows for %s "Stage4Closure" rows', a, b))
FROM (SELECT (SELECT count(*) FROM session_closure) AS a, (SELECT count(*) FROM "Stage4Closure") AS b) x;
SELECT app_migration.note('13', 'StrategyRanking dropped (ranking not in the product flow)', count(*)) FROM "StrategyRanking";

-- ============================================================================
-- 3j. Step 14: follow-up
-- ============================================================================

-- ---- Step 14: follow_up ← TendingEntry (ids kept). type: the *_CHECKIN suffix
-- goes (owner decision 2026-10-21), any other value RAISEs. response_deadline_at
-- and summary from the entry's OPEN TendingCoordinationCycle (plan step 14),
-- else its latest; the entry's own summary wins when both are set, and the
-- cycle's differing resultSummary goes to app_migration.dropped_content.
INSERT INTO follow_up (id, session_id, agreement_id, proposal_id, type, scope, owner_participant_id, opted_in_shared, status,
                       scheduled_for, response_deadline_at, opened_at, completed_at, summary, created_at, updated_at)
SELECT e.id, e."sessionId", ag.id, NULL,
       (CASE e.type::text
          WHEN 'SCHEDULED_SHARED_AGREEMENT_CHECKIN' THEN 'SCHEDULED_SHARED_AGREEMENT'
          WHEN 'SCHEDULED_INDIVIDUAL_COMMITMENT_CHECKIN' THEN 'SCHEDULED_INDIVIDUAL_COMMITMENT'
          WHEN 'USER_INITIATED_REENTRY' THEN 'USER_INITIATED_REENTRY'
          ELSE app_migration.unmapped('TendingEntry.type', e.type::text)
        END)::follow_up_type,
       e.scope::text::follow_up_scope, po.id, e."optedInShared", e.status::text::follow_up_status,
       e."scheduledFor", y."responseDeadlineAt", e."openedAt", e."completedAt", coalesce(e.summary, y."resultSummary"),
       e."createdAt", e."updatedAt"
FROM "TendingEntry" e
LEFT JOIN agreement ag ON ag.id = e."agreementId"
LEFT JOIN participant po ON po.session_id = e."sessionId" AND po.user_id = app_migration.as_uuid(e."ownerUserId")
LEFT JOIN LATERAL (
  SELECT * FROM "TendingCoordinationCycle" c WHERE e.id = ANY (c."entryIds") ORDER BY (c.status IN ('WAITING_FOR_PARTNER', 'READY_TO_RESOLVE')) DESC, c."createdAt" DESC, c.id DESC LIMIT 1
) y ON true;
INSERT INTO app_migration.dropped_content (concept, session_id, user_id, text, written_at)
SELECT 'TendingCoordinationCycle.resultSummary (differs from the entry summary kept)', e."sessionId", y."createdByUserId", y."resultSummary", y."updatedAt"
FROM "TendingEntry" e
JOIN LATERAL (SELECT * FROM "TendingCoordinationCycle" c WHERE e.id = ANY (c."entryIds") ORDER BY (c.status IN ('WAITING_FOR_PARTNER', 'READY_TO_RESOLVE')) DESC, c."createdAt" DESC, c.id DESC LIMIT 1) y ON true
WHERE e.summary IS NOT NULL AND y."resultSummary" IS NOT NULL AND e.summary <> y."resultSummary";
SELECT app_migration.note('14', 'TendingEntry.summary and its cycle resultSummary both set and different (entry kept; cycle text → dropped_content)', count(*))
FROM "TendingEntry" e
JOIN LATERAL (SELECT * FROM "TendingCoordinationCycle" c WHERE e.id = ANY (c."entryIds") ORDER BY (c.status IN ('WAITING_FOR_PARTNER', 'READY_TO_RESOLVE')) DESC, c."createdAt" DESC, c.id DESC LIMIT 1) y ON true
WHERE e.summary IS NOT NULL AND y."resultSummary" IS NOT NULL AND e.summary <> y."resultSummary";
-- The entry's open (else latest) cycle — the one response_deadline_at came
-- from — for the trailer's v_follow_up_cycle comparison.
INSERT INTO app_migration.old_cycle (follow_up_id, cycle_id, status)
SELECT e.id, y.id, y.status::text
FROM "TendingEntry" e
JOIN LATERAL (SELECT * FROM "TendingCoordinationCycle" c WHERE e.id = ANY (c."entryIds") ORDER BY (c.status IN ('WAITING_FOR_PARTNER', 'READY_TO_RESOLVE')) DESC, c."createdAt" DESC, c.id DESC LIMIT 1) y ON true;
SELECT app_migration.assert(a = b, format('step 14: %s follow_up rows for %s "TendingEntry" rows', a, b))
FROM (SELECT (SELECT count(*) FROM follow_up) AS a, (SELECT count(*) FROM "TendingEntry") AS b) x;
SELECT app_migration.assert(n = 0, format('step 14: %s follow_up row(s) lost their agreement or owner', n))
FROM (SELECT count(*) AS n FROM "TendingEntry" e JOIN follow_up f ON f.id = e.id
      WHERE (e."agreementId" IS NOT NULL AND f.agreement_id IS NULL) OR (e."ownerUserId" IS NOT NULL AND f.owner_participant_id IS NULL)) x;

-- follow_up_checkin: one row per (old check-in, entry it covers) — a check-in
-- covers its cycle's entryIds and every entry its responses / outcomes /
-- adjustments name (P24c/P24d: at least one entry, never two check-ins of one
-- user on one entry). Children without an entry (need outcomes, carried
-- notes) go on the check-in's first row (lowest entry id). An orphan
-- TendingResponse (checkinId NULL) joins the row for its (entry, user), or
-- gets a synthetic check-in at its submittedAt.
INSERT INTO app_migration.checkin_map (checkin_id, entry_id, user_id, session_id, submitted_at, is_first, new_id)
SELECT checkin_id, entry_id, user_id, session_id, submitted_at, rn = 1, app_migration.mint(submitted_at)
FROM (
  SELECT c.id AS checkin_id, x.entry_id, c."userId" AS user_id, c."sessionId" AS session_id, c."submittedAt" AS submitted_at,
         row_number() OVER (PARTITION BY c.id ORDER BY x.entry_id) AS rn
  FROM "TendingCheckin" c
  CROSS JOIN LATERAL (
    SELECT e AS entry_id FROM "TendingCoordinationCycle" y CROSS JOIN unnest(y."entryIds") AS e WHERE y.id = c."coordinationCycleId"
    UNION SELECT r."tendingEntryId" FROM "TendingResponse" r WHERE r."checkinId" = c.id
    UNION SELECT o."tendingEntryId" FROM "TendingEntryOutcome" o WHERE o."checkinId" = c.id
    UNION SELECT a."tendingEntryId" FROM "TendingAdjustment" a WHERE a."checkinId" = c.id
  ) x
) z
ORDER BY submitted_at, checkin_id, entry_id;
INSERT INTO app_migration.checkin_map (checkin_id, entry_id, user_id, session_id, submitted_at, is_first, new_id)
SELECT NULL, r."tendingEntryId", r."userId", e."sessionId", r."submittedAt", true, app_migration.mint(r."submittedAt")
FROM "TendingResponse" r JOIN "TendingEntry" e ON e.id = r."tendingEntryId"
WHERE r."checkinId" IS NULL
  AND NOT EXISTS (SELECT 1 FROM app_migration.checkin_map m WHERE m.entry_id = r."tendingEntryId" AND m.user_id = r."userId")
ORDER BY r."submittedAt", r.id;
SELECT app_migration.note('14', 'orphan TendingResponse → synthetic check-in (added rows)', count(*))
FROM app_migration.checkin_map WHERE checkin_id IS NULL;
SELECT app_migration.note('14', 'orphan TendingResponse joined an existing check-in of its (entry, user)', count(*))
FROM "TendingResponse" r
WHERE r."checkinId" IS NULL
  AND EXISTS (SELECT 1 FROM app_migration.checkin_map m WHERE m.entry_id = r."tendingEntryId" AND m.user_id = r."userId" AND m.checkin_id IS NOT NULL);
INSERT INTO app_migration.shape_map
SELECT 'follow_up_checkin', coalesce(checkin_id::text, 'orphan') || ':' || entry_id::text || ':' || user_id::text, new_id
FROM app_migration.checkin_map;

INSERT INTO follow_up_checkin (id, follow_up_id, participant_id, next_action, continue_choice, reflection_summary, payload, submitted_at, created_at)
SELECT m.new_id, m.entry_id, p.id, c."nextAction"::text::next_action,
       coalesce(c."continueChoice", (SELECT r."continueChoice" FROM "TendingResponse" r
                                     WHERE m.checkin_id IS NULL AND r."tendingEntryId" = m.entry_id AND r."userId" = m.user_id))::text::continue_choice,
       c."reflectionSummary",
       jsonb_build_object(
         'responses', coalesce((
            SELECT jsonb_agg(jsonb_build_object('id', r.id, 'status', r.status, 'reflection', r.reflection,
                                                'continueChoice', r."continueChoice", 'submittedAt', r."submittedAt")
                             ORDER BY r."submittedAt", r.id)
            FROM "TendingResponse" r
            WHERE r."tendingEntryId" = m.entry_id AND r."userId" = m.user_id
              AND (r."checkinId" = m.checkin_id OR r."checkinId" IS NULL)), '[]'::jsonb),
         'entryOutcomes', coalesce((
            SELECT jsonb_agg(jsonb_build_object('id', o.id, 'responseId', o."responseId", 'followThroughStatus', o."followThroughStatus",
                                                'helpfulnessStatus', o."helpfulnessStatus", 'blockerCategories', to_jsonb(o."blockerCategories"),
                                                'whatHappened', o."whatHappened", 'helpedNeed', o."helpedNeed", 'blockerNote', o."blockerNote",
                                                'stillWorthTrying', o."stillWorthTrying", 'createdAt', o."createdAt")
                             ORDER BY o."createdAt", o.id)
            FROM "TendingEntryOutcome" o WHERE o."checkinId" = m.checkin_id AND o."tendingEntryId" = m.entry_id), '[]'::jsonb),
         'adjustments', coalesce((
            SELECT jsonb_agg(jsonb_build_object('id', a.id, 'privacyScope', a."privacyScope", 'revisedCommitmentText', a."revisedCommitmentText",
                                                'revisedCadence', a."revisedCadence", 'revisedScope', a."revisedScope",
                                                'revisedSuccessCriteria', a."revisedSuccessCriteria", 'reason', a.reason,
                                                'blockerAddressed', to_jsonb(a."blockerAddressed"), 'createdAt', a."createdAt")
                             ORDER BY a."createdAt", a.id)
            FROM "TendingAdjustment" a WHERE a."checkinId" = m.checkin_id AND a."tendingEntryId" = m.entry_id), '[]'::jsonb),
         'partialClosures', coalesce((
            SELECT jsonb_agg(jsonb_build_object('id', pc.id, 'responseId', pc."tendingResponseId", 'followUpId', pc."tendingEntryId",
                                                'resolution', pc.resolution, 'createdAt', pc."createdAt")
                             ORDER BY pc."createdAt", pc.id)
            FROM "TendingResponsePartialClosure" pc JOIN "TendingResponse" r ON r.id = pc."tendingResponseId"
            WHERE r."tendingEntryId" = m.entry_id AND r."userId" = m.user_id
              AND (r."checkinId" = m.checkin_id OR r."checkinId" IS NULL)), '[]'::jsonb),
         'needOutcomes', coalesce((
            SELECT jsonb_agg(jsonb_build_object('id', n.id, 'needId', ns.need_id, 'needLabel', n."needLabel",
                                                'sourceParticipantId', sp.id, 'resolutionStatus', n."resolutionStatus", 'note', n.note,
                                                'changedNeedLabel', n."changedNeedLabel", 'nextAction', n."nextAction", 'createdAt', n."createdAt")
                             ORDER BY n."createdAt", n.id)
            FROM "TendingNeedOutcome" n
            LEFT JOIN need_share ns ON ns.need_id = app_migration.as_uuid(n."needId")
            LEFT JOIN participant sp ON sp.session_id = n."sessionId" AND sp.user_id = app_migration.as_uuid(n."sourceUserId")
            WHERE m.is_first AND n."checkinId" = m.checkin_id), '[]'::jsonb),
         'carriedNotes', coalesce((
            SELECT jsonb_agg(jsonb_build_object('noteId', b.id, 'content', b.content, 'shareConsentAt', b."shareConsentAt", 'createdAt', b."createdAt")
                             ORDER BY b."createdAt", b.id)
            FROM "TendingBetweenPeriodNote" b
            WHERE m.is_first AND b."selectedForCheckinId" = m.checkin_id AND b."consentToShareWithPartner"), '[]'::jsonb)
       ),
       m.submitted_at, coalesce(c."createdAt", m.submitted_at)
FROM app_migration.checkin_map m
JOIN participant p ON p.session_id = m.session_id AND p.user_id = m.user_id
LEFT JOIN "TendingCheckin" c ON c.id = m.checkin_id
ORDER BY m.submitted_at, m.new_id;

-- Conservation per concept: Σ array lengths = old child rows (incl. orphans).
SELECT app_migration.assert(got = want, format('step 14: payload.%s holds %s entries for %s old rows', k, got, want))
FROM (
  SELECT k,
         (SELECT coalesce(sum(jsonb_array_length(payload -> k)), 0) FROM follow_up_checkin) AS got,
         CASE k WHEN 'responses' THEN (SELECT count(*) FROM "TendingResponse")
                WHEN 'entryOutcomes' THEN (SELECT count(*) FROM "TendingEntryOutcome")
                WHEN 'adjustments' THEN (SELECT count(*) FROM "TendingAdjustment")
                WHEN 'partialClosures' THEN (SELECT count(*) FROM "TendingResponsePartialClosure")
                WHEN 'needOutcomes' THEN (SELECT count(*) FROM "TendingNeedOutcome")
                WHEN 'carriedNotes' THEN (SELECT count(*) FROM "TendingBetweenPeriodNote"
                                          WHERE "selectedForCheckinId" IS NOT NULL AND "consentToShareWithPartner")
         END AS want
  FROM unnest(ARRAY['responses', 'entryOutcomes', 'adjustments', 'partialClosures', 'needOutcomes', 'carriedNotes']) AS k
) x;
SELECT app_migration.assert(a = b, format('step 14: %s follow_up_checkin rows for %s mapped (check-in, entry) pairs', a, b))
FROM (SELECT (SELECT count(*) FROM follow_up_checkin) AS a, (SELECT count(*) FROM app_migration.checkin_map) AS b) x;

-- follow_up_note ← TendingBetweenPeriodNote (ids kept); selectedForCheckinId →
-- carried_into_checkin_id (the check-in's first row); consent flags → the copy above.
INSERT INTO follow_up_note (id, participant_id, content, carry_forward, carried_into_checkin_id, created_at, updated_at)
SELECT b.id, p.id, b.content, b."carryForwardSelected", m.new_id, b."createdAt", b."updatedAt"
FROM "TendingBetweenPeriodNote" b
JOIN participant p ON p.session_id = b."sessionId" AND p.user_id = b."userId"
LEFT JOIN app_migration.checkin_map m ON m.checkin_id = b."selectedForCheckinId" AND m.is_first;
SELECT app_migration.assert(a = b, format('step 14: %s follow_up_note rows for %s "TendingBetweenPeriodNote" rows', a, b))
FROM (SELECT (SELECT count(*) FROM follow_up_note) AS a, (SELECT count(*) FROM "TendingBetweenPeriodNote") AS b) x;

-- reminder ← TendingReminder (ids kept; status text → enum, P24b checked).
INSERT INTO reminder (id, user_id, follow_up_id, scope, remind_at, cadence, note, status, created_at, updated_at)
SELECT r.id, r."userId", r."tendingEntryId", r.scope::text::reminder_scope, r."remindAt", r.cadence, r.note, r.status::reminder_status,
       r."createdAt", r."updatedAt"
FROM "TendingReminder" r;
SELECT app_migration.note('14', 'TendingReminder.' || c || ' dropped (reminder keys on user + follow_up)', n)
FROM (SELECT 'checkinId' AS c, count(*) FILTER (WHERE "checkinId" IS NOT NULL) AS n FROM "TendingReminder"
      UNION ALL SELECT 'sessionId', count(*) FROM "TendingReminder") x;
SELECT app_migration.assert(a = b, format('step 14: %s reminder rows for %s "TendingReminder" rows', a, b))
FROM (SELECT (SELECT count(*) FROM reminder) AS a, (SELECT count(*) FROM "TendingReminder") AS b) x;
SELECT app_migration.note('14', 'TendingCoordinationCycle dropped (→ response_deadline_at/summary + v_follow_up_cycle)', count(*))
FROM "TendingCoordinationCycle";

-- ============================================================================
-- 3k. Renames: invitation, mood_reading, regulation_event, user_memory
-- ============================================================================

-- ---- Renames that hang off participant: invitation, mood_reading, regulation_event, user_memory.
-- invitation (ids kept): invitedById → participant; messageConfirmed folded into
-- message_confirmed_at (createdAt when the flag is set without a time);
-- accepted_by_user_id (new, P3 §6) = the session's one participant other than
-- the inviter, a vanished acceptor included (their tombstone keeps the id;
-- P14b checked there is exactly one).
INSERT INTO invitation (id, session_id, invited_by_participant_id, accepted_by_user_id, name, status, message_confirmed_at, expires_at,
                        accepted_at, declined_at, decline_reason, created_at, updated_at)
SELECT i.id, i."sessionId", pi.id,
       CASE WHEN i.status = 'ACCEPTED' THEN
         (SELECT DISTINCT p.user_id FROM app_migration.pair p WHERE p.session_id = i."sessionId" AND p.user_id <> i."invitedById")
       END,
       i.name, i.status::text::invitation_status,
       coalesce(i."messageConfirmedAt", CASE WHEN i."messageConfirmed" THEN i."createdAt" END),
       i."expiresAt", i."acceptedAt", i."declinedAt", i."declineReason", i."createdAt",
       greatest(i."createdAt", i."acceptedAt", i."declinedAt", i."messageConfirmedAt")
FROM "Invitation" i
JOIN "Session" s ON s.id = i."sessionId"
JOIN participant pi ON pi.session_id = i."sessionId" AND pi.user_id = i."invitedById";
SELECT app_migration.note('3', 'invitation accepted by a vanished member (accepted_by_user_id = the tombstone)', count(*))
FROM invitation i JOIN app_migration.vanished v ON v.user_id = i.accepted_by_user_id;
SELECT app_migration.assert(a = b, format('invitation: %s rows for %s "Invitation" rows', a, b))
FROM (SELECT (SELECT count(*) FROM invitation) AS a, (SELECT count(*) FROM "Invitation") AS b) x;

-- mood_reading ← EmotionalReading (ids kept; stage dropped).
INSERT INTO mood_reading (id, participant_id, intensity, context, recorded_at, created_at)
SELECT e.id, p.id, e.intensity, e.context, e.timestamp, e.timestamp
FROM "EmotionalReading" e
JOIN "UserVessel" v ON v.id = e."vesselId"
JOIN participant p ON p.session_id = v."sessionId" AND p.user_id = v."userId";
SELECT app_migration.assert(a = b, format('mood_reading: %s rows for %s "EmotionalReading" rows', a, b))
FROM (SELECT (SELECT count(*) FROM mood_reading) AS a, (SELECT count(*) FROM "EmotionalReading") AS b) x;

-- regulation_event ← EmotionalExerciseCompletion (ids kept).
INSERT INTO regulation_event (id, participant_id, type, intensity_before, intensity_after, completed_at, created_at)
SELECT e.id, p.id, e.type::text::regulation_type, e."intensityBefore", e."intensityAfter", e."completedAt", e."completedAt"
FROM "EmotionalExerciseCompletion" e
JOIN participant p ON p.session_id = e."sessionId" AND p.user_id = e."userId";
SELECT app_migration.assert(a = b, format('regulation_event: %s rows for %s "EmotionalExerciseCompletion" rows', a, b))
FROM (SELECT (SELECT count(*) FROM regulation_event) AS a, (SELECT count(*) FROM "EmotionalExerciseCompletion") AS b) x;

-- user_memory ← UserMemory (ids kept; suggestedBy → suggested_text).
INSERT INTO user_memory (id, user_id, session_id, content, category, status, source, suggested_text, created_at, updated_at)
SELECT id, "userId", "sessionId", content, category::text::memory_category, status::text::memory_status, source::text::memory_source,
       "suggestedBy", "createdAt", "updatedAt"
FROM "UserMemory";
SELECT app_migration.assert(a = b, format('user_memory: %s rows for %s "UserMemory" rows', a, b))
FROM (SELECT (SELECT count(*) FROM user_memory) AS a, (SELECT count(*) FROM "UserMemory") AS b) x;

-- ============================================================================
-- 3l. Steps 15–16: reflection, feature_state
-- ============================================================================

-- ---- Step 15: reflection ← InnerWorkSession (ids kept; summary_doc parsed
-- from text, P28a checked; linked_at = updatedAt of the linking row);
-- reflection_message ← InnerWorkMessage; takeaway ← SessionTakeaway
-- (resolved without a time → updatedAt); takeaway_link ← TakeawayLink.
-- linkedAtStage, linkedTrigger, linkedAtMessageId, contentEmbedding/embedding dropped.
INSERT INTO reflection (id, user_id, title, theme, status, summary, summary_doc, linked_session_id, linked_at, context_snapshot,
                        distilled_at, created_at, updated_at)
SELECT s.id, s."userId", s.title, s.theme, s.status::text::reflection_status, s.summary, s."conversationSummary"::jsonb,
       s."linkedPartnerSessionId", CASE WHEN s."linkedPartnerSessionId" IS NOT NULL THEN s."updatedAt" END,
       s."contextSummarySnapshot", s."distilledAt", s."createdAt", s."updatedAt"
FROM "InnerWorkSession" s;
INSERT INTO reflection_message (id, reflection_id, role, content, created_at)
SELECT id, "sessionId", role::text::message_role, content, timestamp FROM "InnerWorkMessage";
INSERT INTO takeaway (id, reflection_id, content, theme, source, type, position, resolved_at, created_at, updated_at)
SELECT id, "sessionId", content, theme, source::text::takeaway_source, type::text::takeaway_type, position,
       CASE WHEN resolved OR "resolvedAt" IS NOT NULL THEN coalesce("resolvedAt", "updatedAt") END, "createdAt", "updatedAt"
FROM "SessionTakeaway";
INSERT INTO takeaway_link (source_id, target_id, link_type, similarity, created_at)
SELECT "sourceId", "targetId", "linkType"::text::takeaway_link_type, similarity::real, "createdAt" FROM "TakeawayLink";

SELECT app_migration.note('15', 'InnerWorkSession.' || c || ' dropped', n)
FROM (SELECT 'linkedAtStage' AS c, count(*) FILTER (WHERE "linkedAtStage" IS NOT NULL) AS n FROM "InnerWorkSession"
      UNION ALL SELECT 'linkedTrigger', count(*) FILTER (WHERE "linkedTrigger" IS NOT NULL) FROM "InnerWorkSession"
      UNION ALL SELECT 'linkedAtMessageId', count(*) FILTER (WHERE "linkedAtMessageId" IS NOT NULL) FROM "InnerWorkSession"
      UNION ALL SELECT 'contentEmbedding (D8)', count(*) FILTER (WHERE "contentEmbedding" IS NOT NULL) FROM "InnerWorkSession") x
WHERE n > 0;
SELECT app_migration.note('15', t || ' dropped (D8)', n)
FROM (SELECT 'SessionTakeaway.embedding' AS t, count(*) FILTER (WHERE embedding IS NOT NULL) AS n FROM "SessionTakeaway"
      UNION ALL SELECT 'UserVessel.contentEmbedding', count(*) FILTER (WHERE "contentEmbedding" IS NOT NULL) FROM "UserVessel") x
WHERE n > 0;
SELECT app_migration.assert(a = b AND c = d AND e = f AND g = h,
         format('step 15: reflection %s/%s, reflection_message %s/%s, takeaway %s/%s, takeaway_link %s/%s', a, b, c, d, e, f, g, h))
FROM (SELECT (SELECT count(*) FROM reflection) AS a, (SELECT count(*) FROM "InnerWorkSession") AS b,
             (SELECT count(*) FROM reflection_message) AS c, (SELECT count(*) FROM "InnerWorkMessage") AS d,
             (SELECT count(*) FROM takeaway) AS e, (SELECT count(*) FROM "SessionTakeaway") AS f,
             (SELECT count(*) FROM takeaway_link) AS g, (SELECT count(*) FROM "TakeawayLink") AS h) x;

-- ---- Step 16: feature_state — one document per (user, feature) that has
-- any source row; each old row becomes an array element (to_jsonb of the row
-- minus userId), single rows become objects (null when absent). Documents:
--   meditation        {sessions[], favorites[], scripts[], preferences, stats}
--   gratitude         {entries[], preferences}
--   needs_assessment  {scores[] (+needSlug from the dropped taxonomy), state}
--   people            {persons[] each with mentions[]}
-- favorites[] is not in spec §1.7's key summary; MeditationFavorite is in its
-- Absorbs list, so it needs a key.
INSERT INTO feature_state (user_id, feature, doc, created_at, updated_at)
SELECT u.id, 'meditation', jsonb_build_object(
         'sessions', coalesce((SELECT jsonb_agg(to_jsonb(x) - 'userId' ORDER BY x."startedAt", x.id) FROM "MeditationSession" x WHERE x."userId" = u.id), '[]'::jsonb),
         'favorites', coalesce((SELECT jsonb_agg(to_jsonb(x) - 'userId' ORDER BY x."savedAt", x.id) FROM "MeditationFavorite" x WHERE x."userId" = u.id), '[]'::jsonb),
         'scripts', coalesce((SELECT jsonb_agg(to_jsonb(x) - 'userId' ORDER BY x."createdAt", x.id) FROM "SavedMeditation" x WHERE x."userId" = u.id), '[]'::jsonb),
         'preferences', (SELECT to_jsonb(x) - 'userId' FROM "MeditationPreferences" x WHERE x."userId" = u.id),
         'stats', (SELECT to_jsonb(x) - 'userId' FROM "MeditationStats" x WHERE x."userId" = u.id)),
       u."createdAt", now()
FROM "User" u
WHERE EXISTS (SELECT 1 FROM "MeditationSession" x WHERE x."userId" = u.id)
   OR EXISTS (SELECT 1 FROM "MeditationFavorite" x WHERE x."userId" = u.id)
   OR EXISTS (SELECT 1 FROM "SavedMeditation" x WHERE x."userId" = u.id)
   OR EXISTS (SELECT 1 FROM "MeditationPreferences" x WHERE x."userId" = u.id)
   OR EXISTS (SELECT 1 FROM "MeditationStats" x WHERE x."userId" = u.id);

INSERT INTO feature_state (user_id, feature, doc, created_at, updated_at)
SELECT u.id, 'gratitude', jsonb_build_object(
         'entries', coalesce((SELECT jsonb_agg(to_jsonb(x) - 'userId' ORDER BY x."createdAt", x.id) FROM "GratitudeEntry" x WHERE x."userId" = u.id), '[]'::jsonb),
         'preferences', (SELECT to_jsonb(x) - 'userId' FROM "GratitudePreferences" x WHERE x."userId" = u.id)),
       u."createdAt", now()
FROM "User" u
WHERE EXISTS (SELECT 1 FROM "GratitudeEntry" x WHERE x."userId" = u.id)
   OR EXISTS (SELECT 1 FROM "GratitudePreferences" x WHERE x."userId" = u.id);

INSERT INTO feature_state (user_id, feature, doc, created_at, updated_at)
SELECT u.id, 'needs_assessment', jsonb_build_object(
         'scores', coalesce((SELECT jsonb_agg((to_jsonb(x) - 'userId') || jsonb_build_object('needSlug', n.slug) ORDER BY x."createdAt", x.id)
                             FROM "NeedScore" x JOIN "Need" n ON n.id = x."needId" WHERE x."userId" = u.id), '[]'::jsonb),
         'state', (SELECT to_jsonb(x) - 'userId' FROM "NeedsAssessmentState" x WHERE x."userId" = u.id)),
       u."createdAt", now()
FROM "User" u
WHERE EXISTS (SELECT 1 FROM "NeedScore" x WHERE x."userId" = u.id)
   OR EXISTS (SELECT 1 FROM "NeedsAssessmentState" x WHERE x."userId" = u.id);

INSERT INTO feature_state (user_id, feature, doc, created_at, updated_at)
SELECT u.id, 'people', jsonb_build_object(
         'persons', coalesce((
           SELECT jsonb_agg((to_jsonb(x) - 'userId') || jsonb_build_object('mentions', coalesce((
                    SELECT jsonb_agg(to_jsonb(m) - 'userId' ORDER BY m."createdAt", m.id) FROM "PersonMention" m WHERE m."personId" = x.id), '[]'::jsonb))
                  ORDER BY x."firstMentioned", x.id)
           FROM "Person" x WHERE x."userId" = u.id), '[]'::jsonb)),
       u."createdAt", now()
FROM "User" u
WHERE EXISTS (SELECT 1 FROM "Person" x WHERE x."userId" = u.id);

-- Conservation: Σ array lengths per feature key = old row counts; one
-- document per single-row table row.
SELECT app_migration.assert(got = want, format('step 16: feature_state %s holds %s for %s old rows', what, got, want))
FROM (
  SELECT 'meditation.sessions' AS what, (SELECT coalesce(sum(jsonb_array_length(doc -> 'sessions')), 0) FROM feature_state WHERE feature = 'meditation') AS got, (SELECT count(*) FROM "MeditationSession") AS want
  UNION ALL SELECT 'meditation.favorites', (SELECT coalesce(sum(jsonb_array_length(doc -> 'favorites')), 0) FROM feature_state WHERE feature = 'meditation'), (SELECT count(*) FROM "MeditationFavorite")
  UNION ALL SELECT 'meditation.scripts', (SELECT coalesce(sum(jsonb_array_length(doc -> 'scripts')), 0) FROM feature_state WHERE feature = 'meditation'), (SELECT count(*) FROM "SavedMeditation")
  UNION ALL SELECT 'meditation.preferences', (SELECT count(*) FROM feature_state WHERE feature = 'meditation' AND jsonb_typeof(doc -> 'preferences') = 'object'), (SELECT count(*) FROM "MeditationPreferences")
  UNION ALL SELECT 'meditation.stats', (SELECT count(*) FROM feature_state WHERE feature = 'meditation' AND jsonb_typeof(doc -> 'stats') = 'object'), (SELECT count(*) FROM "MeditationStats")
  UNION ALL SELECT 'gratitude.entries', (SELECT coalesce(sum(jsonb_array_length(doc -> 'entries')), 0) FROM feature_state WHERE feature = 'gratitude'), (SELECT count(*) FROM "GratitudeEntry")
  UNION ALL SELECT 'gratitude.preferences', (SELECT count(*) FROM feature_state WHERE feature = 'gratitude' AND jsonb_typeof(doc -> 'preferences') = 'object'), (SELECT count(*) FROM "GratitudePreferences")
  UNION ALL SELECT 'needs_assessment.scores', (SELECT coalesce(sum(jsonb_array_length(doc -> 'scores')), 0) FROM feature_state WHERE feature = 'needs_assessment'), (SELECT count(*) FROM "NeedScore")
  UNION ALL SELECT 'needs_assessment.state', (SELECT count(*) FROM feature_state WHERE feature = 'needs_assessment' AND jsonb_typeof(doc -> 'state') = 'object'), (SELECT count(*) FROM "NeedsAssessmentState")
  UNION ALL SELECT 'people.persons', (SELECT coalesce(sum(jsonb_array_length(doc -> 'persons')), 0) FROM feature_state WHERE feature = 'people'), (SELECT count(*) FROM "Person")
  UNION ALL SELECT 'people.persons[].mentions', (SELECT coalesce(sum(jsonb_array_length(pp -> 'mentions')), 0) FROM feature_state, jsonb_array_elements(doc -> 'persons') pp WHERE feature = 'people'), (SELECT count(*) FROM "PersonMention")
) x;

-- ============================================================================
-- 3m. Steps 17–18: text-id audit, brain_activity, after-counts
-- ============================================================================

-- ---- Step 17: the FK-less text ids. Each became a real FK above (or was
-- dropped, reported where it held a value); P25 refused any that is not
-- uuid-shaped. Here: every non-null source value resolved.
SELECT app_migration.assert(n = 0, format('step 17: %s.%s: %s non-null value(s) did not resolve', t, c, n))
FROM (
  SELECT 'Message' AS t, 'forUserId' AS c, (SELECT count(*) FROM "Message" m WHERE m."forUserId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM message x WHERE x.id = m.id)) AS n
  UNION ALL SELECT 'ReconcilerResult', 'guesserId/subjectId', (SELECT count(*) FROM "ReconcilerResult" r WHERE NOT EXISTS (SELECT 1 FROM reconciler_result x WHERE x.id = r.id))
  UNION ALL SELECT 'ReconcilerShareOffer', 'userId', (SELECT count(*) FROM "ReconcilerShareOffer" o WHERE NOT EXISTS (SELECT 1 FROM context_share_offer x WHERE x.id = o.id))
  UNION ALL SELECT 'Stage4ProposalRevision', 'actorUserId', (SELECT count(*) FROM "Stage4ProposalRevision" r JOIN proposal_revision x ON x.id = r.id
                                                             WHERE r."actorUserId" IS NOT NULL AND x.actor_participant_id IS NULL)
  UNION ALL SELECT 'Stage4Closure', 'closedByUserId', (SELECT count(*) FROM "Stage4Closure" c JOIN session_closure x ON x.session_id = c."sessionId"
                                                       WHERE c."closedByUserId" IS NOT NULL AND x.closed_by_participant_id IS NULL)
  UNION ALL SELECT 'TendingEntry', 'ownerUserId', (SELECT count(*) FROM "TendingEntry" e JOIN follow_up x ON x.id = e.id
                                                   WHERE e."ownerUserId" IS NOT NULL AND x.owner_participant_id IS NULL)
  UNION ALL SELECT 'Stage4NeedDeclination', 'userId', (SELECT count(*) FROM "Stage4NeedDeclination" d
                                                       WHERE NOT EXISTS (SELECT 1 FROM participant p WHERE p.session_id = d."sessionId" AND p.user_id = app_migration.as_uuid(d."userId")))
  UNION ALL SELECT 'TendingNeedOutcome', 'sourceUserId', (SELECT count(*) FROM "TendingNeedOutcome" n
                                                          WHERE n."sourceUserId" IS NOT NULL
                                                            AND NOT EXISTS (SELECT 1 FROM participant p WHERE p.session_id = n."sessionId" AND p.user_id = app_migration.as_uuid(n."sourceUserId")))
) x;
SELECT app_migration.note('17', 'TendingNeedOutcome.needId kept as label (not a shared need)', count(*))
FROM "TendingNeedOutcome" n
WHERE n."needId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM need_share ns WHERE ns.need_id = app_migration.as_uuid(n."needId"));
SELECT app_migration.note('17', 'GratitudeEntry/MeditationSession.linkedConflictId kept inside the feature document', count(*))
FROM (SELECT "linkedConflictId" FROM "GratitudeEntry" WHERE "linkedConflictId" IS NOT NULL
      UNION ALL SELECT "linkedConflictId" FROM "MeditationSession" WHERE "linkedConflictId" IS NOT NULL) x;

-- ---- Step 18: brain_activity ← BrainActivity (ids kept; innerWorkSessionId →
-- reflection_id; participant_id NULL for history; cost float → numeric(10,6)).
INSERT INTO brain_activity (id, session_id, reflection_id, participant_id, turn_id, activity_type, call_type, model, input, output, metadata,
                            structured_output, token_count_input, token_count_output, duration_ms, cost, status, created_at, completed_at, updated_at)
SELECT id, "sessionId", "innerWorkSessionId", NULL, "turnId", "activityType"::text::activity_type, "callType"::text::brain_call_type, model,
       app_migration.jnull(input), app_migration.jnull(output), app_migration.jnull(metadata), app_migration.jnull("structuredOutput"),
       "tokenCountInput", "tokenCountOutput", "durationMs", round(cost::numeric, 6), status::text::activity_status,
       "createdAt", "completedAt", coalesce("completedAt", "createdAt")
FROM "BrainActivity";
SELECT app_migration.assert(a = b, format('step 18: %s brain_activity rows for %s "BrainActivity" rows', a, b))
FROM (SELECT (SELECT count(*) FROM brain_activity) AS a, (SELECT count(*) FROM "BrainActivity") AS b) x;

-- Tables dropped by decision, counted.
SELECT app_migration.note('19', 'StrategyRanking dropped: ranking is not in the product flow (plan step 13, A-Q4-adjacent)', count(*)) FROM "StrategyRanking";
SELECT app_migration.note('19', 'RefinementAttemptCounter dropped: becomes the count of rounds (spec §1.2); counter vs round reported', count(*)) FROM "RefinementAttemptCounter";
SELECT app_migration.note('19', 'Stage4NeedCoverage dropped: computed: v_need_coverage (plan step 8)', count(*)) FROM "Stage4NeedCoverage";
SELECT app_migration.note('19', 'TendingCoordinationCycle dropped: response_deadline_at/summary on follow_up + v_follow_up_cycle (plan step 14)', count(*)) FROM "TendingCoordinationCycle";
SELECT app_migration.note('19', 'Insight dropped: derivable AI output (spec §1.7)', count(*)) FROM "Insight";
SELECT app_migration.note('19', 'RecurringTheme dropped: derivable: v_reflection_theme (plan step 15)', count(*)) FROM "RecurringTheme";
SELECT app_migration.note('19', 'Need dropped: the 19-row taxonomy moves to shared/src/constants/needs.ts (spec A-Q4)', count(*)) FROM "Need";
SELECT app_migration.note('19', 'SharedVessel dropped: 1:1 container with no columns; children key on session_id (spec §1.1)', count(*)) FROM "SharedVessel";

-- Row counts after the copy: the 47 target tables.
DO $$
DECLARE
  t text;
  n bigint;
BEGIN
  FOR t IN SELECT c.relname FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace
           WHERE s.nspname = 'public' AND c.relkind = 'r' AND c.relname ~ '^[a-z]' AND c.relname <> '_prisma_migrations'
           ORDER BY c.relname
  LOOP
    EXECUTE format('SELECT count(*) FROM public.%I', t) INTO n;
    INSERT INTO app_migration.row_counts VALUES ('after', t, n);
  END LOOP;
END
$$;

-- ============================================================================
-- 4. Step 19: drop the old shape
-- ============================================================================

-- ---- Step 19: drop the 68 old tables and 51 old enum types (after every
-- assertion above), and the work tables that read them. One DROP statement,
-- so the old FKs between them need no ordering.
DROP VIEW app_migration.pair, app_migration.vanished;
DROP TABLE "User", "Relationship", "RelationshipMember", "Session", "InnerWorkSession", "InnerWorkMessage", "SessionTakeaway", "TakeawayLink", "StageProgress", "UserVessel", "UserEvent", "EmotionalReading", "IdentifiedNeed", "Boundary", "UserDocument", "SharedVessel", "ConsentedContent", "CommonGround", "Agreement", "ConsentRecord", "Message", "PreSessionMessage", "EmpathyDraft", "EmpathyAttempt", "EmpathyValidation", "ReconcilerResult", "ReconcilerShareOffer", "RefinementAttemptCounter", "StrategyProposal", "StrategyProposalNeed", "Stage4ProposalSelection", "Stage4ProposalRevision", "Stage4NeedCoverage", "Stage4NeedDeclination", "Stage4Closure", "Stage4SubChat", "Stage4SubChatMessage", "TendingEntry", "TendingCheckin", "TendingCoordinationCycle", "TendingResponse", "TendingEntryOutcome", "TendingNeedOutcome", "TendingReminder", "TendingAdjustment", "TendingBetweenPeriodNote", "TendingResponsePartialClosure", "StrategyRanking", "EmotionalExerciseCompletion", "GlobalLibraryItem", "Invitation", "UserMemory", "Need", "NeedScore", "NeedsAssessmentState", "Person", "PersonMention", "Insight", "RecurringTheme", "GratitudeEntry", "GratitudePreferences", "MeditationSession", "MeditationStats", "MeditationFavorite", "MeditationPreferences", "SavedMeditation", "BrainActivity", "ValidationFeedbackDraft";
DROP TABLE app_migration.precheck, app_migration.su, app_migration.ab_slot, app_migration.checkin_map,
           app_migration.milestone_src, app_migration.disposition_ref, app_migration.proposal_need_src,
           app_migration.slot_fix, app_migration.empathy_attempt_src, app_migration.empathy_validation_src;
DROP TYPE "SessionType", "SessionStatus", "InnerWorkStatus", "TakeawaySource", "TakeawayType", "TakeawayLinkType", "StageStatus", "Attribution", "NeedCategory", "AgreementType", "AgreementStatus", "ConsentContentType", "ConsentDecision", "MessageRole", "EmpathyStatus", "SharedContentDeliveryStatus", "ReconcilerShareStatus", "StrategySource", "Stage4ProposalKind", "Stage4ProposalStatus", "Stage4SelectionDecision", "Stage4ClosureKind", "Stage4ClosureReason", "TendingEntryType", "TendingEntryStatus", "TendingEntryScope", "TendingFollowThroughStatus", "TendingHelpfulnessStatus", "TendingBlockerCategory", "TendingNeedResolutionStatus", "TendingNextAction", "TendingReminderScope", "TendingCoordinationStatus", "Stage4SubChatAnchor", "Stage4SubChatStatus", "ContinueChoice", "PartialClosureResolution", "ExerciseType", "GlobalLibrarySource", "InvitationStatus", "MemoryCategory", "MemoryStatus", "MemorySource", "NeedsCategory", "MentionSourceType", "InsightType", "MeditationType", "FavoriteType", "BrainActivityCallType", "ActivityType", "ActivityStatus";

DO $$
DECLARE
  extra text;
BEGIN
  SELECT string_agg(c.relname, ', ' ORDER BY c.relname) INTO extra
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p', 'v', 'm', 'f')
    AND c.relname !~ '^[a-z_]';
  PERFORM app_migration.assert(extra IS NULL, format('step 19: old relation(s) remain: %s', extra));
  SELECT string_agg(t.typname, ', ' ORDER BY t.typname) INTO extra
  FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace
  WHERE n.nspname = 'public' AND t.typtype = 'e' AND t.typname !~ '^[a-z_]';
  PERFORM app_migration.assert(extra IS NULL, format('step 19: old enum type(s) remain: %s', extra));
  PERFORM app_migration.assert(
    (SELECT count(*) FROM pg_tables WHERE schemaname = 'public' AND tablename <> '_prisma_migrations') = 47,
    format('step 19: %s tables in public, expected the 47 of the target', (SELECT count(*) FROM pg_tables WHERE schemaname = 'public' AND tablename <> '_prisma_migrations')));
END
$$;

-- ============================================================================
-- 5. Trailer (backend/scripts/target-shape/trailer.sql, sql-only.sql spliced in)
-- ============================================================================

-- ============================================================================
-- trailer.sql — section 5 of the target_shape migration (TS-7). Hand-maintained;
-- backend/scripts/gen-target-migration.ts appends it to the generated sections
-- and splices backend/scripts/target-shape/sql-only.sql in, verbatim, at the
-- `-- @@include sql-only.sql` line. It never runs alone: it runs in the same
-- transaction, after the copies and after the old tables are dropped (plan §3
-- step 20), so a failure here also rolls everything back.
--
-- Spec: docs/backend/data-model/schema-target-2026-10.md §1 (Keys lines), §4
-- (views, functions, the anonymisation walk), §7 (invariants);
-- phase3-design-summary.md §4–§6 where the spec re-bases them.
--
-- Contents, in order:
--   T1  the intensity domain, and the three columns the spec types with it
--   T2  sql-only.sql (generated columns, sql_ partial / expression indexes)
--   T3  CHECK constraints (every §1 Keys CHECK; jsonb_typeof on every jsonb column)
--   T4  app.* functions — invoker helpers, then the SECURITY DEFINER helpers and
--       writers handed to mwf_job in the TS-1 order (GRANT CREATE → ALTER OWNER
--       → REVOKE CREATE → SET ROLE mwf_job for REVOKE/GRANT EXECUTE → RESET ROLE)
--   T5  triggers (the T-* set and touch_updated_at ×35)
--   T6  views (security_invoker = true), SELECT to mwf_app
--   T7  grants (mwf_job, mwf_ops, mwf_auth; mwf_app: views and EXECUTE only)
--   T8  catalog assertions (plan step 20) and invariant checks over the
--       migrated rows (a deferred/BEFORE trigger only sees rows written after
--       it exists), then the cleanup of the migration's work objects
--
-- Not here: RLS ENABLE/FORCE and policies (TS-16); the milestone seed (it
-- precedes step 7, because participant_milestone → milestone is RESTRICT).
-- ============================================================================

-- ---------------------------------------------------------------------------
-- T1. intensity domain (spec §3): int 1..10. The prechecks (P27) proved every
-- copied value is in range, so the retype cannot fail on data.
-- ---------------------------------------------------------------------------
CREATE DOMAIN intensity AS integer CHECK (VALUE BETWEEN 1 AND 10);
ALTER TABLE mood_reading ALTER COLUMN intensity TYPE intensity;
ALTER TABLE regulation_event
  ALTER COLUMN intensity_before TYPE intensity,
  ALTER COLUMN intensity_after TYPE intensity;

-- ---------------------------------------------------------------------------
-- T2. sql-only.sql, verbatim (TS-6): generated columns, then sql_ indexes.
-- ---------------------------------------------------------------------------
-- ============================================================================
-- sql-only.sql — target shape, October 2026 (TS-6)
--
-- Spec: docs/backend/data-model/schema-target-2026-10.md (§1 Keys lines, §5).
--
-- The objects `prisma migrate diff` cannot create but `prisma db pull` CAN
-- see, so they must be created exactly this way for backend/prisma/schema.prisma
-- to stay equal to a `db pull` of the migrated database:
--   1. the two generated columns (user.name, consent.target_kind);
--   2. the `sql_`-prefixed partial / expression indexes (spec §5 "Lives only in
--      migration SQL"; never give a Prisma index one of these names).
--
-- INPUT TO TS-7: the migration generator appends this file, verbatim, to the
-- trailer of the one-shot migration, after the tables exist. It runs AFTER the
-- Prisma-generated DDL (`migrate diff --from-empty --to-schema`), which creates
-- user.name and consent.target_kind as plain columns; section 1 replaces them.
-- The data migration must not write either column (they are GENERATED).
--
-- TS-7, one trap: schema.prisma declares consent.target_kind with
-- @default(dbgenerated("\nCASE … END")) because that is how `db pull` renders
-- the generated column; `migrate diff --from-empty` turns it into a column
-- DEFAULT that references other columns, which Postgres rejects. Generate the
-- CREATE TABLE DDL from a copy of schema.prisma with that one @default removed
-- (check-schema.sh shows the exact perl one-liner); section 1 below then
-- replaces the plain column.
--
-- Verified on PG 18.6 / Prisma 7.10 (TS-6 probe, 2026-10-19): the `intensity` domain
-- and CHECK constraints are invisible to both `migrate diff` and `db pull`
-- (a domain column introspects as plain Int), so they stay in TS-7's trailer.
--
-- NOT here (also SQL-only, but invisible to `db pull` and owned by TS-7's
-- trailer): RLS + policies, triggers, CHECK constraints (incl. jsonb_typeof,
-- exclusive arcs), the `intensity` domain, views, `app.*` functions, roles,
-- grants, the `milestone` seed.
--
-- Gate: backend/scripts/target-shape/check-schema.sh applies the Prisma DDL
-- then this file to a scratch database and proves the drift diff is empty.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Generated columns (DROP the plain column Prisma created, ADD it GENERATED;
--    PG cannot convert a plain column in place). Both end up as the table's
--    last column, which is where schema.prisma declares them.
-- ----------------------------------------------------------------------------

-- §1.7 user.name
ALTER TABLE "user" DROP COLUMN "name";
ALTER TABLE "user" ADD COLUMN "name" text
  GENERATED ALWAYS AS (nullif(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')), '')) STORED;

-- §1.3 consent.target_kind — one arm per arc column, in arc order. NOT NULL per
-- the §1.3 column table (the exclusive-arc CHECK guarantees exactly one arm).
ALTER TABLE "consent" DROP COLUMN "target_kind";
ALTER TABLE "consent" ADD COLUMN "target_kind" consent_target NOT NULL
  GENERATED ALWAYS AS (
    CASE
      WHEN need_id IS NOT NULL THEN 'NEED'::consent_target
      WHEN empathy_attempt_id IS NOT NULL THEN 'EMPATHY_ATTEMPT'::consent_target
      WHEN proposal_id IS NOT NULL THEN 'PROPOSAL'::consent_target
      WHEN share_offer_id IS NOT NULL THEN 'SHARE_OFFER'::consent_target
      WHEN review_id IS NOT NULL THEN 'REVIEW'::consent_target
    END
  ) STORED;

-- @@section: indexes  (check-schema.sh splits the file here; keep this line)
-- ----------------------------------------------------------------------------
-- 2. sql_-prefixed partial unique / partial / expression indexes
--
-- `migrate diff` ignores these (gate step b), but Prisma 7.10 `db pull` DOES
-- render them — as `@unique(map: "sql_…", where: raw(…))` / `@@index(…, where:)`
-- plus `previewFeatures = [… "partialIndexes"]`, and it turns the back-relation
-- of every single-column one into a 1:1 (`Conversation?` instead of
-- `Conversation[]`). schema.prisma deliberately does not declare them
-- (spec §5); NEVER run `prisma db pull` to refresh schema.prisma.
-- ----------------------------------------------------------------------------

-- §1.1 session — A-Q3: one live session per relationship
CREATE UNIQUE INDEX "sql_session_one_live" ON "session" ("relationship_id")
  WHERE status NOT IN ('RESOLVED', 'ABANDONED', 'ARCHIVED');

-- §1.1 conversation — exactly one MAIN thread per participant
CREATE UNIQUE INDEX "sql_conversation_one_main" ON "conversation" ("participant_id")
  WHERE kind = 'MAIN';

-- §1.1 draft — one draft per sharing point (adversarial P1-5). An expression
-- index, so it cannot be a Prisma @@unique; not in §5's list by name.
CREATE UNIQUE INDEX "sql_draft_one_per_point" ON "draft"
  ("participant_id", "kind", (coalesce(about_participant_id, attempt_id, share_offer_id)));

-- §1.1 session_key / participant_key, §1.7 user_key — one live key per owner
CREATE UNIQUE INDEX "sql_session_key_live" ON "session_key" ("session_id")
  WHERE destroyed_at IS NULL;
CREATE UNIQUE INDEX "sql_participant_key_live" ON "participant_key" ("participant_id")
  WHERE destroyed_at IS NULL;
CREATE UNIQUE INDEX "sql_user_key_live" ON "user_key" ("user_id")
  WHERE destroyed_at IS NULL;

-- §1.2 empathy_attempt — one live attempt per direction
CREATE UNIQUE INDEX "sql_attempt_one_live_per_direction" ON "empathy_attempt"
  ("author_participant_id", "subject_participant_id")
  WHERE status NOT IN ('SUPERSEDED', 'VALIDATED');

-- §1.2 reconciler_result — one current result per attempt
CREATE UNIQUE INDEX "sql_result_one_current" ON "reconciler_result" ("attempt_id")
  WHERE superseded_at IS NULL;

-- §1.4 need — live needs per participant
CREATE INDEX "sql_need_live" ON "need" ("participant_id")
  WHERE deleted_at IS NULL;

-- §1.4 need_disposition — one current need per walkthrough
CREATE UNIQUE INDEX "sql_disposition_one_current" ON "need_disposition" ("participant_id")
  WHERE is_current;

-- §1.5 follow_up — the open-due job
CREATE INDEX "sql_follow_up_due" ON "follow_up" ("scheduled_for")
  WHERE status = 'SCHEDULED';

-- §1.5 reminder — the delivery job
CREATE INDEX "sql_reminder_due" ON "reminder" ("remind_at")
  WHERE status = 'SCHEDULED';

-- §1.7 user_device — Expo tokens are per install (adversarial P2)
CREATE UNIQUE INDEX "sql_user_device_token" ON "user_device" ("user_id", "push_token")
  WHERE push_token IS NOT NULL;

-- ---------------------------------------------------------------------------
-- T3. CHECK constraints. Names: chk_<table>_<rule>. Validated against the
-- migrated rows as they are added (the prechecks named in brackets guard the
-- ones old data could violate).
-- ---------------------------------------------------------------------------

-- §1.1 session [P12]
ALTER TABLE session ADD CONSTRAINT chk_session_resolved_at CHECK (status <> 'RESOLVED' OR resolved_at IS NOT NULL);
-- §1.1 participant
ALTER TABLE participant ADD CONSTRAINT chk_participant_kind_user CHECK ((kind = 'modeled') = (user_id IS NULL));
-- §1.1 conversation (anchor columns are SUBCHAT-only)
ALTER TABLE conversation
  ADD CONSTRAINT chk_conversation_anchor_kind CHECK ((kind = 'MAIN') = (anchor_kind IS NULL)),
  ADD CONSTRAINT chk_conversation_anchor_proposal CHECK (kind = 'SUBCHAT' OR anchor_proposal_id IS NULL);
-- §1.1 message [P02] — P3 §6, "humans can't author as the facilitator"
ALTER TABLE message
  ADD CONSTRAINT chk_message_user_has_sender CHECK (role <> 'USER' OR sender_participant_id IS NOT NULL),
  ADD CONSTRAINT chk_message_ai_has_no_sender CHECK (role NOT IN ('AI', 'SYSTEM') OR sender_participant_id IS NULL);
-- §1.1 draft — exclusive arc, and the arm matches the kind
ALTER TABLE draft
  ADD CONSTRAINT chk_draft_one_arc CHECK (num_nonnulls(about_participant_id, attempt_id, share_offer_id) = 1),
  ADD CONSTRAINT chk_draft_arc_matches_kind CHECK (
        (kind = 'EMPATHY') = (about_participant_id IS NOT NULL)
    AND (kind = 'VALIDATION_FEEDBACK') = (attempt_id IS NOT NULL)
    AND (kind = 'SHARE_CONTEXT') = (share_offer_id IS NOT NULL));
-- §1.1 ai_memory [P28a, P28b]
ALTER TABLE ai_memory
  ADD CONSTRAINT chk_ai_memory_one_owner CHECK (num_nonnulls(participant_id, user_id) = 1),
  ADD CONSTRAINT chk_ai_memory_global_is_user CHECK ((kind = 'GLOBAL_FACTS') = (user_id IS NOT NULL)),
  ADD CONSTRAINT chk_ai_memory_doc_object CHECK (jsonb_typeof(doc) = 'object'),
  ADD CONSTRAINT chk_ai_memory_doc_keys CHECK (
    CASE kind WHEN 'SUMMARY' THEN doc ?& ARRAY['text', 'messageCount', 'generatedAt']
              ELSE jsonb_typeof(doc -> 'facts') = 'array' END);
-- §1.1 invitation [P14a, P14b] — P3 §6
ALTER TABLE invitation ADD CONSTRAINT chk_invitation_accepted CHECK (
  status <> 'ACCEPTED' OR (accepted_at IS NOT NULL AND accepted_by_user_id IS NOT NULL));
-- §1.2 empathy_attempt [P15b, P15d]
ALTER TABLE empathy_attempt
  ADD CONSTRAINT chk_empathy_attempt_not_self CHECK (author_participant_id <> subject_participant_id),
  ADD CONSTRAINT chk_empathy_attempt_revealed_at CHECK (status NOT IN ('REVEALED', 'VALIDATED') OR revealed_at IS NOT NULL);
-- §1.2 empathy_review
ALTER TABLE empathy_review ADD CONSTRAINT chk_empathy_review_feedback_sent CHECK (feedback IS NULL OR feedback_sent_at IS NOT NULL);
-- §1.2 reconciler_result [P17f]
ALTER TABLE reconciler_result ADD CONSTRAINT chk_reconciler_result_score CHECK (alignment_score BETWEEN 0 AND 100);
-- §1.2 context_share_offer [P18a]
ALTER TABLE context_share_offer
  ADD CONSTRAINT chk_context_share_offer_accepted CHECK ((status = 'ACCEPTED') = (shared_at IS NOT NULL)),
  ADD CONSTRAINT chk_context_share_offer_declined CHECK ((status = 'DECLINED') = (declined_at IS NOT NULL));
-- §1.3 consent [P07, P19] — exclusive arc; dated decisions (P3 §6); terminal
-- revocation; a share-offer or feedback consent has no requester (P1-4)
ALTER TABLE consent
  ADD CONSTRAINT chk_consent_one_target CHECK (num_nonnulls(need_id, empathy_attempt_id, proposal_id, share_offer_id, review_id) = 1),
  ADD CONSTRAINT chk_consent_decision_dated CHECK ((decision IS NULL) = (decided_at IS NULL)),
  ADD CONSTRAINT chk_consent_revoked CHECK (revoked_at IS NULL OR decision = 'REVOKED'),
  ADD CONSTRAINT chk_consent_requester CHECK (requested_by_participant_id IS NULL OR target_kind IN ('NEED', 'PROPOSAL', 'EMPATHY_ATTEMPT'));
-- §1.4 need [P30]
ALTER TABLE need ADD CONSTRAINT chk_need_confidence CHECK (ai_confidence BETWEEN 0 AND 1);
-- §1.4 need_share [P20c]
ALTER TABLE need_share ADD CONSTRAINT chk_need_share_revoked_after_shared CHECK (revoked_at IS NULL OR revoked_at >= shared_at);
-- §1.4 proposal [P21]
ALTER TABLE proposal
  ADD CONSTRAINT chk_proposal_removed CHECK ((status = 'REMOVED') = (removed_at IS NOT NULL)),
  ADD CONSTRAINT chk_proposal_shared_individual CHECK (kind = 'INDIVIDUAL_COMMITMENT' OR shared_at IS NULL);
-- §1.4 proposal_revision [P23c]
ALTER TABLE proposal_revision
  ADD CONSTRAINT chk_proposal_revision_before_object CHECK (before IS NULL OR jsonb_typeof(before) = 'object'),
  ADD CONSTRAINT chk_proposal_revision_after_object CHECK (after IS NULL OR jsonb_typeof(after) = 'object');
-- §1.5 follow_up [P24a]
ALTER TABLE follow_up
  ADD CONSTRAINT chk_follow_up_individual_owner CHECK ((scope = 'INDIVIDUAL') = (owner_participant_id IS NOT NULL)),
  ADD CONSTRAINT chk_follow_up_one_subject CHECK (num_nonnulls(agreement_id, proposal_id) <= 1);
-- §1.5 follow_up_checkin
ALTER TABLE follow_up_checkin ADD CONSTRAINT chk_follow_up_checkin_payload_object CHECK (jsonb_typeof(payload) = 'object');
-- §1.6 reflection, takeaway_link [P31]
ALTER TABLE reflection ADD CONSTRAINT chk_reflection_summary_doc_object CHECK (summary_doc IS NULL OR jsonb_typeof(summary_doc) = 'object');
ALTER TABLE takeaway_link ADD CONSTRAINT chk_takeaway_link_not_self CHECK (source_id <> target_id);
-- §1.7 user — a tombstone is scrubbed (P3 D9)
ALTER TABLE "user" ADD CONSTRAINT chk_user_tombstone_scrubbed CHECK (deleted_at IS NULL OR (clerk_id IS NULL AND email LIKE 'deleted+%'));
-- §1.7 user_preferences
ALTER TABLE user_preferences ADD CONSTRAINT chk_user_preferences_doc CHECK (
  jsonb_typeof(doc) = 'object' AND doc ?& ARRAY['memory', 'notifications', 'privacy']);
-- §1.7 feature_state
ALTER TABLE feature_state
  ADD CONSTRAINT chk_feature_state_feature CHECK (feature IN ('meditation', 'gratitude', 'needs_assessment', 'people')),
  ADD CONSTRAINT chk_feature_state_doc_object CHECK (jsonb_typeof(doc) = 'object');
-- §1.8 brain_activity [P28c]
ALTER TABLE brain_activity
  ADD CONSTRAINT chk_brain_activity_input_json CHECK (input IS NULL OR jsonb_typeof(input) IN ('object', 'array')),
  ADD CONSTRAINT chk_brain_activity_output_json CHECK (output IS NULL OR jsonb_typeof(output) IN ('object', 'array')),
  ADD CONSTRAINT chk_brain_activity_metadata_json CHECK (metadata IS NULL OR jsonb_typeof(metadata) IN ('object', 'array')),
  ADD CONSTRAINT chk_brain_activity_structured_output_json CHECK (structured_output IS NULL OR jsonb_typeof(structured_output) IN ('object', 'array'));

-- ---------------------------------------------------------------------------
-- T4. app.* functions (spec §4; P3 §5).
--
-- Every SECURITY DEFINER function and every trigger function pins
-- search_path = pg_catalog, public, pg_temp (pg_temp last, so a caller's temp
-- objects can never shadow a catalog or a table) and qualifies every relation.
--
-- "Is the caller the job?" inside a SECURITY DEFINER function: current_user is
-- the owner (mwf_job), so the test reads session_user — the role that logged
-- in — and is exactly session_user IN ('mwf_job', 'mwf_migrator') (spec
-- Conventions `job`). No catalog is read and no superuser arm exists (Phase 3
-- §1: rolsuper must be false); local tooling that needs the job connects as
-- mwf_job (JOB_DATABASE_URL, docs/development/local-setup.md).
--
-- Every self-arm is NULL-safe: an unset identity (app.current_user_id() IS
-- NULL) or a modeled participant (user_id IS NULL) is never "self".
-- ---------------------------------------------------------------------------

-- Invoker helper: updated_at on every UPDATE (owner decision 2026-10-21; not moddatetime).
CREATE OR REPLACE FUNCTION app.touch_updated_at() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$ BEGIN NEW.updated_at := now(); RETURN NEW; END $$;

-- The two TS-1 helpers keep their signatures and owner (mwf_job) and are
-- re-based on participant. CREATE OR REPLACE needs the owner, so it runs as
-- mwf_job inside a short CREATE window on schema app; grants are kept.
GRANT CREATE ON SCHEMA app TO mwf_job;
SET ROLE mwf_job;

-- Does the caller have a participant row in this session? (left_at does not
-- matter: a leaver keeps reading the shared vessel; spec §1.1 participant.)
CREATE OR REPLACE FUNCTION app.is_member(session uuid) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.participant p
      WHERE p.session_id = is_member.session AND p.user_id = app.current_user_id()
    )
  $$;

-- The caller's co-participant's user id: NULL unless the caller is a
-- participant and the session has exactly two human participants (kept for
-- the two-party job paths; v_co_participant is the N-safe read).
CREATE OR REPLACE FUNCTION app.partner_user_id(session uuid) RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
    SELECT other.user_id
    FROM public.participant me
    JOIN public.participant other
      ON other.session_id = me.session_id AND other.id <> me.id AND other.kind = 'human'
    WHERE me.session_id = partner_user_id.session
      AND me.user_id = app.current_user_id()
      AND (SELECT count(*) FROM public.participant c WHERE c.session_id = me.session_id AND c.kind = 'human') = 2
  $$;

RESET ROLE;
REVOKE CREATE ON SCHEMA app FROM mwf_job;

-- Does the caller share this participant's session?
CREATE FUNCTION app.is_co_participant(participant uuid) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.participant them
      JOIN public.participant me ON me.session_id = them.session_id
      WHERE them.id = is_co_participant.participant AND me.user_id = app.current_user_id()
    )
  $$;

-- The caller's participant id in this session (NULL if none).
CREATE FUNCTION app.my_participant(session uuid) RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
    SELECT p.id FROM public.participant p
    WHERE p.session_id = my_participant.session AND p.user_id = app.current_user_id()
  $$;

-- Content-free status of every empathy direction in the caller's sessions
-- (the latest round per direction): what both parties may see while neither
-- may read an unrevealed row (P0-2). Behind v_empathy_direction_status.
CREATE FUNCTION app.empathy_direction_status()
  RETURNS TABLE (author_participant_id uuid, subject_participant_id uuid, round integer, status public.empathy_status,
                 submitted_at timestamptz, revealed_at timestamptz)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
    SELECT DISTINCT ON (a.author_participant_id, a.subject_participant_id)
           a.author_participant_id, a.subject_participant_id, a.round, a.status, a.submitted_at, a.revealed_at
    FROM public.empathy_attempt a
    JOIN public.participant au ON au.id = a.author_participant_id
    WHERE EXISTS (SELECT 1 FROM public.participant me
                  WHERE me.session_id = au.session_id AND me.user_id = app.current_user_id())
    ORDER BY a.author_participant_id, a.subject_participant_id, a.round DESC
  $$;

-- The only writer of session.status (spec §1.1 transition set). Members or
-- the job; T-cardinality-1 (trigger) still refuses → ACTIVE without two
-- participants. Locks the session row (lock order: session, then attempt).
CREATE FUNCTION app.session_set_status(session uuid, status public.session_status) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  DECLARE
    v_from public.session_status;
    v_job  boolean := session_user IN ('mwf_job', 'mwf_migrator');
  BEGIN
    SELECT s.status INTO v_from FROM public.session s WHERE s.id = session_set_status.session FOR UPDATE;
    IF NOT FOUND OR NOT (v_job OR coalesce(app.is_member(session_set_status.session), false)) THEN
      RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
    END IF;
    IF v_from = session_set_status.status THEN
      RETURN;
    END IF;
    IF NOT ((v_from, session_set_status.status) IN (
              ('CREATED'::public.session_status, 'INVITED'::public.session_status), ('INVITED', 'ACTIVE'),
              ('CREATED', 'ABANDONED'), ('INVITED', 'ABANDONED'), ('ACTIVE', 'ABANDONED'),
              ('ACTIVE', 'RESOLVED'), ('RESOLVED', 'ARCHIVED'), ('ABANDONED', 'ARCHIVED'))) THEN
      RAISE EXCEPTION 'session status % → % is not a permitted transition', v_from, session_set_status.status
        USING ERRCODE = 'check_violation';
    END IF;
    UPDATE public.session s
    SET status = session_set_status.status,
        resolved_at = CASE WHEN session_set_status.status = 'RESOLVED' THEN coalesce(s.resolved_at, now()) ELSE s.resolved_at END
    WHERE s.id = session_set_status.session;
  END
  $$;

-- The only writer of empathy_attempt.status (spec §1.2 transition table; P3 §5).
-- Actors (P3 §5: a non-author never moves a row into a disclosing state):
--   the AUTHOR (identity-bound) or the job: HELD → AWAITING_SHARING | READY,
--     AWAITING_SHARING → REFINING | READY, REFINING → READY | AWAITING_SHARING
--     (the stage2.ts in-request writers), and SUPERSEDED (resubmission);
--   the job only: READY → REVEALED, and only when the reveal gate holds;
--   the SUBJECT (identity-bound) or the job: REVEALED → VALIDATED | REFINING.
-- Anyone else: 'attempt not found'. Locks the session row, then the attempt,
-- so a concurrent resubmit of the reverse direction cannot slip between the
-- gate read and the reveal. On → REVEALED: stamps revealed_at once and writes
-- the EMPATHY_STATEMENT into the SUBJECT's MAIN conversation (the author keeps
-- their own copy); re-encrypting content under the session key is the job's,
-- in the application (keys never reach SQL). → SUPERSEDED inserts round n+1
-- (HELD) with p_content and returns its id; a retried call returns that id.
CREATE FUNCTION app.empathy_set_status(attempt uuid, status public.empathy_status, content text DEFAULT NULL) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  DECLARE
    a              public.empathy_attempt%ROWTYPE;
    v_me           uuid := app.current_user_id();
    v_job          boolean := session_user IN ('mwf_job', 'mwf_migrator');
    v_session      uuid;
    v_author_user  uuid;
    v_author_left  timestamptz;
    v_subject_user uuid;
    v_subject_left timestamptz;
    v_is_author    boolean;
    v_is_subject   boolean;
    v_gate         boolean;
    v_new          uuid;
  BEGIN
    SELECT p.session_id INTO v_session
    FROM public.empathy_attempt e JOIN public.participant p ON p.id = e.author_participant_id
    WHERE e.id = empathy_set_status.attempt;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'attempt not found' USING ERRCODE = 'P0002';
    END IF;
    PERFORM 1 FROM public.session s WHERE s.id = v_session FOR UPDATE;
    SELECT * INTO a FROM public.empathy_attempt e WHERE e.id = empathy_set_status.attempt FOR UPDATE;
    SELECT p.user_id, p.left_at INTO v_author_user, v_author_left FROM public.participant p WHERE p.id = a.author_participant_id;
    SELECT p.user_id, p.left_at INTO v_subject_user, v_subject_left FROM public.participant p WHERE p.id = a.subject_participant_id;
    v_is_author  := v_me IS NOT NULL AND v_author_user IS NOT NULL AND v_me = v_author_user;
    v_is_subject := v_me IS NOT NULL AND v_subject_user IS NOT NULL AND v_me = v_subject_user;
    IF NOT (v_job OR v_is_author OR v_is_subject) THEN
      RAISE EXCEPTION 'attempt not found' USING ERRCODE = 'P0002';
    END IF;

    IF empathy_set_status.status = 'SUPERSEDED' THEN
      IF NOT (v_job OR v_is_author) THEN
        RAISE EXCEPTION 'only the author resubmits' USING ERRCODE = 'insufficient_privilege';
      END IF;
      IF a.status = 'SUPERSEDED' THEN
        -- A retried resubmission: return the round that superseded this one.
        SELECT e.id INTO v_new FROM public.empathy_attempt e WHERE e.supersedes_attempt_id = a.id ORDER BY e.round DESC LIMIT 1;
        RETURN coalesce(v_new, a.id);
      END IF;
      IF a.status = 'VALIDATED' THEN
        RAISE EXCEPTION 'a VALIDATED attempt cannot be superseded' USING ERRCODE = 'check_violation';
      END IF;
      IF empathy_set_status.content IS NULL THEN
        RAISE EXCEPTION 'resubmission needs the new round''s content' USING ERRCODE = 'null_value_not_allowed';
      END IF;
      UPDATE public.empathy_attempt SET status = 'SUPERSEDED', status_version = status_version + 1 WHERE id = a.id;
      INSERT INTO public.empathy_attempt (author_participant_id, subject_participant_id, round, supersedes_attempt_id, content, status)
      VALUES (a.author_participant_id, a.subject_participant_id, a.round + 1, a.id, empathy_set_status.content, 'HELD')
      RETURNING id INTO v_new;
      RETURN v_new;
    END IF;

    IF a.status = empathy_set_status.status THEN
      RETURN a.id;
    END IF;

    IF (a.status, empathy_set_status.status) IN (
         ('HELD'::public.empathy_status, 'AWAITING_SHARING'::public.empathy_status), ('HELD', 'READY'),
         ('AWAITING_SHARING', 'REFINING'), ('AWAITING_SHARING', 'READY'),
         ('REFINING', 'READY'), ('REFINING', 'AWAITING_SHARING')) THEN
      IF NOT (v_job OR v_is_author) THEN
        RAISE EXCEPTION 'only the author or the job moves this attempt' USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSIF (a.status, empathy_set_status.status) = ('READY'::public.empathy_status, 'REVEALED'::public.empathy_status) THEN
      IF NOT v_job THEN
        RAISE EXCEPTION 'only the job reveals' USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSIF (a.status, empathy_set_status.status) IN (
         ('REVEALED'::public.empathy_status, 'VALIDATED'::public.empathy_status), ('REVEALED', 'REFINING')) THEN
      IF NOT (v_job OR v_is_subject) THEN
        RAISE EXCEPTION 'only the subject reviews a revealed attempt' USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSE
      RAISE EXCEPTION 'empathy status % → % is not a permitted transition', a.status, empathy_set_status.status
        USING ERRCODE = 'check_violation';
    END IF;

    IF empathy_set_status.status = 'REVEALED' THEN
      -- The reveal gate (never vacuous): author and subject are both present,
      -- and every ordered pair of present human participants has a live
      -- attempt at READY or later.
      SELECT v_author_left IS NULL AND v_subject_left IS NULL
         AND NOT EXISTS (
               SELECT 1
               FROM public.participant x
               JOIN public.participant y ON y.session_id = x.session_id AND y.id <> x.id
               WHERE x.session_id = v_session
                 AND x.kind = 'human' AND x.left_at IS NULL AND y.kind = 'human' AND y.left_at IS NULL
                 AND NOT EXISTS (SELECT 1 FROM public.empathy_attempt e
                                 WHERE e.author_participant_id = x.id AND e.subject_participant_id = y.id
                                   AND e.status IN ('READY', 'REVEALED', 'VALIDATED')))
        INTO v_gate;
      IF NOT v_gate THEN
        RAISE EXCEPTION 'reveal gate not met: every direction must be READY first' USING ERRCODE = 'check_violation';
      END IF;
      UPDATE public.empathy_attempt
      SET status = 'REVEALED', revealed_at = coalesce(revealed_at, now()), status_version = status_version + 1
      WHERE id = a.id;
      INSERT INTO public.message (conversation_id, sender_participant_id, role, kind, content, source_attempt_id)
      SELECT c.id, a.author_participant_id, 'USER', 'EMPATHY_STATEMENT', a.content, a.id
      FROM public.conversation c
      WHERE c.participant_id = a.subject_participant_id AND c.kind = 'MAIN'
        AND NOT EXISTS (SELECT 1 FROM public.message m
                        WHERE m.conversation_id = c.id AND m.source_attempt_id = a.id AND m.kind = 'EMPATHY_STATEMENT');
    ELSE
      UPDATE public.empathy_attempt SET status = empathy_set_status.status, status_version = status_version + 1 WHERE id = a.id;
    END IF;
    RETURN a.id;
  END
  $$;

-- need_share is written only here, by the job (it holds the session key that
-- encrypts shared_text; EXECUTE is the job's alone), after the owner's
-- GRANTED consent, for a need that is neither deleted nor superseded;
-- participant_id and session_id come from the need, never from the caller
-- (spec §1.4, N-1, N-7). Idempotent: a need already shared is left as it is.
CREATE FUNCTION app.need_share(need uuid, shared_text text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF NOT (session_user IN ('mwf_job', 'mwf_migrator')) THEN
      RAISE EXCEPTION 'need_share is the job''s' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.need n
                   WHERE n.id = need_share.need AND n.deleted_at IS NULL AND n.superseded_by_need_id IS NULL) THEN
      RAISE EXCEPTION 'need not found, deleted or superseded' USING ERRCODE = 'P0002';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.consent c JOIN public.need n ON n.id = c.need_id
                   WHERE c.need_id = need_share.need AND c.participant_id = n.participant_id AND c.decision = 'GRANTED') THEN
      RAISE EXCEPTION 'need has no GRANTED consent by its owner' USING ERRCODE = 'check_violation';
    END IF;
    INSERT INTO public.need_share (need_id, participant_id, session_id, category, shared_text)
    SELECT n.id, n.participant_id, p.session_id, n.category, need_share.shared_text
    FROM public.need n JOIN public.participant p ON p.id = n.participant_id
    WHERE n.id = need_share.need
    ON CONFLICT (need_id) DO NOTHING;
  END
  $$;

-- Revoke a shared need: need_share.revoked_at and the consent's REVOKED in
-- one transaction (spec §1.4). The need's owner (identity-bound) or the job.
CREATE FUNCTION app.need_revoke_share(need uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  DECLARE
    v_job boolean := session_user IN ('mwf_job', 'mwf_migrator');
    v_me  uuid := app.current_user_id();
  BEGIN
    IF NOT (v_job OR (v_me IS NOT NULL AND EXISTS (
              SELECT 1 FROM public.need n JOIN public.participant p ON p.id = n.participant_id
              WHERE n.id = need_revoke_share.need AND p.user_id = v_me))) THEN
      RAISE EXCEPTION 'need not found' USING ERRCODE = 'P0002';
    END IF;
    UPDATE public.need_share SET revoked_at = now() WHERE need_id = need_revoke_share.need AND revoked_at IS NULL;
    UPDATE public.consent SET decision = 'REVOKED', revoked_at = now()
    WHERE need_id = need_revoke_share.need AND decision = 'GRANTED';
  END
  $$;

-- app.anonymize_user_in_session(session, participant): steps 1–4 and 7
-- (participant key) of the account walk for one session (spec §4). The
-- participant's own user (identity-bound, never NULL) or the job.
CREATE FUNCTION app.anonymize_user_in_session(session uuid, participant uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  DECLARE
    v_job  boolean := session_user IN ('mwf_job', 'mwf_migrator');
    v_me   uuid := app.current_user_id();
    v_user uuid;
    pid    uuid := anonymize_user_in_session.participant;
  BEGIN
    SELECT p.user_id INTO v_user FROM public.participant p
    WHERE p.id = pid AND p.session_id = anonymize_user_in_session.session;
    IF NOT FOUND OR NOT (v_job OR coalesce(v_me IS NOT NULL AND v_user = v_me, false)) THEN
      RAISE EXCEPTION 'participant not found' USING ERRCODE = 'P0002';
    END IF;
    -- 1. a live session → ABANDONED (closes the invite-accept path; lets T-cardinality-2 accept the leave)
    IF (SELECT s.status FROM public.session s WHERE s.id = anonymize_user_in_session.session) IN ('CREATED', 'INVITED', 'ACTIVE') THEN
      PERFORM app.session_set_status(anonymize_user_in_session.session, 'ABANDONED');
    END IF;
    -- 2. the only PII a co-participant sees
    UPDATE public.participant SET display_name = NULL, left_at = coalesce(left_at, now()) WHERE id = pid;
    -- 3. the leaver's private-only rows (D9)
    DELETE FROM public.conversation WHERE participant_id = pid;           -- cascades its messages
    DELETE FROM public.conversation_read_state WHERE participant_id = pid;
    DELETE FROM public.draft WHERE participant_id = pid;
    DELETE FROM public.ai_memory WHERE participant_id = pid;
    DELETE FROM public.mood_reading WHERE participant_id = pid;
    DELETE FROM public.regulation_event WHERE participant_id = pid;
    DELETE FROM public.need_disposition WHERE participant_id = pid;
    DELETE FROM public.follow_up_note WHERE participant_id = pid;
    DELETE FROM public.need n WHERE n.participant_id = pid
      AND NOT EXISTS (SELECT 1 FROM public.need_share s WHERE s.need_id = n.id);
    DELETE FROM public.proposal_choice c WHERE c.participant_id = pid
      AND NOT EXISTS (SELECT 1 FROM public.participant_milestone m WHERE m.participant_id = pid AND m.milestone_key = 'choices_shared');
    DELETE FROM public.follow_up_checkin c USING public.follow_up f
      WHERE c.follow_up_id = f.id AND f.scope = 'INDIVIDUAL' AND c.participant_id = pid;
    DELETE FROM public.empathy_attempt WHERE author_participant_id = pid AND revealed_at IS NULL;  -- cascades results, offers, reviews
    -- 4. full prompts in plaintext
    DELETE FROM public.brain_activity WHERE participant_id = pid;
    -- 7. the participant-key shred
    UPDATE public.participant_key SET destroyed_at = now() WHERE participant_id = pid AND destroyed_at IS NULL;
  END
  $$;

-- app.anonymize_user_account(user): the complete walk (spec §4, P1-13).
-- The user themself (identity-bound, never NULL) or the job.
CREATE FUNCTION app.anonymize_user_account("user" uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  DECLARE
    v_job boolean := session_user IN ('mwf_job', 'mwf_migrator');
    v_me  uuid := app.current_user_id();
    v_uid uuid := anonymize_user_account."user";
    r     record;
  BEGIN
    IF NOT (v_job OR coalesce(v_me IS NOT NULL AND v_uid = v_me, false))
       OR NOT EXISTS (SELECT 1 FROM public."user" u WHERE u.id = v_uid) THEN
      RAISE EXCEPTION 'user not found' USING ERRCODE = 'P0002';
    END IF;
    -- 1–4, 7 (participant keys) per session
    FOR r IN SELECT p.id, p.session_id FROM public.participant p WHERE p.user_id = v_uid ORDER BY p.session_id LOOP
      PERFORM app.anonymize_user_in_session(r.session_id, r.id);
    END LOOP;
    -- 4. reflection telemetry (participant telemetry went per session)
    DELETE FROM public.brain_activity b USING public.reflection x WHERE b.reflection_id = x.id AND x.user_id = v_uid;
    -- 5. U-class material
    DELETE FROM public.reflection WHERE user_id = v_uid;          -- cascades messages, takeaways, links
    DELETE FROM public.feature_state WHERE user_id = v_uid;
    DELETE FROM public.user_memory WHERE user_id = v_uid;
    DELETE FROM public.user_device WHERE user_id = v_uid;
    DELETE FROM public.user_preferences WHERE user_id = v_uid;
    DELETE FROM public.reminder WHERE user_id = v_uid;
    DELETE FROM public.ai_memory WHERE user_id = v_uid;
    -- 6. the tombstone
    UPDATE public."user"
    SET clerk_id = NULL, email = 'deleted+' || v_uid::text, first_name = NULL, last_name = NULL, deleted_at = coalesce(deleted_at, now())
    WHERE id = v_uid;
    -- 7. the user-key shred
    UPDATE public.user_key SET destroyed_at = now() WHERE user_id = v_uid AND destroyed_at IS NULL;
  END
  $$;

-- Pre-identity bootstrap (P3 §5): resolve a Clerk id; create the user for a
-- first login (mwf_auth only, INSERT only).
CREATE FUNCTION app.resolve_user_by_clerk_id(clerk_id text) RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
    SELECT u.id FROM public."user" u WHERE u.clerk_id = resolve_user_by_clerk_id.clerk_id AND u.deleted_at IS NULL
  $$;

CREATE FUNCTION app.create_user_for_clerk(clerk_id text, email text, first_name text DEFAULT NULL, last_name text DEFAULT NULL)
  RETURNS uuid
  LANGUAGE sql SECURITY DEFINER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
    INSERT INTO public."user" (clerk_id, email, first_name, last_name)
    VALUES (create_user_for_clerk.clerk_id, create_user_for_clerk.email, create_user_for_clerk.first_name, create_user_for_clerk.last_name)
    RETURNING id
  $$;

-- Hand the definer functions to mwf_job (TS-1 order, measured there with a
-- non-superuser migrator): CREATE on the schema for the hand-over only; then
-- the EXECUTE grants issued AS mwf_job, the owner.
GRANT CREATE ON SCHEMA app TO mwf_job;
ALTER FUNCTION app.is_co_participant(uuid) OWNER TO mwf_job;
ALTER FUNCTION app.my_participant(uuid) OWNER TO mwf_job;
ALTER FUNCTION app.empathy_direction_status() OWNER TO mwf_job;
ALTER FUNCTION app.session_set_status(uuid, public.session_status) OWNER TO mwf_job;
ALTER FUNCTION app.empathy_set_status(uuid, public.empathy_status, text) OWNER TO mwf_job;
ALTER FUNCTION app.need_share(uuid, text) OWNER TO mwf_job;
ALTER FUNCTION app.need_revoke_share(uuid) OWNER TO mwf_job;
ALTER FUNCTION app.anonymize_user_in_session(uuid, uuid) OWNER TO mwf_job;
ALTER FUNCTION app.anonymize_user_account(uuid) OWNER TO mwf_job;
ALTER FUNCTION app.resolve_user_by_clerk_id(text) OWNER TO mwf_job;
ALTER FUNCTION app.create_user_for_clerk(text, text, text, text) OWNER TO mwf_job;
REVOKE CREATE ON SCHEMA app FROM mwf_job;

SET ROLE mwf_job;
REVOKE EXECUTE ON FUNCTION
  app.is_co_participant(uuid), app.my_participant(uuid), app.empathy_direction_status(),
  app.session_set_status(uuid, public.session_status), app.empathy_set_status(uuid, public.empathy_status, text),
  app.need_share(uuid, text), app.need_revoke_share(uuid),
  app.anonymize_user_in_session(uuid, uuid), app.anonymize_user_account(uuid),
  app.resolve_user_by_clerk_id(text), app.create_user_for_clerk(text, text, text, text)
  FROM PUBLIC;
-- mwf_app: the identity-bound reads and the request-path writers.
GRANT EXECUTE ON FUNCTION
  app.is_co_participant(uuid), app.my_participant(uuid), app.empathy_direction_status(),
  app.session_set_status(uuid, public.session_status), app.empathy_set_status(uuid, public.empathy_status, text),
  app.need_revoke_share(uuid), app.anonymize_user_in_session(uuid, uuid), app.anonymize_user_account(uuid),
  app.resolve_user_by_clerk_id(text)
  TO mwf_app;
-- mwf_job: its own writers when called from a job connection.
GRANT EXECUTE ON FUNCTION
  app.is_member(uuid), app.partner_user_id(uuid), app.is_co_participant(uuid), app.my_participant(uuid),
  app.empathy_direction_status(), app.session_set_status(uuid, public.session_status),
  app.empathy_set_status(uuid, public.empathy_status, text), app.need_share(uuid, text), app.need_revoke_share(uuid),
  app.anonymize_user_in_session(uuid, uuid), app.anonymize_user_account(uuid)
  TO mwf_job;
-- mwf_auth: first-login creation only (and the lookup that precedes it).
GRANT EXECUTE ON FUNCTION app.create_user_for_clerk(text, text, text, text), app.resolve_user_by_clerk_id(text) TO mwf_auth;
RESET ROLE;

-- ---------------------------------------------------------------------------
-- T5. Triggers (spec §5 "Lives only in migration SQL"; §7). Invoker rights
-- throughout — T-consent-owner must be (N-4), and the others need no more
-- than their caller can see — with search_path pinned and every relation
-- qualified, so a caller's temp table cannot stand in for a real one. No
-- caller needs EXECUTE on a trigger function (PostgreSQL checks it only at
-- CREATE TRIGGER); EXECUTE is revoked from PUBLIC below.
-- ---------------------------------------------------------------------------

-- T-cardinality-1: → ACTIVE needs ≥2 participants with ≥1 live human (D1).
CREATE FUNCTION app.t_session_cardinality() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF NEW.status = 'ACTIVE' AND OLD.status IS DISTINCT FROM 'ACTIVE'
       AND ((SELECT count(*) FROM public.participant p WHERE p.session_id = NEW.id) < 2
            OR NOT EXISTS (SELECT 1 FROM public.participant p WHERE p.session_id = NEW.id AND p.kind = 'human' AND p.left_at IS NULL)) THEN
      RAISE EXCEPTION 'a session becomes ACTIVE only with two participants, one of them a present human'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_cardinality_1 BEFORE UPDATE OF status ON public.session
  FOR EACH ROW EXECUTE FUNCTION app.t_session_cardinality();

-- T-cardinality-2 (deferred): a non-terminal session never loses its last present human.
CREATE FUNCTION app.t_participant_cardinality() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF EXISTS (SELECT 1 FROM public.session s WHERE s.id = OLD.session_id AND s.status NOT IN ('RESOLVED', 'ABANDONED', 'ARCHIVED'))
       AND NOT EXISTS (SELECT 1 FROM public.participant p WHERE p.session_id = OLD.session_id AND p.kind = 'human' AND p.left_at IS NULL) THEN
      RAISE EXCEPTION 'a live session must keep a present human participant' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
  END
  $$;
CREATE CONSTRAINT TRIGGER t_cardinality_2 AFTER DELETE OR UPDATE OF kind, user_id, left_at ON public.participant
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.t_participant_cardinality();

-- T-message-immutable: routing columns never change; content of AI/SYSTEM rows
-- and of every delivered kind never changes, except by the job (W13 re-encryption).
CREATE FUNCTION app.t_message_immutable() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF NEW.conversation_id IS DISTINCT FROM OLD.conversation_id
       OR NEW.sender_participant_id IS DISTINCT FROM OLD.sender_participant_id
       OR NEW.role IS DISTINCT FROM OLD.role
       OR NEW.kind IS DISTINCT FROM OLD.kind THEN
      RAISE EXCEPTION 'message routing is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.content IS DISTINCT FROM OLD.content AND (OLD.role IN ('AI', 'SYSTEM') OR OLD.kind <> 'CHAT')
       AND current_user NOT IN ('mwf_job', 'mwf_migrator') THEN
      RAISE EXCEPTION 'this message''s content is immutable' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_message_immutable BEFORE UPDATE ON public.message
  FOR EACH ROW EXECUTE FUNCTION app.t_message_immutable();

-- T-same-session: author and subject belong to the same session.
CREATE FUNCTION app.t_attempt_same_session() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF (SELECT p.session_id FROM public.participant p WHERE p.id = NEW.author_participant_id)
       IS DISTINCT FROM (SELECT p.session_id FROM public.participant p WHERE p.id = NEW.subject_participant_id) THEN
      RAISE EXCEPTION 'author and subject must share a session' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_same_session BEFORE INSERT OR UPDATE OF author_participant_id, subject_participant_id ON public.empathy_attempt
  FOR EACH ROW EXECUTE FUNCTION app.t_attempt_same_session();

-- T-review-subject: the reviewer of an attempt is its subject (spec §1.2 "trigger-checked").
CREATE FUNCTION app.t_review_subject() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.empathy_attempt a
                   WHERE a.id = NEW.attempt_id AND a.subject_participant_id = NEW.reviewer_participant_id) THEN
      RAISE EXCEPTION 'only the subject of an attempt reviews it' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_review_subject BEFORE INSERT OR UPDATE OF attempt_id, reviewer_participant_id ON public.empathy_review
  FOR EACH ROW EXECUTE FUNCTION app.t_review_subject();

-- T-consent-owner: the decider owns the arc target. Invoker rights, so under
-- the caller's RLS a partner's row and a missing row look the same; one fixed
-- message with no ids (N-4).
CREATE FUNCTION app.t_consent_owner() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  DECLARE
    v_owner uuid;
  BEGIN
    IF NEW.need_id IS NOT NULL THEN
      SELECT n.participant_id INTO v_owner FROM public.need n WHERE n.id = NEW.need_id;
    ELSIF NEW.empathy_attempt_id IS NOT NULL THEN
      SELECT a.author_participant_id INTO v_owner FROM public.empathy_attempt a WHERE a.id = NEW.empathy_attempt_id;
    ELSIF NEW.proposal_id IS NOT NULL THEN
      SELECT p.created_by_participant_id INTO v_owner FROM public.proposal p WHERE p.id = NEW.proposal_id;
    ELSIF NEW.share_offer_id IS NOT NULL THEN
      SELECT o.subject_participant_id INTO v_owner FROM public.context_share_offer o WHERE o.id = NEW.share_offer_id;
    ELSIF NEW.review_id IS NOT NULL THEN
      SELECT r.reviewer_participant_id INTO v_owner FROM public.empathy_review r WHERE r.id = NEW.review_id;
    END IF;
    IF v_owner IS NULL OR v_owner <> NEW.participant_id THEN
      RAISE EXCEPTION 'consent target is not yours' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_consent_owner BEFORE INSERT OR UPDATE ON public.consent
  FOR EACH ROW EXECUTE FUNCTION app.t_consent_owner();

-- T-consent-transitions: decision moves only NULL → GRANTED | DENIED,
-- GRANTED → REVOKED; decided_at moves only with the first decision and
-- revoked_at only with the revocation (both are otherwise pinned).
CREATE FUNCTION app.t_consent_transitions() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF TG_OP = 'INSERT' THEN
      IF NEW.decision = 'REVOKED' OR NEW.revoked_at IS NOT NULL THEN
        RAISE EXCEPTION 'a consent is not created revoked' USING ERRCODE = 'check_violation';
      END IF;
      RETURN NEW;
    END IF;
    IF NEW.decision IS NOT DISTINCT FROM OLD.decision THEN
      IF NEW.decided_at IS DISTINCT FROM OLD.decided_at OR NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
        RAISE EXCEPTION 'decided_at and revoked_at change only with the decision' USING ERRCODE = 'check_violation';
      END IF;
    ELSIF OLD.decision IS NULL AND NEW.decision IN ('GRANTED', 'DENIED') THEN
      IF NEW.revoked_at IS NOT NULL THEN
        RAISE EXCEPTION 'a first decision is not a revocation' USING ERRCODE = 'check_violation';
      END IF;
    ELSIF OLD.decision = 'GRANTED' AND NEW.decision = 'REVOKED' THEN
      IF NEW.decided_at IS DISTINCT FROM OLD.decided_at OR NEW.revoked_at IS NULL THEN
        RAISE EXCEPTION 'a revocation keeps decided_at and records revoked_at' USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      RAISE EXCEPTION 'consent decision % → % is not permitted', OLD.decision, NEW.decision USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_consent_transitions BEFORE INSERT OR UPDATE ON public.consent
  FOR EACH ROW EXECUTE FUNCTION app.t_consent_transitions();

-- T-need-share-owner: participant_id/session_id are the need owner's (N-1).
CREATE FUNCTION app.t_need_share_owner() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.need n JOIN public.participant p ON p.id = n.participant_id
                   WHERE n.id = NEW.need_id AND n.participant_id = NEW.participant_id AND p.session_id = NEW.session_id) THEN
      RAISE EXCEPTION 'need_share must carry its need owner''s participant and session' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_need_share_owner BEFORE INSERT OR UPDATE ON public.need_share
  FOR EACH ROW EXECUTE FUNCTION app.t_need_share_owner();

-- T-need-share-terminal: the delivered text and its pins never change;
-- revoked_at moves only NULL → value (P3 §4, re-homed).
CREATE FUNCTION app.t_need_share_terminal() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF NEW.need_id IS DISTINCT FROM OLD.need_id OR NEW.shared_text IS DISTINCT FROM OLD.shared_text
       OR NEW.participant_id IS DISTINCT FROM OLD.participant_id OR NEW.session_id IS DISTINCT FROM OLD.session_id
       OR NEW.category IS DISTINCT FROM OLD.category OR NEW.shared_at IS DISTINCT FROM OLD.shared_at
       OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at) THEN
      RAISE EXCEPTION 'a shared need is immutable; revocation is terminal' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_need_share_terminal BEFORE UPDATE ON public.need_share
  FOR EACH ROW EXECUTE FUNCTION app.t_need_share_terminal();

-- T-result-live-attempt: no result on a SUPERSEDED round; subject = the attempt's subject.
CREATE FUNCTION app.t_result_live_attempt() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.empathy_attempt a
                   WHERE a.id = NEW.attempt_id AND a.status <> 'SUPERSEDED' AND a.subject_participant_id = NEW.subject_participant_id) THEN
      RAISE EXCEPTION 'a reconciler result needs a live attempt with the same subject' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;
CREATE TRIGGER t_result_live_attempt BEFORE INSERT ON public.reconciler_result
  FOR EACH ROW EXECUTE FUNCTION app.t_result_live_attempt();

-- T-agreement-parties (deferred): at commit, the parties of an agreement are
-- exactly the session's human participants present when it was created
-- (left_at IS NULL or later than created_at — a leaver/tombstone who was
-- present stays a party, spec §4 "what survives … agreement_party"), each
-- WILLING on the proposal (D4; "what the 2-participant system does, applied
-- across N"). The predicate is app.agreement_parties_ok, used by the trigger
-- (inlined, so no caller needs EXECUTE on it) and by T8's check of the
-- migrated rows.
CREATE FUNCTION app.agreement_parties_ok(agreement uuid) RETURNS boolean
  LANGUAGE sql STABLE
  SET search_path = pg_catalog, public, pg_temp
  AS $$
    SELECT NOT EXISTS (SELECT 1 FROM public.agreement ag WHERE ag.id = agreement_parties_ok.agreement)
        OR (SELECT NOT EXISTS (SELECT ap.participant_id FROM public.agreement_party ap WHERE ap.agreement_id = ag.id
                               EXCEPT SELECT p.id FROM public.participant p
                                      WHERE p.session_id = ag.session_id AND p.kind = 'human'
                                        AND (p.left_at IS NULL OR p.left_at > ag.created_at))
               AND NOT EXISTS (SELECT p.id FROM public.participant p
                               WHERE p.session_id = ag.session_id AND p.kind = 'human'
                                 AND (p.left_at IS NULL OR p.left_at > ag.created_at)
                               EXCEPT SELECT ap.participant_id FROM public.agreement_party ap WHERE ap.agreement_id = ag.id)
               AND NOT EXISTS (SELECT 1 FROM public.agreement_party ap
                               WHERE ap.agreement_id = ag.id
                                 AND NOT EXISTS (SELECT 1 FROM public.proposal_choice c
                                                 WHERE c.proposal_id = ag.proposal_id AND c.participant_id = ap.participant_id
                                                   AND c.decision = 'WILLING'))
            FROM public.agreement ag WHERE ag.id = agreement_parties_ok.agreement)
  $$;
CREATE FUNCTION app.t_agreement_parties() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public, pg_temp
  AS $$
  DECLARE
    v_agreement uuid;
    v_ok        boolean;
  BEGIN
    -- IF, not CASE: plpgsql plans a CASE as one expression, and NEW of an
    -- agreement_party row has no id (nor any NEW on DELETE).
    IF TG_TABLE_NAME = 'agreement' THEN
      v_agreement := NEW.id;
    ELSIF TG_OP = 'DELETE' THEN
      v_agreement := OLD.agreement_id;
    ELSE
      v_agreement := NEW.agreement_id;
    END IF;
    SELECT NOT EXISTS (SELECT 1 FROM public.agreement ag WHERE ag.id = v_agreement)
        OR (SELECT NOT EXISTS (SELECT ap.participant_id FROM public.agreement_party ap WHERE ap.agreement_id = ag.id
                               EXCEPT SELECT p.id FROM public.participant p
                                      WHERE p.session_id = ag.session_id AND p.kind = 'human'
                                        AND (p.left_at IS NULL OR p.left_at > ag.created_at))
               AND NOT EXISTS (SELECT p.id FROM public.participant p
                               WHERE p.session_id = ag.session_id AND p.kind = 'human'
                                 AND (p.left_at IS NULL OR p.left_at > ag.created_at)
                               EXCEPT SELECT ap.participant_id FROM public.agreement_party ap WHERE ap.agreement_id = ag.id)
               AND NOT EXISTS (SELECT 1 FROM public.agreement_party ap
                               WHERE ap.agreement_id = ag.id
                                 AND NOT EXISTS (SELECT 1 FROM public.proposal_choice c
                                                 WHERE c.proposal_id = ag.proposal_id AND c.participant_id = ap.participant_id
                                                   AND c.decision = 'WILLING'))
            FROM public.agreement ag WHERE ag.id = v_agreement)
      INTO v_ok;
    IF NOT v_ok THEN
      RAISE EXCEPTION 'an agreement names every present participant, each WILLING' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
  END
  $$;
CREATE CONSTRAINT TRIGGER t_agreement_parties AFTER INSERT OR UPDATE OR DELETE ON public.agreement_party
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.t_agreement_parties();
CREATE CONSTRAINT TRIGGER t_agreement_parties_on_agreement AFTER INSERT ON public.agreement
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.t_agreement_parties();

-- No caller needs EXECUTE on a trigger function or on the T8 predicate.
REVOKE EXECUTE ON FUNCTION
  app.touch_updated_at(), app.t_session_cardinality(), app.t_participant_cardinality(), app.t_message_immutable(),
  app.t_attempt_same_session(), app.t_review_subject(), app.t_consent_owner(), app.t_consent_transitions(),
  app.t_need_share_owner(), app.t_need_share_terminal(), app.t_result_live_attempt(), app.t_agreement_parties(),
  app.agreement_parties_ok(uuid)
  FROM PUBLIC;

-- touch_updated_at on the 35 tables that have updated_at (T8 asserts the set
-- equals the catalog's). message and takeaway_link have none.
CREATE TRIGGER touch_updated_at BEFORE UPDATE ON agreement FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();
CREATE TRIGGER touch_updated_at BEFORE UPDATE ON ai_memory FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();
